INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u3-C1','kor',2,1,'u3',1,'꾸며 주는 말 알기 — 「넓은 밭」·「활짝 웃다」처럼 뒤에 오는 말이 어떤지·어떻게 하는지 자세하게 해 주는 말을 알고 문장에서 찾기',ARRAY['2국04-03']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u3-C2','kor',2,1,'u3',1,'꾸며 주는 말과 꾸미는 말 잇기 — 꾸며 주는 말이 문장에서 어느 말을 꾸미는지(넓은 → 옥수수밭, 활짝 → 웃으셨다) 찾아 잇기',ARRAY['2국04-03']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u3-C3','kor',2,1,'u3',1,'꾸며 주는 말을 쓰면 좋은 점 — 생각이나 느낌을 더 자세하고 생생하게 나타낼 수 있고, 읽는 사람도 모습을 또렷하게 떠올리며 재미있게 읽음을 알기',ARRAY['2국03-02']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u3-C4','kor',2,1,'u3',3,'대상에 어울리는 꾸며 주는 말 고르기 — 그림·사진의 대상을 살펴 색(노란·붉은)·모양(둥근·예쁜)·움직임(빠르게·힘차게)에 맞는 꾸며 주는 말 고르기',ARRAY['2국03-02']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u3-C5','kor',2,1,'u3',3,'꾸며 주는 말을 넣어 문장 쓰기 — 꾸며 주는 말을 알맞은 자리에 넣어 끝까지 문장을 쓰고, 한 문장에 여러 개를 넣되 뜻이 어긋나지 않게 하기',ARRAY['2국03-02']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u3-C6','kor',2,1,'u3',5,'꾸며 주는 말이 들어간 글 읽기 — 식물이 자라는 글에서 자라는 차례(씨앗 → 새싹 → 꽃 → 열매)와 모양을 나타내는 낱말(조롱조롱·올록볼록·무럭무럭)의 뜻을 알고 모습을 떠올리기',ARRAY['2국03-02']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u3-C7','kor',2,1,'u3',1,'일기의 뜻과 짜임 — 일기는 그날 겪은 일 가운데 기억하고 싶은 일을 골라 생각이나 느낌을 담아 쓰는 글이며, 날짜·요일·날씨 → 제목 → 겪은 일 → 생각이나 느낌 차례로 씀을 알기',ARRAY['2국03-04']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u3-C8','kor',2,1,'u3',7,'겪은 일에서 글감 정하기 — 하루에 한 것·본 것·들은 것을 떠올리고, 그 가운데 마음이 움직인 인상 깊은 일 하나를 골라 일기 글감으로 정하기',ARRAY['2국03-04']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u3-C9','kor',2,1,'u3',7,'일기 제목 붙이기 — 글감을 정한 뒤 무슨 일이 있었는지 한눈에 알 수 있게 내용을 잘 나타내는 제목 붙이기',ARRAY['2국03-04']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u3-C10','kor',2,1,'u3',9,'겪은 일과 생각·느낌을 자세하고 솔직하게 쓰기 — 언제·어디서·누구와 무슨 일이 있었는지 자세하게, 그때 든 생각이나 느낌은 솔직하게 쓰고, 다 쓴 일기를 스스로 점검해 고치기',ARRAY['2국03-04']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u3-C11','kor',2,1,'u3',12,'여러 가지 일기·관찰하기 — 관찰 일기·요리 일기·그림 일기의 쓰는 내용을 알고, 관찰할 때 색·모양·냄새·촉감을 살펴 꾸며 주는 말로 나타내기',ARRAY['2국03-04']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u3-C12','kor',2,1,'u3',14,'흉내 내는 말 — 빙글빙글(모양)·톡톡(소리)·보들보들(느낌)처럼 모양·소리·느낌을 흉내 내는 말을 알고, 흉내 내는 말도 뒤의 말을 생생하게 꾸며 줌을 알기',ARRAY['2국04-03']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X01','kor',2,'u3',ARRAY['K2-1-u3-C1']::text[],'꾸밈을 받는 이름 낱말(꽃·들판·강아지)을 꾸며 주는 말로 고른다','「어떤?」 「어떻게?」에 대답하는 말에 동그라미 치기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X02','kor',2,'u3',ARRAY['K2-1-u3-C2']::text[],'꾸며 주는 말이 꾸미는 말을 엉뚱하게 잇는다(넓은 → 웃었다, 활짝 → 밭)','꾸며 주는 말 바로 뒤의 말에 붙여 소리 내어 읽어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X03','kor',2,'u3',ARRAY['K2-1-u3-C3','K2-1-u3-C5']::text[],'꾸며 주는 말이 없는 밋밋한 문장이 더 생생하다고 여기거나, 좋은 점을 「글이 길어져서」로만 안다','두 문장을 읽고 어느 쪽 그림이 더 또렷하게 떠오르는지 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X04','kor',2,'u3',ARRAY['K2-1-u3-C4','K2-1-u3-C11']::text[],'대상과 어울리지 않는 꾸며 주는 말을 붙인다(시끄러운 사과·네모난 강아지)','대상을 눈앞에 그리고 색·모양·움직임 가운데 무엇이 보이는지 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X05','kor',2,'u3',ARRAY['K2-1-u3-C5']::text[],'꾸며 주는 말은 많을수록 좋다고 여겨 뜻이 어긋나거나 겹치는 말을 넣고, 한 문장에 하나만 넣을 수 있다고 여긴다','넣은 말이 모두 그 모습에 맞는지 하나씩 짚어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X06','kor',2,'u3',ARRAY['K2-1-u3-C5']::text[],'꾸며 주는 말을 넣으며 문장을 끝맺지 않거나 낱말만 늘어놓는다(노란 우산.)','「누가 어찌한다.」 끝까지 말했는지 마침표 앞을 확인하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X07','kor',2,'u3',ARRAY['K2-1-u3-C6','K2-1-u3-C10']::text[],'글에 없는 내용을 있다고 하거나 일어난 차례를 뒤바꾼다(꽃이 핀 뒤 새싹이 돋음)','글에서 그 문장을 찾아 손가락으로 짚고 앞뒤 차례 확인하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X08','kor',2,'u3',ARRAY['K2-1-u3-C6','K2-1-u3-C12']::text[],'모양을 나타내는 낱말의 뜻을 서로 바꾼다(조롱조롱 ↔ 올록볼록, 무럭무럭 ↔ 시들시들)','낱말을 소리 내어 읽으며 손으로 그 모양을 흉내 내 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X09','kor',2,'u3',ARRAY['K2-1-u3-C7','K2-1-u3-C10']::text[],'일기를 하루에 한 일을 모두 적는 글이나 생각·느낌은 없어도 되는 글로 알고, 날짜·날씨·느낌을 빠뜨린다','날짜·날씨, 제목, 겪은 일, 느낌 — 네 손가락을 접으며 확인하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X10','kor',2,'u3',ARRAY['K2-1-u3-C7']::text[],'일기 차례를 뒤바꾼다(제목을 맨 위에 두고 날짜를 맨 끝에, 느낌을 겪은 일보다 먼저)','「날짜·날씨 → 제목 → 겪은 일 → 느낌」 차례를 소리 내어 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X11','kor',2,'u3',ARRAY['K2-1-u3-C7','K2-1-u3-C11']::text[],'일기와 관계없는 것(전화번호·시간표·가격)을 일기에 꼭 들어갈 내용이나 살펴볼 점으로 고른다','「이것이 그날을 돌아보는 데 꼭 필요할까?」 묻기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X12','kor',2,'u3',ARRAY['K2-1-u3-C8']::text[],'물건·느낌을 나타내는 낱말(연필·즐거움)을 겪은 일로 여긴다','「내가 ~했다·봤다·들었다」로 말이 되는지 붙여 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X13','kor',2,'u3',ARRAY['K2-1-u3-C8']::text[],'인상 깊은 일 대신 날마다 똑같은 일이나 하루 일을 모두 글감으로 고른다','「오늘 가장 마음이 움직인 일 하나는?」 하고 묻기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X14','kor',2,'u3',ARRAY['K2-1-u3-C9']::text[],'무슨 일이 있었는지 드러나지 않는 제목(오늘 날씨·그냥 하루·일기)을 고른다','제목만 듣고 무슨 일인지 떠오르는지 물어보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X15','kor',2,'u3',ARRAY['K2-1-u3-C10']::text[],'한 일만 늘어놓고 생각·느낌을 빼거나, 겪은 일과 맞지 않는 느낌·남의 느낌을 쓴다','「그때 내 마음은 어땠지? 왜?」를 한 줄 더하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X16','kor',2,'u3',ARRAY['K2-1-u3-C10']::text[],'언제·어디서·누구와를 빠뜨려 무슨 일인지 자세하게 드러나지 않게 쓴다','「언제? 어디서? 누구와?」 세 물음에 답이 있는지 확인하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X17','kor',2,'u3',ARRAY['K2-1-u3-C11']::text[],'관찰할 수 없는 것(가격·만든 사람)을 관찰할 점으로 고르거나, 일기 종류와 쓰는 내용을 바꾸어 잇는다','눈·코·손으로 알 수 있는 것인지 먼저 묻기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X18','kor',2,'u3',ARRAY['K2-1-u3-C12']::text[],'흉내 내는 말이 아닌 낱말(바람개비·돌다·예쁜)을 흉내 내는 말로 여기거나 모양·소리·느낌 흉내를 헷갈린다','따라 했을 때 모습·소리·느낌이 떠오르는지 소리 내어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u3-X19','kor',2,'u3',ARRAY['K2-1-u3-C1','K2-1-u3-C2','K2-1-u3-C4','K2-1-u3-C5','K2-1-u3-C6','K2-1-u3-C7','K2-1-u3-C8','K2-1-u3-C9','K2-1-u3-C10','K2-1-u3-C11','K2-1-u3-C12']::text[],'묻는 말을 거꾸로 읽는다 — 아닌↔맞는, 어울리지 않는↔어울리는, 빠진↔들어간','물음의 「아닌·않는·빠진」에 동그라미를 치고 답을 넣어 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L01_basic#1','kor',2,1,'u3','L01','g2_1_kor_u3_L01_basic','lesson_basic','K2-1-u3-C1',1,'mc','auto','「넓은 운동장」에서 꾸며 주는 말은 어느 것인가요?',ARRAY['K2-1-u3-X01']::text[],true,'{"seq":1,"concept":"K2-1-u3-C1","difficulty":1,"kind":"mc","stem":"「넓은 운동장」에서 꾸며 주는 말은 어느 것인가요?","options":[{"t":"넓은","correct":true},{"t":"운동장","mis":"K2-1-u3-X01"},{"t":"넓은 운동장","mis":"K2-1-u3-X01"}],"explanation":["「넓은」이 운동장이 어떤지 알려 줘요.","「운동장」은 꾸밈을 받는 말이에요.","「어떤 운동장?」에 대답하는 말을 찾아요."],"variant_rule":{"alt":[{"stem":"「예쁜 꽃」에서 꾸며 주는 말은 어느 것인가요?","options":[{"t":"예쁜","correct":true},{"t":"꽃","mis":"K2-1-u3-X01"},{"t":"예쁜 꽃","mis":"K2-1-u3-X01"}],"explanation":["「예쁜」이 꽃이 어떤지 알려 줘요.","「꽃」은 꾸밈을 받는 말이에요.","「어떤 꽃?」에 대답하는 말을 찾아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L01_basic#2','kor',2,1,'u3','L01','g2_1_kor_u3_L01_basic','lesson_basic','K2-1-u3-C1',1,'mc','auto','다음 문장에서 꾸며 주는 말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L01_basic#3','kor',2,1,'u3','L01','g2_1_kor_u3_L01_basic','lesson_basic','K2-1-u3-C7',1,'mc','auto','일기는 어떤 글인가요?',ARRAY['K2-1-u3-X09']::text[],true,'{"seq":3,"concept":"K2-1-u3-C7","difficulty":1,"kind":"mc","stem":"일기는 어떤 글인가요?","options":[{"t":"그날 겪은 일 가운데 기억하고 싶은 일과 생각이나 느낌을 쓴 글","correct":true},{"t":"하루에 한 일을 모두 차례대로 적은 글","mis":"K2-1-u3-X09"},{"t":"내일 할 일을 미리 적어 두는 글","mis":"K2-1-u3-X09"}],"explanation":["일기는 겪은 일 가운데 기억하고 싶은 일을 골라 써요.","한 일을 모두 적거나 내일 할 일을 쓰는 글이 아니에요.","그 일에 대한 생각이나 느낌도 함께 써요."],"variant_rule":{"alt":[{"stem":"일기에 꼭 함께 쓰는 것은 어느 것인가요?","options":[{"t":"겪은 일에 대한 생각이나 느낌","correct":true},{"t":"친구의 전화번호","mis":"K2-1-u3-X11"},{"t":"내일 시간표","mis":"K2-1-u3-X11"}],"explanation":["일기에는 겪은 일과 그때의 생각이나 느낌을 써요.","전화번호나 시간표는 그날을 돌아보는 내용이 아니에요.","그래서 일기를 읽으면 그날 마음이 떠올라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L01_basic#4','kor',2,1,'u3','L01','g2_1_kor_u3_L01_basic','lesson_basic','K2-1-u3-C3',1,'ox','auto','「비가 내린다.」보다 「비가 주룩주룩 세차게 내린다.」가 더 생생하게 느껴져요.',ARRAY['K2-1-u3-X03']::text[],true,'{"seq":4,"concept":"K2-1-u3-C3","difficulty":1,"kind":"ox","stem":"「비가 내린다.」보다 「비가 주룩주룩 세차게 내린다.」가 더 생생하게 느껴져요.","answer":"O","reason_options":[{"t":"꾸며 주는 말이 비 내리는 모습을 그려 주니까","correct":true},{"t":"글자가 많을수록 좋은 문장이니까","mis":"K2-1-u3-X03"}],"mis":"K2-1-u3-X03","explanation":["「주룩주룩」·「세차게」가 비 내리는 모습을 또렷하게 보여 줘요.","길어서가 아니라 모습이 떠올라서 생생한 거예요.","꾸며 주는 말은 문장을 자세하게 해 줘요."],"variant_rule":{"alt":[{"stem":"「꽃이 피었다.」가 「예쁜 꽃이 활짝 피었다.」보다 더 생생해요.","answer":"X","reason_options":[{"t":"꾸며 주는 말이 있는 쪽이 모습을 더 잘 그려 주니까","correct":true},{"t":"짧은 문장이 언제나 더 좋으니까","mis":"K2-1-u3-X03"}],"explanation":["「예쁜」·「활짝」이 꽃의 모습을 보여 줘요.","꾸며 주는 말이 없으면 어떤 꽃인지 알 수 없어요.","그래서 꾸며 주는 말이 있는 쪽이 더 생생해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L01_basic#5','kor',2,1,'u3','L01','g2_1_kor_u3_L01_basic','lesson_basic','K2-1-u3-C2',2,'match','auto','꾸며 주는 말과 꾸밈을 받는 말을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u3-C2","difficulty":2,"kind":"match","stem":"꾸며 주는 말과 꾸밈을 받는 말을 알맞게 이어 보세요.","pairs":[{"l":"넓은","r":"옥수수밭"},{"l":"활짝","r":"웃으셨다"},{"l":"예쁜","r":"꽃"}],"mis":"K2-1-u3-X02","explanation":["「넓은」은 옥수수밭이 어떤지 꾸며요.","「활짝」은 어떻게 웃으셨는지 꾸며요.","「예쁜」은 꽃이 어떤지 꾸며요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 꾸며 주는 말과 꾸밈을 받는 말을 알맞게 이어 보세요.","pairs":[{"l":"빠르게","r":"달린다"},{"l":"커다란","r":"코끼리"},{"l":"맛있게","r":"먹었다"}],"explanation":["「빠르게」는 어떻게 달리는지 꾸며요.","「커다란」은 코끼리가 어떤지 꾸며요.","「맛있게」는 어떻게 먹었는지 꾸며요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L01_basic#6','kor',2,1,'u3','L01','g2_1_kor_u3_L01_basic','lesson_basic','K2-1-u3-C2',2,'mc','auto','「나는 맛있게 딸기를 먹었다.」에서 「맛있게」가 꾸며 주는 말은 어느 것인가요?',ARRAY['K2-1-u3-X02']::text[],true,'{"seq":6,"concept":"K2-1-u3-C2","difficulty":2,"kind":"mc","stem":"「나는 맛있게 딸기를 먹었다.」에서 「맛있게」가 꾸며 주는 말은 어느 것인가요?","options":[{"t":"먹었다","correct":true},{"t":"나는","mis":"K2-1-u3-X02"},{"t":"딸기를","mis":"K2-1-u3-X02"}],"explanation":["「맛있게」는 어떻게 먹었는지 알려 줘요.","「맛있게 나는」, 「맛있게 딸기」는 어색해요.","꾸며 주는 말을 붙여 읽어 보면 짝이 보여요."],"variant_rule":{"alt":[{"stem":"「동생이 큰 소리로 노래를 불렀다.」에서 「큰」이 꾸며 주는 말은 어느 것인가요?","options":[{"t":"소리","correct":true},{"t":"동생이","mis":"K2-1-u3-X02"},{"t":"불렀다","mis":"K2-1-u3-X02"}],"explanation":["「큰」은 소리가 어떤지 알려 줘요.","「큰 동생」, 「큰 불렀다」가 아니라 「큰 소리」예요.","바로 뒤의 말에 붙여 읽어 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L01_basic#7','kor',2,1,'u3','L01','g2_1_kor_u3_L01_basic','lesson_basic','K2-1-u3-C1',2,'sa','auto','「하얀 구름이 둥실둥실 떠간다.」에서 「구름」을 꾸며 주는 말을 찾아 써 보세요.','{}'::text[],true,'{"seq":7,"concept":"K2-1-u3-C1","difficulty":2,"kind":"sa","stem":"「하얀 구름이 둥실둥실 떠간다.」에서 「구름」을 꾸며 주는 말을 찾아 써 보세요.","answer":["하얀"],"explanation":["「하얀」이 구름이 어떤지 알려 줘요.","「둥실둥실」은 어떻게 떠가는지 꾸며요.","무엇을 꾸미는지 바로 뒤의 말을 봐요."],"variant_rule":{"alt":[{"stem":"「작은 새가 높이 날아간다.」에서 「새」를 꾸며 주는 말을 찾아 써 보세요.","answer":["작은"],"explanation":["「작은」이 새가 어떤지 알려 줘요.","「높이」는 어떻게 날아가는지 꾸며요.","무엇을 꾸미는지 바로 뒤의 말을 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L01_basic#8','kor',2,1,'u3','L01','g2_1_kor_u3_L01_basic','lesson_basic','K2-1-u3-C3',2,'mc','auto','꾸며 주는 말을 쓰면 좋은 점은 어느 것인가요?',ARRAY['K2-1-u3-X03']::text[],true,'{"seq":8,"concept":"K2-1-u3-C3","difficulty":2,"kind":"mc","stem":"꾸며 주는 말을 쓰면 좋은 점은 어느 것인가요?","options":[{"t":"생각이나 느낌을 더 자세하고 생생하게 나타낼 수 있어요","correct":true},{"t":"글자 수가 많아져 공책이 금방 채워져요","mis":"K2-1-u3-X03"},{"t":"어려운 말을 써서 멋있어 보여요","mis":"K2-1-u3-X03"}],"explanation":["꾸며 주는 말은 모습과 느낌을 자세하게 보여 줘요.","길어지거나 어려워 보이는 것이 좋은 점은 아니에요.","읽는 사람도 더 재미있게 느껴요."],"variant_rule":{"alt":[{"stem":"꾸며 주는 말을 넣은 글을 읽으면 어떤 점이 좋을까요?","options":[{"t":"그 모습이 눈앞에 그려지듯 떠올라요","correct":true},{"t":"읽는 시간이 오래 걸려요","mis":"K2-1-u3-X03"},{"t":"무슨 뜻인지 알 수 없어져요","mis":"K2-1-u3-X03"}],"explanation":["꾸며 주는 말이 있으면 모습이 또렷해져요.","읽는 시간이 늘어나는 것이 좋은 점은 아니에요.","그래서 글이 더 재미있게 느껴져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L01_basic#9','kor',2,1,'u3','L01','g2_1_kor_u3_L01_basic','lesson_basic','K2-1-u3-C7',2,'ox','auto','일기에는 그날 있었던 일을 하나도 빠짐없이 모두 써야 해요.',ARRAY['K2-1-u3-X09']::text[],true,'{"seq":9,"concept":"K2-1-u3-C7","difficulty":2,"kind":"ox","stem":"일기에는 그날 있었던 일을 하나도 빠짐없이 모두 써야 해요.","answer":"X","reason_options":[{"t":"기억하고 싶은 일을 골라 쓰는 글이니까","correct":true},{"t":"일어난 일은 모두 중요하니까","mis":"K2-1-u3-X09"}],"mis":"K2-1-u3-X09","explanation":["일기는 하루 가운데 기억하고 싶은 일을 골라 써요.","모두 쓰면 무엇이 마음에 남았는지 드러나지 않아요.","고른 일에 생각이나 느낌을 담아요."],"variant_rule":{"alt":[{"stem":"일기에는 겪은 일에 대한 나의 생각이나 느낌을 써요.","answer":"O","reason_options":[{"t":"일기는 겪은 일과 생각·느낌을 담는 글이니까","correct":true},{"t":"생각이나 느낌은 없어도 되니까","mis":"K2-1-u3-X09"}],"explanation":["일기에는 겪은 일과 생각이나 느낌을 함께 써요.","느낌이 빠지면 그날의 내 마음이 남지 않아요.","그래서 일기를 다시 읽으면 그날이 떠올라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L01_basic#10','kor',2,1,'u3','L01','g2_1_kor_u3_L01_basic','lesson_basic','K2-1-u3-C1',3,'error','auto','「활짝 핀 예쁜 꽃이 넓은 들판에 가득해요.」에서 꾸며 주는 말을 찾았어요. 잘못 찾은 친구는 누구인가요?',ARRAY['K2-1-u3-X01','K2-1-u3-X19']::text[],true,'{"seq":10,"concept":"K2-1-u3-C1","difficulty":3,"kind":"error","stem":"「활짝 핀 예쁜 꽃이 넓은 들판에 가득해요.」에서 꾸며 주는 말을 찾았어요. 잘못 찾은 친구는 누구인가요?","options":[{"t":"하린 — 「들판」","correct":true,"mis_target":"K2-1-u3-X01"},{"t":"도윤 — 「활짝」","mis":"K2-1-u3-X19"},{"t":"서아 — 「넓은」","mis":"K2-1-u3-X19"}],"explanation":["「들판」은 꾸밈을 받는 말이에요.","「활짝」·「예쁜」·「넓은」이 꾸며 주는 말이에요.","도윤이와 서아는 바르게 찾았어요."],"variant_rule":{"alt":[{"stem":"「귀여운 강아지가 푸른 잔디밭을 신나게 뛰어요.」에서 꾸며 주는 말을 찾았어요. 잘못 찾은 친구는 누구인가요?","options":[{"t":"민호 — 「강아지」","correct":true,"mis_target":"K2-1-u3-X01"},{"t":"지안 — 「푸른」","mis":"K2-1-u3-X19"},{"t":"예린 — 「신나게」","mis":"K2-1-u3-X19"}],"explanation":["「강아지」는 꾸밈을 받는 말이에요.","「귀여운」·「푸른」·「신나게」가 꾸며 주는 말이에요.","지안이와 예린이는 바르게 찾았어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L01_challenge#1','kor',2,1,'u3','L01','g2_1_kor_u3_L01_challenge','lesson_challenge','K2-1-u3-C1',2,'mc','auto','다음 문장에서 꾸며 주는 말만 모은 것은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L01_challenge#2','kor',2,1,'u3','L01','g2_1_kor_u3_L01_challenge','lesson_challenge','K2-1-u3-C7',2,'mc','auto','일기에 들어가는 것을 바르게 모은 것은 어느 것인가요?',ARRAY['K2-1-u3-X09','K2-1-u3-X11']::text[],false,'{"seq":2,"concept":"K2-1-u3-C7","difficulty":2,"kind":"mc","stem":"일기에 들어가는 것을 바르게 모은 것은 어느 것인가요?","options":[{"t":"날짜와 날씨 · 제목 · 겪은 일 · 생각이나 느낌","correct":true},{"t":"날짜와 날씨 · 제목 · 겪은 일","mis":"K2-1-u3-X09"},{"t":"제목 · 겪은 일 · 친구 전화번호","mis":"K2-1-u3-X11"}],"explanation":["일기에는 날짜와 날씨, 제목, 겪은 일, 생각이나 느낌이 들어가요.","생각이나 느낌이 빠지면 일기가 아쉬워요.","전화번호는 일기 내용이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L01_challenge#3','kor',2,1,'u3','L01','g2_1_kor_u3_L01_challenge','lesson_challenge','K2-1-u3-C2',3,'mc','auto','「키 큰 해바라기가 노랗게 활짝 피었다.」에서 「노랗게」가 꾸며 주는 말은 어느 것인가요?',ARRAY['K2-1-u3-X02']::text[],false,'{"seq":3,"concept":"K2-1-u3-C2","difficulty":3,"kind":"mc","stem":"「키 큰 해바라기가 노랗게 활짝 피었다.」에서 「노랗게」가 꾸며 주는 말은 어느 것인가요?","options":[{"t":"피었다","correct":true},{"t":"해바라기가","mis":"K2-1-u3-X02"},{"t":"활짝","mis":"K2-1-u3-X02"}],"explanation":["「노랗게」는 어떻게 피었는지 알려 줘요.","「노랗게 해바라기」는 어색해요.","꾸며 주는 말을 붙여 읽어 보면 짝이 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L01_challenge#4','kor',2,1,'u3','L01','g2_1_kor_u3_L01_challenge','lesson_challenge','K2-1-u3-C2',3,'error','auto','「귀여운 동생이 새 신발을 신고 깡충깡충 뛰었다.」에서 꾸며 주는 말과 꾸밈을 받는 말을 이었어요. 잘못 이은 친구는 누구인가요?',ARRAY['K2-1-u3-X02','K2-1-u3-X19']::text[],false,'{"seq":4,"concept":"K2-1-u3-C2","difficulty":3,"kind":"error","stem":"「귀여운 동생이 새 신발을 신고 깡충깡충 뛰었다.」에서 꾸며 주는 말과 꾸밈을 받는 말을 이었어요. 잘못 이은 친구는 누구인가요?","options":[{"t":"시우 — 「귀여운 → 신발」","correct":true,"mis_target":"K2-1-u3-X02"},{"t":"다은 — 「새 → 신발」","mis":"K2-1-u3-X19"},{"t":"로아 — 「깡충깡충 → 뛰었다」","mis":"K2-1-u3-X19"}],"explanation":["「귀여운」은 동생을 꾸며요.","「새」는 신발을, 「깡충깡충」은 뛰었다를 꾸며요.","다은이와 로아는 바르게 이었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L01_challenge#5','kor',2,1,'u3','L01','g2_1_kor_u3_L01_challenge','lesson_challenge','K2-1-u3-C3',3,'mc','auto','두 문장 가운데 그날 모습이 더 잘 떠오르는 문장과 그 까닭을 바르게 말한 것은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L01_challenge#6','kor',2,1,'u3','L01','g2_1_kor_u3_L01_challenge','lesson_challenge','K2-1-u3-C1',3,'ox','auto','「코끼리」와 「커다란 하얀 코끼리」를 견주면, 「커다란」과 「하얀」은 모두 코끼리를 꾸며 주는 말이에요.',ARRAY['K2-1-u3-X01']::text[],false,'{"seq":6,"concept":"K2-1-u3-C1","difficulty":3,"kind":"ox","stem":"「코끼리」와 「커다란 하얀 코끼리」를 견주면, 「커다란」과 「하얀」은 모두 코끼리를 꾸며 주는 말이에요.","answer":"O","reason_options":[{"t":"두 말 모두 코끼리가 어떤지 알려 주니까","correct":true},{"t":"「코끼리」만 꾸며 주는 말이니까","mis":"K2-1-u3-X01"}],"mis":"K2-1-u3-X01","explanation":["「커다란」은 크기를, 「하얀」은 색을 알려 줘요.","두 말이 모두 코끼리를 꾸며요.","꾸며 주는 말은 여러 개 붙을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L01_challenge#7','kor',2,1,'u3','L01','g2_1_kor_u3_L01_challenge','lesson_challenge','K2-1-u3-C7',3,'mc','auto','친구들이 일기에 대해 말했어요. 바르게 말한 것은 어느 것인가요?',ARRAY['K2-1-u3-X13','K2-1-u3-X09']::text[],false,'{"seq":7,"concept":"K2-1-u3-C7","difficulty":3,"kind":"mc","stem":"친구들이 일기에 대해 말했어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"「작은 일이라도 마음이 움직였다면 일기로 쓸 수 있어.」","correct":true},{"t":"「특별한 여행을 간 날에만 일기를 쓸 수 있어.」","mis":"K2-1-u3-X13"},{"t":"「느낌은 빼고 한 일만 쓰면 돼.」","mis":"K2-1-u3-X09"}],"explanation":["작은 일이라도 기억하고 싶은 일이면 좋은 글감이에요.","특별한 날만 쓰는 글이 아니에요.","생각이나 느낌도 꼭 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L01_challenge#8','kor',2,1,'u3','L01','g2_1_kor_u3_L01_challenge','lesson_challenge','K2-1-u3-C3',4,'mc','auto','준우가 쓴 글이에요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L01_challenge#9','kor',2,1,'u3','L01','g2_1_kor_u3_L01_challenge','lesson_challenge','K2-1-u3-C1',4,'essay','teacher','「강아지가 달린다.」에 꾸며 주는 말을 두 개 넣어 더 생생한 문장으로 고쳐 쓰고, 넣은 꾸며 주는 말에 밑줄을 그어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u3-C1","difficulty":4,"kind":"essay","stem":"「강아지가 달린다.」에 꾸며 주는 말을 두 개 넣어 더 생생한 문장으로 고쳐 쓰고, 넣은 꾸며 주는 말에 밑줄을 그어 보세요.","answer_guide":{"answer":"예: 귀여운 강아지가 빠르게 달린다. (밑줄: 귀여운, 빠르게)","scoring_points":["꾸며 주는 말을 두 개 넣었는가","넣은 말이 강아지나 달리는 모습에 어울리는가","문장을 끝까지 쓰고 마침표를 찍었는가"]},"explanation":["꾸며 주는 말 두 개.","어울리는 말.","끝까지 쓴 문장."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L01_challenge#10','kor',2,1,'u3','L01','g2_1_kor_u3_L01_challenge','lesson_challenge','K2-1-u3-C7',4,'essay','teacher','일기가 어떤 글인지 쓰고, 일기에 꼭 들어가야 할 것을 두 가지 이상 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u3-C7","difficulty":4,"kind":"essay","stem":"일기가 어떤 글인지 쓰고, 일기에 꼭 들어가야 할 것을 두 가지 이상 써 보세요.","answer_guide":{"answer":"예: 일기는 그날 겪은 일 가운데 기억하고 싶은 일을 골라 생각이나 느낌을 쓴 글이에요. 날짜와 날씨, 제목, 겪은 일, 생각이나 느낌이 들어가요.","scoring_points":["일기가 겪은 일 가운데 고른 일을 쓰는 글임을 썼는가","생각이나 느낌을 담는다는 것을 썼는가","일기에 들어갈 것을 두 가지 이상 썼는가"]},"explanation":["일기의 뜻.","생각이나 느낌.","들어갈 것 두 가지."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L03_basic#1','kor',2,1,'u3','L03','g2_1_kor_u3_L03_basic','lesson_basic','K2-1-u3-C4',1,'mc','auto','사과 그림을 보고 꾸며 주는 말을 넣으려고 해요. 사과에 어울리는 말은 어느 것인가요?',ARRAY['K2-1-u3-X04']::text[],true,'{"seq":1,"concept":"K2-1-u3-C4","difficulty":1,"kind":"mc","stem":"사과 그림을 보고 꾸며 주는 말을 넣으려고 해요. 사과에 어울리는 말은 어느 것인가요?","options":[{"t":"붉은","correct":true},{"t":"시끄러운","mis":"K2-1-u3-X04"},{"t":"졸린","mis":"K2-1-u3-X04"}],"explanation":["사과의 색을 보면 「붉은」이 어울려요.","사과는 시끄럽거나 졸리지 않아요.","대상의 색·모양을 살펴 어울리는 말을 골라요."],"asset":{"type":"scene","icon":"🍎"},"variant_rule":{"alt":[{"stem":"바나나 그림을 보고 꾸며 주는 말을 넣으려고 해요. 바나나에 어울리는 말은 어느 것인가요?","options":[{"t":"노란","correct":true},{"t":"파란","mis":"K2-1-u3-X04"},{"t":"네모난","mis":"K2-1-u3-X04"}],"explanation":["바나나의 색을 보면 「노란」이 어울려요.","바나나는 파랗거나 네모나지 않아요.","대상을 잘 살펴 어울리는 말을 골라요."],"asset":{"type":"scene","icon":"🍌"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L03_basic#2','kor',2,1,'u3','L03','g2_1_kor_u3_L03_basic','lesson_basic','K2-1-u3-C4',1,'mc','auto','「(     ) 우산을 쓴다.」에서 우산의 색을 나타내는 꾸며 주는 말은 어느 것인가요?',ARRAY['K2-1-u3-X04']::text[],true,'{"seq":2,"concept":"K2-1-u3-C4","difficulty":1,"kind":"mc","stem":"「(     ) 우산을 쓴다.」에서 우산의 색을 나타내는 꾸며 주는 말은 어느 것인가요?","options":[{"t":"노란","correct":true},{"t":"예쁜","mis":"K2-1-u3-X04"},{"t":"빠르게","mis":"K2-1-u3-X04"}],"explanation":["「노란」은 우산의 색을 나타내요.","「예쁜」은 모양, 「빠르게」는 움직임을 나타내요.","무엇에 초점을 두는지에 따라 고르는 말이 달라요."],"variant_rule":{"alt":[{"stem":"「(     ) 공이 굴러간다.」에서 공의 모양을 나타내는 꾸며 주는 말은 어느 것인가요?","options":[{"t":"둥근","correct":true},{"t":"빨간","mis":"K2-1-u3-X04"},{"t":"천천히","mis":"K2-1-u3-X04"}],"explanation":["「둥근」은 공의 모양을 나타내요.","「빨간」은 색, 「천천히」는 움직임을 나타내요.","무엇에 초점을 두는지에 따라 고르는 말이 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L03_basic#3','kor',2,1,'u3','L03','g2_1_kor_u3_L03_basic','lesson_basic','K2-1-u3-C5',1,'mc','auto','꾸며 주는 말을 넣어 문장을 바르게 쓴 것은 어느 것인가요?',ARRAY['K2-1-u3-X06','K2-1-u3-X03']::text[],true,'{"seq":3,"concept":"K2-1-u3-C5","difficulty":1,"kind":"mc","stem":"꾸며 주는 말을 넣어 문장을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"커다란 배가 빠르게 나아간다.","correct":true},{"t":"커다란 배.","mis":"K2-1-u3-X06"},{"t":"배가 나아간다.","mis":"K2-1-u3-X03"}],"explanation":["「커다란」·「빠르게」를 넣어 끝까지 쓴 문장이에요.","「커다란 배.」는 무엇을 하는지 끝맺지 않았어요.","「배가 나아간다.」에는 꾸며 주는 말이 없어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 꾸며 주는 말을 넣어 문장을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"예쁜 나비가 훨훨 날아간다.","correct":true},{"t":"예쁜 나비.","mis":"K2-1-u3-X06"},{"t":"나비가 날아간다.","mis":"K2-1-u3-X03"}],"explanation":["「예쁜」·「훨훨」을 넣어 끝까지 쓴 문장이에요.","「예쁜 나비.」는 무엇을 하는지 끝맺지 않았어요.","「나비가 날아간다.」에는 꾸며 주는 말이 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L03_basic#4','kor',2,1,'u3','L03','g2_1_kor_u3_L03_basic','lesson_basic','K2-1-u3-C5',1,'ox','auto','꾸며 주는 말은 한 문장에 여러 개 넣을 수 있어요.',ARRAY['K2-1-u3-X05']::text[],true,'{"seq":4,"concept":"K2-1-u3-C5","difficulty":1,"kind":"ox","stem":"꾸며 주는 말은 한 문장에 여러 개 넣을 수 있어요.","answer":"O","reason_options":[{"t":"「멋있는 말이 힘차게 달려온다.」처럼 넣을 수 있으니까","correct":true},{"t":"한 문장에는 하나만 넣어야 하니까","mis":"K2-1-u3-X05"}],"mis":"K2-1-u3-X05","explanation":["「멋있는」은 말을, 「힘차게」는 달려온다를 꾸며요.","한 문장에 꾸며 주는 말이 여러 개 들어갈 수 있어요.","어울리게 넣는 것이 중요해요."],"variant_rule":{"alt":[{"stem":"꾸며 주는 말은 한 문장에 하나만 넣어야 해요.","answer":"X","reason_options":[{"t":"어울리면 여러 개를 넣어도 되니까","correct":true},{"t":"두 개를 넣으면 틀린 문장이니까","mis":"K2-1-u3-X05"}],"explanation":["「두 명의 아이가 종이비행기를 힘껏 멀리 날린다.」처럼 여러 개를 넣을 수 있어요.","「힘껏」·「멀리」가 함께 날리는 모습을 꾸며요.","어울리게 넣으면 더 생생해져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L03_basic#5','kor',2,1,'u3','L03','g2_1_kor_u3_L03_basic','lesson_basic','K2-1-u3-C4',2,'match','auto','모습과 어울리는 꾸며 주는 말을 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u3-C4","difficulty":2,"kind":"match","stem":"모습과 어울리는 꾸며 주는 말을 이어 보세요.","pairs":[{"l":"달리는 말","r":"힘차게"},{"l":"치는 파도","r":"거센"},{"l":"피는 꽃","r":"활짝"}],"mis":"K2-1-u3-X04","explanation":["말이 달리는 모습에는 「힘차게」가 어울려요.","파도에는 「거센」이 어울려요.","꽃이 피는 모습에는 「활짝」이 어울려요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 모습과 어울리는 꾸며 주는 말을 이어 보세요.","pairs":[{"l":"떠가는 구름","r":"둥실둥실"},{"l":"내리는 눈","r":"펑펑"},{"l":"빛나는 별","r":"반짝반짝"}],"explanation":["구름이 떠가는 모습에는 「둥실둥실」이 어울려요.","눈이 많이 내리는 모습에는 「펑펑」이 어울려요.","별이 빛나는 모습에는 「반짝반짝」이 어울려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L03_basic#6','kor',2,1,'u3','L03','g2_1_kor_u3_L03_basic','lesson_basic','K2-1-u3-C4',2,'blank','auto','달리는 강아지를 설명하는 문장이에요. 빈칸에 들어갈 말로 가장 알맞은 것은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L03_basic#7','kor',2,1,'u3','L03','g2_1_kor_u3_L03_basic','lesson_basic','K2-1-u3-C5',2,'sa','auto','「(     ) 사과를 먹었다.」 빈칸에 사과의 모양을 나타내는 꾸며 주는 말을 한 낱말로 써 보세요.','{}'::text[],true,'{"seq":7,"concept":"K2-1-u3-C5","difficulty":2,"kind":"sa","stem":"「(     ) 사과를 먹었다.」 빈칸에 사과의 모양을 나타내는 꾸며 주는 말을 한 낱말로 써 보세요.","answer":["둥근","동그란","둥그런","동글동글한"],"explanation":["사과의 모양은 「둥근」, 「동그란」 같은 말로 나타내요.","「붉은」은 색을 나타내는 말이에요.","모양을 살펴 어울리는 말을 넣어요."],"variant_rule":{"alt":[{"stem":"「(     ) 하늘을 보았다.」 빈칸에 하늘의 색을 나타내는 꾸며 주는 말을 한 낱말로 써 보세요.","answer":["파란","푸른","새파란","파아란"],"explanation":["하늘의 색은 「파란」, 「푸른」 같은 말로 나타내요.","색에 초점을 두고 떠올려요.","어울리는 꾸며 주는 말을 넣으면 문장이 생생해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L03_basic#8','kor',2,1,'u3','L03','g2_1_kor_u3_L03_basic','lesson_basic','K2-1-u3-C5',2,'mc','auto','「두 명의 아이가 종이비행기를 날린다.」에 꾸며 주는 말을 넣어 더 생생하게 고친 것은 어느 것인가요?',ARRAY['K2-1-u3-X05','K2-1-u3-X06']::text[],true,'{"seq":8,"concept":"K2-1-u3-C5","difficulty":2,"kind":"mc","stem":"「두 명의 아이가 종이비행기를 날린다.」에 꾸며 주는 말을 넣어 더 생생하게 고친 것은 어느 것인가요?","options":[{"t":"두 명의 아이가 종이비행기를 힘껏 멀리 날린다.","correct":true},{"t":"두 명의 아이가 종이비행기를 슬프게 시끄럽게 날린다.","mis":"K2-1-u3-X05"},{"t":"힘껏 멀리 종이비행기.","mis":"K2-1-u3-X06"}],"explanation":["「힘껏」·「멀리」가 날리는 모습을 생생하게 해요.","뜻이 어긋나는 말을 넣거나 문장을 끝맺지 않으면 안 돼요.","어울리는 말을 넣고 끝까지 써요."],"variant_rule":{"alt":[{"stem":"「아이들이 공을 찬다.」에 꾸며 주는 말을 넣어 더 생생하게 고친 것은 어느 것인가요?","options":[{"t":"아이들이 커다란 공을 힘차게 찬다.","correct":true},{"t":"아이들이 졸린 공을 맛있게 찬다.","mis":"K2-1-u3-X05"},{"t":"커다란 공 힘차게.","mis":"K2-1-u3-X06"}],"explanation":["「커다란」·「힘차게」가 공과 차는 모습을 보여 줘요.","공에 「졸린」, 차는 모습에 「맛있게」는 어울리지 않아요.","문장은 끝까지 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L03_basic#9','kor',2,1,'u3','L03','g2_1_kor_u3_L03_basic','lesson_basic','K2-1-u3-C4',2,'ox','auto','「시끄러운 사과」는 사과의 모습에 어울리는 꾸며 주는 말이에요.',ARRAY['K2-1-u3-X04']::text[],true,'{"seq":9,"concept":"K2-1-u3-C4","difficulty":2,"kind":"ox","stem":"「시끄러운 사과」는 사과의 모습에 어울리는 꾸며 주는 말이에요.","answer":"X","reason_options":[{"t":"사과는 소리를 내지 않아 색이나 모양을 나타내는 말이 어울리니까","correct":true},{"t":"꾸며 주는 말은 아무것이나 붙여도 되니까","mis":"K2-1-u3-X04"}],"mis":"K2-1-u3-X04","explanation":["사과에는 「붉은」, 「둥근」 같은 말이 어울려요.","대상과 어울리지 않는 말을 붙이면 모습이 떠오르지 않아요.","대상을 잘 살펴 골라요."],"variant_rule":{"alt":[{"stem":"「반짝반짝 빛나는 별」은 별의 모습에 어울리는 표현이에요.","answer":"O","reason_options":[{"t":"별이 빛나는 모습이 떠오르니까","correct":true},{"t":"별은 소리를 내니까","mis":"K2-1-u3-X04"}],"explanation":["「반짝반짝」은 별이 빛나는 모습을 잘 나타내요.","대상에 어울리는 말이라서 생생해요.","별은 소리를 내지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L03_basic#10','kor',2,1,'u3','L03','g2_1_kor_u3_L03_basic','lesson_basic','K2-1-u3-C5',3,'error','auto','「우산을 쓴다.」에 꾸며 주는 말을 넣어 문장을 고쳤어요. 알맞지 않게 고친 친구는 누구인가요?',ARRAY['K2-1-u3-X06','K2-1-u3-X19']::text[],true,'{"seq":10,"concept":"K2-1-u3-C5","difficulty":3,"kind":"error","stem":"「우산을 쓴다.」에 꾸며 주는 말을 넣어 문장을 고쳤어요. 알맞지 않게 고친 친구는 누구인가요?","options":[{"t":"지후 — 「노란 우산.」","correct":true,"mis_target":"K2-1-u3-X06"},{"t":"하늘 — 「노란 우산을 쓴다.」","mis":"K2-1-u3-X19"},{"t":"서윤 — 「커다란 우산을 쓰고 천천히 걷는다.」","mis":"K2-1-u3-X19"}],"explanation":["지후는 꾸며 주는 말을 넣었지만 문장을 끝까지 쓰지 않았어요.","하늘이와 서윤이는 꾸며 주는 말을 넣어 끝까지 썼어요.","「누가 어찌한다.」까지 써야 문장이에요."],"variant_rule":{"alt":[{"stem":"「새가 난다.」에 꾸며 주는 말을 넣어 문장을 고쳤어요. 알맞지 않게 고친 친구는 누구인가요?","options":[{"t":"준우 — 「새가 네모나게 맛있게 난다.」","correct":true,"mis_target":"K2-1-u3-X05"},{"t":"소율 — 「작은 새가 높이 난다.」","mis":"K2-1-u3-X19"},{"t":"태민 — 「파란 새가 하늘을 훨훨 난다.」","mis":"K2-1-u3-X19"}],"explanation":["「네모나게」·「맛있게」는 나는 모습과 어울리지 않아요.","소율이와 태민이는 어울리는 말을 넣었어요.","많이 넣는 것보다 어울리게 넣는 것이 중요해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L03_challenge#1','kor',2,1,'u3','L03','g2_1_kor_u3_L03_challenge','lesson_challenge','K2-1-u3-C4',2,'mc','auto','붉게 익은 사과를 「모양」에 초점을 두어 꾸민 말은 어느 것인가요?',ARRAY['K2-1-u3-X04','K2-1-u3-X06']::text[],false,'{"seq":1,"concept":"K2-1-u3-C4","difficulty":2,"kind":"mc","stem":"붉게 익은 사과를 「모양」에 초점을 두어 꾸민 말은 어느 것인가요?","options":[{"t":"둥근 사과","correct":true},{"t":"붉은 사과","mis":"K2-1-u3-X04"},{"t":"빠르게 사과","mis":"K2-1-u3-X06"}],"explanation":["「둥근」은 사과의 모양을 나타내요.","「붉은」은 색을 나타내는 말이에요.","「빠르게 사과」는 말이 되지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L03_challenge#2','kor',2,1,'u3','L03','g2_1_kor_u3_L03_challenge','lesson_challenge','K2-1-u3-C5',2,'mc','auto','「멋있는 말이 힘차게 달려온다.」에서 「힘차게」가 꾸며 주는 말은 어느 것인가요?',ARRAY['K2-1-u3-X02']::text[],false,'{"seq":2,"concept":"K2-1-u3-C5","difficulty":2,"kind":"mc","stem":"「멋있는 말이 힘차게 달려온다.」에서 「힘차게」가 꾸며 주는 말은 어느 것인가요?","options":[{"t":"달려온다","correct":true},{"t":"멋있는","mis":"K2-1-u3-X02"},{"t":"말이","mis":"K2-1-u3-X02"}],"explanation":["「힘차게」는 어떻게 달려오는지 꾸며요.","「멋있는」은 말을 꾸미는 꾸며 주는 말이에요.","한 문장에 꾸며 주는 말이 둘 들어 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L03_challenge#3','kor',2,1,'u3','L03','g2_1_kor_u3_L03_challenge','lesson_challenge','K2-1-u3-C4',3,'mc','auto','바닷가 사진을 보고 쓴 문장 가운데 어울리지 않는 꾸며 주는 말이 들어간 것은 어느 것인가요?',ARRAY['K2-1-u3-X19']::text[],false,'{"seq":3,"concept":"K2-1-u3-C4","difficulty":3,"kind":"mc","stem":"바닷가 사진을 보고 쓴 문장 가운데 어울리지 않는 꾸며 주는 말이 들어간 것은 어느 것인가요?","options":[{"t":"「달콤한 파도가 철썩 친다.」","correct":true},{"t":"「하얀 갈매기가 높이 난다.」","mis":"K2-1-u3-X19"},{"t":"「뜨거운 모래가 반짝인다.」","mis":"K2-1-u3-X19"}],"explanation":["파도는 맛이 없어 「달콤한」이 어울리지 않아요.","「하얀 갈매기」, 「뜨거운 모래」는 바닷가 모습에 어울려요.","「어울리지 않는」을 묻는 물음이에요."],"asset":{"type":"scene","icon":"🏖️🌊"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L03_challenge#4','kor',2,1,'u3','L03','g2_1_kor_u3_L03_challenge','lesson_challenge','K2-1-u3-C4',3,'error','auto','공원 사진을 보고 꾸며 주는 말을 넣었어요. 어울리지 않는 말을 넣은 친구는 누구인가요?',ARRAY['K2-1-u3-X04','K2-1-u3-X19']::text[],false,'{"seq":4,"concept":"K2-1-u3-C4","difficulty":3,"kind":"error","stem":"공원 사진을 보고 꾸며 주는 말을 넣었어요. 어울리지 않는 말을 넣은 친구는 누구인가요?","options":[{"t":"은솔 — 「네모난 비둘기가 걸어간다.」","correct":true,"mis_target":"K2-1-u3-X04"},{"t":"민지 — 「푸른 나무가 우뚝 서 있다.」","mis":"K2-1-u3-X19"},{"t":"아린 — 「알록달록한 꽃이 활짝 피었다.」","mis":"K2-1-u3-X19"}],"explanation":["비둘기는 네모나지 않아요.","「푸른 나무」, 「알록달록한 꽃」은 공원 모습에 어울려요.","대상을 눈앞에 그리고 어울리는 말을 골라요."],"asset":{"type":"scene","icon":"🌳🕊️🌷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L03_challenge#5','kor',2,1,'u3','L03','g2_1_kor_u3_L03_challenge','lesson_challenge','K2-1-u3-C5',3,'mc','auto','「(     ) 별이 (     ) 빛난다.」 두 빈칸에 차례로 넣기에 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X02','K2-1-u3-X04']::text[],false,'{"seq":5,"concept":"K2-1-u3-C5","difficulty":3,"kind":"mc","stem":"「(     ) 별이 (     ) 빛난다.」 두 빈칸에 차례로 넣기에 가장 알맞은 것은 어느 것인가요?","options":[{"t":"작은 — 반짝반짝","correct":true},{"t":"반짝반짝 — 작은","mis":"K2-1-u3-X02"},{"t":"시끄러운 — 맛있게","mis":"K2-1-u3-X04"}],"explanation":["「작은」은 별을, 「반짝반짝」은 빛나는 모습을 꾸며요.","차례를 바꾸면 「반짝반짝 별이 작은 빛난다」가 되어 어색해요.","어울리는 말을 알맞은 자리에 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L03_challenge#6','kor',2,1,'u3','L03','g2_1_kor_u3_L03_challenge','lesson_challenge','K2-1-u3-C5',3,'ox','auto','「키가 큰 커다란 큰 나무」처럼 같은 뜻의 꾸며 주는 말을 많이 넣을수록 더 잘 쓴 문장이에요.',ARRAY['K2-1-u3-X05']::text[],false,'{"seq":6,"concept":"K2-1-u3-C5","difficulty":3,"kind":"ox","stem":"「키가 큰 커다란 큰 나무」처럼 같은 뜻의 꾸며 주는 말을 많이 넣을수록 더 잘 쓴 문장이에요.","answer":"X","reason_options":[{"t":"같은 뜻을 되풀이하면 오히려 어색해지니까","correct":true},{"t":"꾸며 주는 말은 많을수록 좋으니까","mis":"K2-1-u3-X05"}],"mis":"K2-1-u3-X05","explanation":["「큰」과 「커다란」은 뜻이 같아 겹쳐요.","많이 넣는 것보다 어울리게 넣는 것이 중요해요.","「키 큰 푸른 나무」처럼 다른 점을 나타내면 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L03_challenge#7','kor',2,1,'u3','L03','g2_1_kor_u3_L03_challenge','lesson_challenge','K2-1-u3-C5',3,'mc','auto','「아기가 웃는다.」를 아기의 모습이 잘 떠오르게 고친 것은 어느 것인가요?',ARRAY['K2-1-u3-X06','K2-1-u3-X05']::text[],false,'{"seq":7,"concept":"K2-1-u3-C5","difficulty":3,"kind":"mc","stem":"「아기가 웃는다.」를 아기의 모습이 잘 떠오르게 고친 것은 어느 것인가요?","options":[{"t":"「작은 아기가 방긋방긋 웃는다.」","correct":true},{"t":"「작은 아기.」","mis":"K2-1-u3-X06"},{"t":"「작은 아기가 무섭게 화나게 웃는다.」","mis":"K2-1-u3-X05"}],"explanation":["「작은」·「방긋방긋」이 아기와 웃는 모습을 보여 줘요.","「작은 아기.」는 끝맺지 않았어요.","「무섭게」·「화나게」는 웃는 모습과 어울리지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L03_challenge#8','kor',2,1,'u3','L03','g2_1_kor_u3_L03_challenge','lesson_challenge','K2-1-u3-C4',4,'mc','auto','두 친구가 수박 그림을 보고 문장을 만들었어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L03_challenge#9','kor',2,1,'u3','L03','g2_1_kor_u3_L03_challenge','lesson_challenge','K2-1-u3-C5',4,'essay','teacher','바다·산·우리 집 가운데 하나를 떠올려, 그 모습을 꾸며 주는 말을 두 개 이상 넣은 문장으로 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u3-C5","difficulty":4,"kind":"essay","stem":"바다·산·우리 집 가운데 하나를 떠올려, 그 모습을 꾸며 주는 말을 두 개 이상 넣은 문장으로 써 보세요.","answer_guide":{"answer":"예: 넓고 푸른 바다에서 하얀 배가 천천히 나아간다.","scoring_points":["떠올린 장소의 모습을 썼는가","꾸며 주는 말을 두 개 이상 넣었는가","넣은 말이 대상과 어울리고 문장을 끝까지 썼는가"]},"explanation":["장소의 모습.","꾸며 주는 말 두 개 이상.","어울림·끝맺음."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L03_challenge#10','kor',2,1,'u3','L03','g2_1_kor_u3_L03_challenge','lesson_challenge','K2-1-u3-C4',4,'essay','teacher','「고양이」를 색·모양·움직임 가운데 두 가지에 초점을 두어 꾸며 주는 말을 넣은 문장으로 쓰고, 무엇에 초점을 두었는지 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u3-C4","difficulty":4,"kind":"essay","stem":"「고양이」를 색·모양·움직임 가운데 두 가지에 초점을 두어 꾸며 주는 말을 넣은 문장으로 쓰고, 무엇에 초점을 두었는지 써 보세요.","answer_guide":{"answer":"예: 하얀 고양이가 살금살금 걸어간다. — 색(하얀)과 움직임(살금살금)에 초점을 두었어요.","scoring_points":["고양이를 꾸미는 문장을 썼는가","꾸며 주는 말이 두 가지 초점(색·모양·움직임)에 맞는가","무엇에 초점을 두었는지 썼는가"]},"explanation":["고양이 문장.","두 가지 초점.","초점 밝히기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L05_basic#1','kor',2,1,'u3','L05','g2_1_kor_u3_L05_basic','lesson_basic','K2-1-u3-C6',1,'mc','auto','글을 읽고 답해 보세요. 흙 속에서 잠을 자던 것은 무엇인가요?',ARRAY['K2-1-u3-X07']::text[],true,'{"seq":1,"concept":"K2-1-u3-C6","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 흙 속에서 잠을 자던 것은 무엇인가요?","options":[{"t":"작은 씨앗","correct":true},{"t":"커다란 해바라기","mis":"K2-1-u3-X07"},{"t":"까만 흙","mis":"K2-1-u3-X07"}],"explanation":["글 첫 문장에 「작은 씨앗이 흙 속에서 잠을 자요.」라고 했어요.","해바라기는 나중에 핀 꽃이에요.","글에서 찾아 손가락으로 짚어 봐요."],"asset":{"type":"passage","lines":["작은 씨앗이 흙 속에서 잠을 자요.","봄비가 내리자 조그만 새싹이 쏙 돋아났어요.","줄기는 하루하루 무럭무럭 자랐어요.","여름이 되자 커다란 해바라기가 활짝 피었어요.","가을에는 꽃 가운데에 까만 씨앗이 촘촘히 박혔어요."],"title":"해바라기가 자라요"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 봄비가 내리자 돋아난 것은 무엇인가요?","options":[{"t":"조그만 새싹","correct":true},{"t":"까만 씨앗","mis":"K2-1-u3-X07"},{"t":"커다란 꽃","mis":"K2-1-u3-X07"}],"explanation":["봄비가 내리자 조그만 새싹이 쏙 돋아났어요.","꽃은 여름에, 까만 씨앗은 가을에 생겼어요.","글에서 찾아 손가락으로 짚어 봐요."],"asset":{"type":"passage","lines":["작은 씨앗이 흙 속에서 잠을 자요.","봄비가 내리자 조그만 새싹이 쏙 돋아났어요.","줄기는 하루하루 무럭무럭 자랐어요.","여름이 되자 커다란 해바라기가 활짝 피었어요.","가을에는 꽃 가운데에 까만 씨앗이 촘촘히 박혔어요."],"title":"해바라기가 자라요"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L05_basic#2','kor',2,1,'u3','L05','g2_1_kor_u3_L05_basic','lesson_basic','K2-1-u3-C1',1,'mc','auto','글을 읽고 답해 보세요. 「커다란 해바라기」에서 해바라기를 꾸며 주는 말은 어느 것인가요?',ARRAY['K2-1-u3-X01']::text[],true,'{"seq":2,"concept":"K2-1-u3-C1","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 「커다란 해바라기」에서 해바라기를 꾸며 주는 말은 어느 것인가요?","options":[{"t":"커다란","correct":true},{"t":"해바라기","mis":"K2-1-u3-X01"},{"t":"여름","mis":"K2-1-u3-X01"}],"explanation":["「커다란」이 해바라기가 어떤지 알려 줘요.","「해바라기」는 꾸밈을 받는 말이에요.","「어떤 해바라기?」에 대답하는 말을 찾아요."],"asset":{"type":"passage","lines":["작은 씨앗이 흙 속에서 잠을 자요.","봄비가 내리자 조그만 새싹이 쏙 돋아났어요.","줄기는 하루하루 무럭무럭 자랐어요.","여름이 되자 커다란 해바라기가 활짝 피었어요.","가을에는 꽃 가운데에 까만 씨앗이 촘촘히 박혔어요."],"title":"해바라기가 자라요"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 「조그만 새싹」에서 새싹을 꾸며 주는 말은 어느 것인가요?","options":[{"t":"조그만","correct":true},{"t":"새싹","mis":"K2-1-u3-X01"},{"t":"봄비","mis":"K2-1-u3-X01"}],"explanation":["「조그만」이 새싹이 어떤지 알려 줘요.","「새싹」은 꾸밈을 받는 말이에요.","「어떤 새싹?」에 대답하는 말을 찾아요."],"asset":{"type":"passage","lines":["작은 씨앗이 흙 속에서 잠을 자요.","봄비가 내리자 조그만 새싹이 쏙 돋아났어요.","줄기는 하루하루 무럭무럭 자랐어요.","여름이 되자 커다란 해바라기가 활짝 피었어요.","가을에는 꽃 가운데에 까만 씨앗이 촘촘히 박혔어요."],"title":"해바라기가 자라요"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L05_basic#3','kor',2,1,'u3','L05','g2_1_kor_u3_L05_basic','lesson_basic','K2-1-u3-C8',1,'mc','auto','작은 열매가 많이 매달린 모양을 나타내는 말은 어느 것인가요?',ARRAY['K2-1-u3-X08']::text[],true,'{"seq":3,"concept":"K2-1-u3-C8","difficulty":1,"kind":"mc","stem":"작은 열매가 많이 매달린 모양을 나타내는 말은 어느 것인가요?","options":[{"t":"조롱조롱","correct":true},{"t":"올록볼록","mis":"K2-1-u3-X08"},{"t":"활짝","mis":"K2-1-u3-X08"}],"explanation":["「조롱조롱」은 작은 열매가 많이 매달린 모양이에요.","「올록볼록」은 겉이 높고 낮은 모양, 「활짝」은 꽃잎이 한껏 핀 모양이에요.","소리 내어 읽으며 모양을 떠올려요."],"variant_rule":{"alt":[{"stem":"겉면이 고르지 않게 높고 낮은 모양을 나타내는 말은 어느 것인가요?","options":[{"t":"올록볼록","correct":true},{"t":"조롱조롱","mis":"K2-1-u3-X08"},{"t":"활짝","mis":"K2-1-u3-X08"}],"explanation":["「올록볼록」은 겉이 높고 낮은 모양이에요.","「조롱조롱」은 열매가 많이 매달린 모양이에요.","손으로 모양을 흉내 내며 떠올려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L05_basic#4','kor',2,1,'u3','L05','g2_1_kor_u3_L05_basic','lesson_basic','K2-1-u3-C6',1,'ox','auto','글을 읽고 답해 보세요. 해바라기는 여름이 되자 꽃이 활짝 피었어요.',ARRAY['K2-1-u3-X07']::text[],true,'{"seq":4,"concept":"K2-1-u3-C6","difficulty":1,"kind":"ox","stem":"글을 읽고 답해 보세요. 해바라기는 여름이 되자 꽃이 활짝 피었어요.","answer":"O","reason_options":[{"t":"글에 「여름이 되자 커다란 해바라기가 활짝 피었어요.」라고 했으니까","correct":true},{"t":"해바라기는 언제나 봄에 피니까","mis":"K2-1-u3-X07"}],"mis":"K2-1-u3-X07","explanation":["글에서 여름에 꽃이 피었다고 했어요.","글에 없는 내용으로 답하면 안 돼요.","글에서 찾아 확인해요."],"asset":{"type":"passage","lines":["작은 씨앗이 흙 속에서 잠을 자요.","봄비가 내리자 조그만 새싹이 쏙 돋아났어요.","줄기는 하루하루 무럭무럭 자랐어요.","여름이 되자 커다란 해바라기가 활짝 피었어요.","가을에는 꽃 가운데에 까만 씨앗이 촘촘히 박혔어요."],"title":"해바라기가 자라요"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 새싹이 돋아난 뒤에 씨앗을 심었어요.","answer":"X","reason_options":[{"t":"씨앗에서 새싹이 돋아났으니 씨앗이 먼저이니까","correct":true},{"t":"새싹이 먼저 나와야 씨앗이 생기니까","mis":"K2-1-u3-X07"}],"explanation":["씨앗이 흙 속에서 잠을 자다 새싹이 돋았어요.","자라는 차례를 바꾸면 안 돼요.","씨앗 → 새싹 → 꽃 → 씨앗 차례예요."],"asset":{"type":"passage","lines":["작은 씨앗이 흙 속에서 잠을 자요.","봄비가 내리자 조그만 새싹이 쏙 돋아났어요.","줄기는 하루하루 무럭무럭 자랐어요.","여름이 되자 커다란 해바라기가 활짝 피었어요.","가을에는 꽃 가운데에 까만 씨앗이 촘촘히 박혔어요."],"title":"해바라기가 자라요"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L05_basic#5','kor',2,1,'u3','L05','g2_1_kor_u3_L05_basic','lesson_basic','K2-1-u3-C8',2,'match','auto','낱말과 알맞은 뜻을 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u3-C8","difficulty":2,"kind":"match","stem":"낱말과 알맞은 뜻을 이어 보세요.","pairs":[{"l":"조롱조롱","r":"열매가 많이 매달린 모양"},{"l":"올록볼록","r":"겉면이 높고 낮은 모양"},{"l":"활짝","r":"꽃잎이 한껏 핀 모양"}],"mis":"K2-1-u3-X08","explanation":["「조롱조롱」은 열매가 많이 매달린 모양이에요.","「올록볼록」은 겉면이 높고 낮은 모양이에요.","「활짝」은 꽃잎이 한껏 핀 모양이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 낱말과 알맞은 뜻을 이어 보세요.","pairs":[{"l":"무럭무럭","r":"힘차게 잘 자라는 모양"},{"l":"빙글빙글","r":"둥글게 감거나 도는 모양"},{"l":"쏙","r":"조그맣게 내미는 모양"}],"explanation":["「무럭무럭」은 힘차게 잘 자라는 모양이에요.","「빙글빙글」은 둥글게 감거나 도는 모양이에요.","「쏙」은 조그맣게 내미는 모양이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L05_basic#6','kor',2,1,'u3','L05','g2_1_kor_u3_L05_basic','lesson_basic','K2-1-u3-C6',2,'mc','auto','글을 읽고 답해 보세요. 해바라기가 자란 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X07']::text[],true,'{"seq":6,"concept":"K2-1-u3-C6","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 해바라기가 자란 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"씨앗 → 새싹 → 꽃 → 씨앗","correct":true},{"t":"새싹 → 씨앗 → 꽃 → 씨앗","mis":"K2-1-u3-X07"},{"t":"꽃 → 새싹 → 씨앗 → 꽃","mis":"K2-1-u3-X07"}],"explanation":["작은 씨앗에서 새싹이 돋고, 꽃이 핀 뒤 다시 씨앗이 생겼어요.","차례를 뒤바꾸면 글과 달라져요.","봄·여름·가을 낱말을 따라가 봐요."],"asset":{"type":"passage","lines":["작은 씨앗이 흙 속에서 잠을 자요.","봄비가 내리자 조그만 새싹이 쏙 돋아났어요.","줄기는 하루하루 무럭무럭 자랐어요.","여름이 되자 커다란 해바라기가 활짝 피었어요.","가을에는 꽃 가운데에 까만 씨앗이 촘촘히 박혔어요."],"title":"해바라기가 자라요"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 토마토가 자란 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"모종 → 노란 꽃 → 초록 열매 → 빨간 열매","correct":true},{"t":"모종 → 빨간 열매 → 노란 꽃 → 초록 열매","mis":"K2-1-u3-X07"},{"t":"노란 꽃 → 모종 → 빨간 열매 → 초록 열매","mis":"K2-1-u3-X07"}],"explanation":["모종을 심고, 꽃이 피고, 초록 열매가 빨갛게 익었어요.","차례를 뒤바꾸면 글과 달라져요.","글의 문장 차례대로 따라가요."],"asset":{"type":"passage","lines":["텃밭에 토마토 모종을 심었어요.","줄기가 쑥쑥 곧게 자라고 노란 꽃이 피었어요.","꽃이 진 자리에 초록 열매가 조롱조롱 매달렸어요.","햇볕을 듬뿍 받은 열매는 빨갛게 익어 갔어요."],"title":"조롱조롱 토마토"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L05_basic#7','kor',2,1,'u3','L05','g2_1_kor_u3_L05_basic','lesson_basic','K2-1-u3-C3',2,'mc','auto','글을 읽고 답해 보세요. 「줄기는 하루하루 무럭무럭 자랐어요.」에서 「무럭무럭」을 빼면 어떻게 될까요?',ARRAY['K2-1-u3-X03','K2-1-u3-X07']::text[],true,'{"seq":7,"concept":"K2-1-u3-C3","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 「줄기는 하루하루 무럭무럭 자랐어요.」에서 「무럭무럭」을 빼면 어떻게 될까요?","options":[{"t":"줄기가 어떻게 자랐는지 모습이 잘 떠오르지 않아요","correct":true},{"t":"문장이 더 생생해져요","mis":"K2-1-u3-X03"},{"t":"줄기가 자라지 않은 것이 돼요","mis":"K2-1-u3-X07"}],"explanation":["「무럭무럭」이 자라는 모습을 그려 줘요.","빼도 줄기는 자라지만 모습이 덜 생생해요.","꾸며 주는 말이 모습을 보여 줘요."],"asset":{"type":"passage","lines":["작은 씨앗이 흙 속에서 잠을 자요.","봄비가 내리자 조그만 새싹이 쏙 돋아났어요.","줄기는 하루하루 무럭무럭 자랐어요.","여름이 되자 커다란 해바라기가 활짝 피었어요.","가을에는 꽃 가운데에 까만 씨앗이 촘촘히 박혔어요."],"title":"해바라기가 자라요"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 「노란 꽃이 피었어요.」에서 「노란」을 빼면 어떻게 될까요?","options":[{"t":"꽃이 무슨 색인지 알 수 없어요","correct":true},{"t":"꽃이 더 또렷하게 떠올라요","mis":"K2-1-u3-X03"},{"t":"꽃이 피지 않은 것이 돼요","mis":"K2-1-u3-X07"}],"explanation":["「노란」이 꽃의 색을 알려 줘요.","빼면 꽃의 모습이 덜 또렷해요.","꾸며 주는 말이 모습을 보여 줘요."],"asset":{"type":"passage","lines":["텃밭에 토마토 모종을 심었어요.","줄기가 쑥쑥 곧게 자라고 노란 꽃이 피었어요.","꽃이 진 자리에 초록 열매가 조롱조롱 매달렸어요.","햇볕을 듬뿍 받은 열매는 빨갛게 익어 갔어요."],"title":"조롱조롱 토마토"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L05_basic#8','kor',2,1,'u3','L05','g2_1_kor_u3_L05_basic','lesson_basic','K2-1-u3-C6',2,'sa','auto','글을 읽고 답해 보세요. 꽃이 진 자리에 매달린 열매는 처음에 무슨 색이었나요? 한 낱말로 써 보세요.','{}'::text[],true,'{"seq":8,"concept":"K2-1-u3-C6","difficulty":2,"kind":"sa","stem":"글을 읽고 답해 보세요. 꽃이 진 자리에 매달린 열매는 처음에 무슨 색이었나요? 한 낱말로 써 보세요.","answer":["초록","초록색","초록 색"],"explanation":["「꽃이 진 자리에 초록 열매가 조롱조롱 매달렸어요.」라고 했어요.","빨갛게 된 것은 햇볕을 받고 익은 뒤예요.","글에서 찾아 짚어 봐요."],"asset":{"type":"passage","lines":["텃밭에 토마토 모종을 심었어요.","줄기가 쑥쑥 곧게 자라고 노란 꽃이 피었어요.","꽃이 진 자리에 초록 열매가 조롱조롱 매달렸어요.","햇볕을 듬뿍 받은 열매는 빨갛게 익어 갔어요."],"title":"조롱조롱 토마토"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 토마토 줄기가 자랄 때 핀 꽃은 무슨 색이었나요? 한 낱말로 써 보세요.","answer":["노란","노랑","노란색","노랑색"],"explanation":["「줄기가 쑥쑥 곧게 자라고 노란 꽃이 피었어요.」라고 했어요.","빨간 것은 익은 열매예요.","글에서 찾아 짚어 봐요."],"asset":{"type":"passage","lines":["텃밭에 토마토 모종을 심었어요.","줄기가 쑥쑥 곧게 자라고 노란 꽃이 피었어요.","꽃이 진 자리에 초록 열매가 조롱조롱 매달렸어요.","햇볕을 듬뿍 받은 열매는 빨갛게 익어 갔어요."],"title":"조롱조롱 토마토"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L05_basic#9','kor',2,1,'u3','L05','g2_1_kor_u3_L05_basic','lesson_basic','K2-1-u3-C3',2,'mc','auto','덩굴손이 자라는 모습을 더 잘 나타낸 문장은 어느 것인가요?',ARRAY['K2-1-u3-X03','K2-1-u3-X06']::text[],true,'{"seq":9,"concept":"K2-1-u3-C3","difficulty":2,"kind":"mc","stem":"덩굴손이 자라는 모습을 더 잘 나타낸 문장은 어느 것인가요?","options":[{"t":"덩굴손이 빙글빙글 감으며 쭉쭉 뻗어 간다.","correct":true},{"t":"덩굴손이 자란다.","mis":"K2-1-u3-X03"},{"t":"덩굴손.","mis":"K2-1-u3-X06"}],"explanation":["「빙글빙글」·「쭉쭉」이 뻗어 가는 모습을 보여 줘요.","「덩굴손이 자란다.」로는 어떻게 자라는지 알 수 없어요.","「덩굴손.」은 문장이 아니에요."],"variant_rule":{"alt":[{"stem":"새싹이 돋는 모습을 더 잘 나타낸 문장은 어느 것인가요?","options":[{"t":"조그만 새싹이 흙을 밀고 쏙 돋아났다.","correct":true},{"t":"새싹이 났다.","mis":"K2-1-u3-X03"},{"t":"조그만 새싹.","mis":"K2-1-u3-X06"}],"explanation":["「조그만」·「쏙」이 돋는 모습을 보여 줘요.","「새싹이 났다.」로는 모습이 떠오르지 않아요.","「조그만 새싹.」은 끝맺지 않았어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L05_basic#10','kor',2,1,'u3','L05','g2_1_kor_u3_L05_basic','lesson_basic','K2-1-u3-C8',3,'error','auto','글을 읽고 낱말의 뜻을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K2-1-u3-X08','K2-1-u3-X19']::text[],true,'{"seq":10,"concept":"K2-1-u3-C8","difficulty":3,"kind":"error","stem":"글을 읽고 낱말의 뜻을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"현우 — 「‘올록볼록’은 열매가 많이 매달린 모양이야.」","correct":true,"mis_target":"K2-1-u3-X08"},{"t":"지안 — 「‘빙글빙글’은 막대를 둥글게 감는 모양이야.」","mis":"K2-1-u3-X19"},{"t":"도담 — 「‘동글동글’은 콩이 둥근 모양이야.」","mis":"K2-1-u3-X19"}],"explanation":["「올록볼록」은 겉이 높고 낮은 모양이에요.","열매가 많이 매달린 모양은 「조롱조롱」이에요.","지안이와 도담이는 바르게 말했어요."],"asset":{"type":"passage","lines":["완두는 덩굴손이 있는 식물이에요.","덩굴손은 막대를 빙글빙글 감으며 쭉쭉 뻗어 가요.","꼬투리 속에는 동글동글한 완두콩이 나란히 들어 있어요.","땅콩 껍데기는 겉이 올록볼록해서 만지면 울퉁불퉁해요."],"title":"덩굴손과 꼬투리"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 글을 읽고 낱말의 뜻을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"예린 — 「‘쭉쭉’은 아주 느리게 뒤로 물러나는 모양이야.」","correct":true,"mis_target":"K2-1-u3-X08"},{"t":"하준 — 「‘쭉쭉’은 길게 곧게 뻗는 모양이야.」","mis":"K2-1-u3-X19"},{"t":"서아 — 「‘올록볼록’은 겉이 울퉁불퉁한 모양이야.」","mis":"K2-1-u3-X19"}],"explanation":["「쭉쭉」은 길게 곧게 뻗어 가는 모양이에요.","느리게 물러나는 모양이 아니에요.","하준이와 서아는 바르게 말했어요."],"asset":{"type":"passage","lines":["완두는 덩굴손이 있는 식물이에요.","덩굴손은 막대를 빙글빙글 감으며 쭉쭉 뻗어 가요.","꼬투리 속에는 동글동글한 완두콩이 나란히 들어 있어요.","땅콩 껍데기는 겉이 올록볼록해서 만지면 울퉁불퉁해요."],"title":"덩굴손과 꼬투리"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L05_challenge#1','kor',2,1,'u3','L05','g2_1_kor_u3_L05_challenge','lesson_challenge','K2-1-u3-C6',2,'mc','auto','글을 읽고 답해 보세요. 땅콩 껍데기를 만지면 어떤 느낌일까요?',ARRAY['K2-1-u3-X07']::text[],false,'{"seq":1,"concept":"K2-1-u3-C6","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 땅콩 껍데기를 만지면 어떤 느낌일까요?","options":[{"t":"울퉁불퉁해요","correct":true},{"t":"매끈매끈해요","mis":"K2-1-u3-X07"},{"t":"말랑말랑해요","mis":"K2-1-u3-X07"}],"explanation":["겉이 올록볼록해서 만지면 울퉁불퉁하다고 했어요.","매끈하거나 말랑하다는 말은 글에 없어요.","글에서 찾아 짚어 봐요."],"asset":{"type":"passage","lines":["완두는 덩굴손이 있는 식물이에요.","덩굴손은 막대를 빙글빙글 감으며 쭉쭉 뻗어 가요.","꼬투리 속에는 동글동글한 완두콩이 나란히 들어 있어요.","땅콩 껍데기는 겉이 올록볼록해서 만지면 울퉁불퉁해요."],"title":"덩굴손과 꼬투리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L05_challenge#2','kor',2,1,'u3','L05','g2_1_kor_u3_L05_challenge','lesson_challenge','K2-1-u3-C1',2,'mc','auto','글을 읽고 답해 보세요. 이 글에서 꾸며 주는 말만 모은 것은 어느 것인가요?',ARRAY['K2-1-u3-X01']::text[],false,'{"seq":2,"concept":"K2-1-u3-C1","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 이 글에서 꾸며 주는 말만 모은 것은 어느 것인가요?","options":[{"t":"빙글빙글 · 동글동글한 · 올록볼록","correct":true},{"t":"덩굴손 · 꼬투리 · 땅콩","mis":"K2-1-u3-X01"},{"t":"완두 · 막대 · 껍데기","mis":"K2-1-u3-X01"}],"explanation":["「빙글빙글」·「동글동글한」·「올록볼록」은 모습을 꾸며요.","덩굴손·꼬투리·땅콩·막대는 꾸밈을 받는 이름 낱말이에요.","「어떤? 어떻게?」에 대답하는 말을 모아요."],"asset":{"type":"passage","lines":["완두는 덩굴손이 있는 식물이에요.","덩굴손은 막대를 빙글빙글 감으며 쭉쭉 뻗어 가요.","꼬투리 속에는 동글동글한 완두콩이 나란히 들어 있어요.","땅콩 껍데기는 겉이 올록볼록해서 만지면 울퉁불퉁해요."],"title":"덩굴손과 꼬투리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L05_challenge#3','kor',2,1,'u3','L05','g2_1_kor_u3_L05_challenge','lesson_challenge','K2-1-u3-C6',3,'mc','auto','글을 읽고 답해 보세요. 열매가 빨갛게 익을 수 있었던 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X07']::text[],false,'{"seq":3,"concept":"K2-1-u3-C6","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 열매가 빨갛게 익을 수 있었던 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"햇볕을 듬뿍 받았기 때문이에요","correct":true},{"t":"노란 꽃이 다시 피었기 때문이에요","mis":"K2-1-u3-X07"},{"t":"줄기를 잘라 주었기 때문이에요","mis":"K2-1-u3-X07"}],"explanation":["「햇볕을 듬뿍 받은 열매는 빨갛게 익어 갔어요.」라고 했어요.","다른 까닭은 글에 없어요.","글에 쓰인 까닭을 찾아요."],"asset":{"type":"passage","lines":["텃밭에 토마토 모종을 심었어요.","줄기가 쑥쑥 곧게 자라고 노란 꽃이 피었어요.","꽃이 진 자리에 초록 열매가 조롱조롱 매달렸어요.","햇볕을 듬뿍 받은 열매는 빨갛게 익어 갔어요."],"title":"조롱조롱 토마토"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L05_challenge#4','kor',2,1,'u3','L05','g2_1_kor_u3_L05_challenge','lesson_challenge','K2-1-u3-C6',3,'ox','auto','글을 읽고 답해 보세요. 덩굴손은 막대를 감지 않고 아래로 축 늘어져 자라요.',ARRAY['K2-1-u3-X07']::text[],false,'{"seq":4,"concept":"K2-1-u3-C6","difficulty":3,"kind":"ox","stem":"글을 읽고 답해 보세요. 덩굴손은 막대를 감지 않고 아래로 축 늘어져 자라요.","answer":"X","reason_options":[{"t":"글에 막대를 빙글빙글 감으며 쭉쭉 뻗어 간다고 했으니까","correct":true},{"t":"덩굴손은 원래 아무것도 감지 않으니까","mis":"K2-1-u3-X07"}],"mis":"K2-1-u3-X07","explanation":["덩굴손은 막대를 빙글빙글 감으며 뻗어 가요.","글에 없는 내용으로 답하면 안 돼요.","글에서 찾아 확인해요."],"asset":{"type":"passage","lines":["완두는 덩굴손이 있는 식물이에요.","덩굴손은 막대를 빙글빙글 감으며 쭉쭉 뻗어 가요.","꼬투리 속에는 동글동글한 완두콩이 나란히 들어 있어요.","땅콩 껍데기는 겉이 올록볼록해서 만지면 울퉁불퉁해요."],"title":"덩굴손과 꼬투리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L05_challenge#5','kor',2,1,'u3','L05','g2_1_kor_u3_L05_challenge','lesson_challenge','K2-1-u3-C6',3,'error','auto','글을 읽고 해바라기가 자라는 모습을 말했어요. 글과 다르게 말한 친구는 누구인가요?',ARRAY['K2-1-u3-X07','K2-1-u3-X19']::text[],false,'{"seq":5,"concept":"K2-1-u3-C6","difficulty":3,"kind":"error","stem":"글을 읽고 해바라기가 자라는 모습을 말했어요. 글과 다르게 말한 친구는 누구인가요?","options":[{"t":"민호 — 「겨울에 해바라기 꽃이 활짝 피었어.」","correct":true,"mis_target":"K2-1-u3-X07"},{"t":"소율 — 「봄비가 내리자 새싹이 돋았어.」","mis":"K2-1-u3-X19"},{"t":"지우 — 「가을에 꽃 가운데에 씨앗이 박혔어.」","mis":"K2-1-u3-X19"}],"explanation":["글에서는 여름에 꽃이 피었다고 했어요.","겨울에 피었다는 말은 글에 없어요.","소율이와 지우는 글과 같게 말했어요."],"asset":{"type":"passage","lines":["작은 씨앗이 흙 속에서 잠을 자요.","봄비가 내리자 조그만 새싹이 쏙 돋아났어요.","줄기는 하루하루 무럭무럭 자랐어요.","여름이 되자 커다란 해바라기가 활짝 피었어요.","가을에는 꽃 가운데에 까만 씨앗이 촘촘히 박혔어요."],"title":"해바라기가 자라요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L05_challenge#6','kor',2,1,'u3','L05','g2_1_kor_u3_L05_challenge','lesson_challenge','K2-1-u3-C8',3,'mc','auto','「꽃이 진 자리에 초록 열매가 (     ) 매달렸어요.」에 들어갈 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X08','K2-1-u3-X04']::text[],false,'{"seq":6,"concept":"K2-1-u3-C8","difficulty":3,"kind":"mc","stem":"「꽃이 진 자리에 초록 열매가 (     ) 매달렸어요.」에 들어갈 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"조롱조롱","correct":true},{"t":"올록볼록","mis":"K2-1-u3-X08"},{"t":"펑펑","mis":"K2-1-u3-X04"}],"explanation":["작은 열매가 많이 매달린 모양은 「조롱조롱」이에요.","「올록볼록」은 겉면의 모양, 「펑펑」은 눈이 많이 내리는 모양이에요.","매달린 모습에 어울리는 말을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L05_challenge#7','kor',2,1,'u3','L05','g2_1_kor_u3_L05_challenge','lesson_challenge','K2-1-u3-C3',3,'mc','auto','글쓴이가 「작은 씨앗」, 「커다란 해바라기」처럼 꾸며 주는 말을 쓴 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X03']::text[],false,'{"seq":7,"concept":"K2-1-u3-C3","difficulty":3,"kind":"mc","stem":"글쓴이가 「작은 씨앗」, 「커다란 해바라기」처럼 꾸며 주는 말을 쓴 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"씨앗이 큰 꽃으로 자라는 모습을 생생하게 보여 주려고","correct":true},{"t":"글을 길게 만들려고","mis":"K2-1-u3-X03"},{"t":"해바라기 이름을 바꾸려고","mis":"K2-1-u3-X03"}],"explanation":["「작은」과 「커다란」을 견주니 자라는 모습이 또렷해요.","글을 길게 하려는 것이 아니에요.","꾸며 주는 말로 모습을 그려 보여 준 거예요."],"asset":{"type":"passage","lines":["작은 씨앗이 흙 속에서 잠을 자요.","봄비가 내리자 조그만 새싹이 쏙 돋아났어요.","줄기는 하루하루 무럭무럭 자랐어요.","여름이 되자 커다란 해바라기가 활짝 피었어요.","가을에는 꽃 가운데에 까만 씨앗이 촘촘히 박혔어요."],"title":"해바라기가 자라요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L05_challenge#8','kor',2,1,'u3','L05','g2_1_kor_u3_L05_challenge','lesson_challenge','K2-1-u3-C8',4,'mc','auto','두 친구가 화단의 식물을 설명했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L05_challenge#9','kor',2,1,'u3','L05','g2_1_kor_u3_L05_challenge','lesson_challenge','K2-1-u3-C6',4,'essay','teacher','「해바라기가 자라요」를 읽고, 해바라기가 자라는 차례를 꾸며 주는 말을 넣어 두 문장으로 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u3-C6","difficulty":4,"kind":"essay","stem":"「해바라기가 자라요」를 읽고, 해바라기가 자라는 차례를 꾸며 주는 말을 넣어 두 문장으로 써 보세요.","answer_guide":{"answer":"예: 작은 씨앗에서 조그만 새싹이 쏙 돋았어요. 새싹은 무럭무럭 자라 커다란 해바라기가 되었어요.","scoring_points":["씨앗 → 새싹 → 꽃 차례가 글과 맞는가","꾸며 주는 말을 넣었는가","두 문장으로 끝까지 썼는가"]},"explanation":["자라는 차례.","꾸며 주는 말.","두 문장."],"asset":{"type":"passage","lines":["작은 씨앗이 흙 속에서 잠을 자요.","봄비가 내리자 조그만 새싹이 쏙 돋아났어요.","줄기는 하루하루 무럭무럭 자랐어요.","여름이 되자 커다란 해바라기가 활짝 피었어요.","가을에는 꽃 가운데에 까만 씨앗이 촘촘히 박혔어요."],"title":"해바라기가 자라요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L05_challenge#10','kor',2,1,'u3','L05','g2_1_kor_u3_L05_challenge','lesson_challenge','K2-1-u3-C8',4,'essay','teacher','집이나 학교에서 본 식물·과일을 하나 골라, 모양을 흉내 내거나 꾸며 주는 말(예: 동글동글, 올록볼록)을 넣어 설명하는 문장을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u3-C8","difficulty":4,"kind":"essay","stem":"집이나 학교에서 본 식물·과일을 하나 골라, 모양을 흉내 내거나 꾸며 주는 말(예: 동글동글, 올록볼록)을 넣어 설명하는 문장을 써 보세요.","answer_guide":{"answer":"예: 귤 껍질은 오톨도톨하고, 속은 동글동글한 조각으로 나뉘어 있어요.","scoring_points":["식물이나 과일 하나를 골랐는가","모양을 나타내는 말을 넣었는가","그 말이 대상의 모습과 어울리는가"]},"explanation":["대상 고르기.","모양 낱말.","어울림."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L07_basic#1','kor',2,1,'u3','L07','g2_1_kor_u3_L07_basic','lesson_basic','K2-1-u3-C8',1,'mc','auto','일기로 쓸 이야깃거리를 무엇이라고 하나요?',ARRAY['K2-1-u3-X14','K2-1-u3-X09']::text[],true,'{"seq":1,"concept":"K2-1-u3-C8","difficulty":1,"kind":"mc","stem":"일기로 쓸 이야깃거리를 무엇이라고 하나요?","options":[{"t":"글감","correct":true},{"t":"제목","mis":"K2-1-u3-X14"},{"t":"날씨","mis":"K2-1-u3-X09"}],"explanation":["일기로 쓸 이야깃거리를 글감이라고 해요.","제목은 글감을 정한 뒤 붙이는 이름이에요.","날씨는 일기 맨 처음에 쓰는 것이에요."],"variant_rule":{"alt":[{"stem":"평소와 다르게 보였거나 마음에 오래 남는 일을 무엇이라고 하나요?","options":[{"t":"인상 깊은 일","correct":true},{"t":"날마다 하는 일","mis":"K2-1-u3-X13"},{"t":"내일 할 일","mis":"K2-1-u3-X13"}],"explanation":["마음에 오래 남는 일을 인상 깊은 일이라고 해요.","날마다 하는 일이나 내일 할 일은 아니에요.","인상 깊은 일이 좋은 글감이 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L07_basic#2','kor',2,1,'u3','L07','g2_1_kor_u3_L07_basic','lesson_basic','K2-1-u3-C8',1,'mc','auto','하루에 겪은 일로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X12']::text[],true,'{"seq":2,"concept":"K2-1-u3-C8","difficulty":1,"kind":"mc","stem":"하루에 겪은 일로 알맞은 것은 어느 것인가요?","options":[{"t":"텃밭에서 상추를 땄다","correct":true},{"t":"연필","mis":"K2-1-u3-X12"},{"t":"즐거움","mis":"K2-1-u3-X12"}],"explanation":["「상추를 땄다」는 내가 한 일이에요.","「연필」은 물건, 「즐거움」은 느낌이에요.","「~했다·봤다·들었다」로 말이 되는지 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 하루에 겪은 일로 알맞은 것은 어느 것인가요?","options":[{"t":"도서관에서 책을 읽었다","correct":true},{"t":"책상","mis":"K2-1-u3-X12"},{"t":"기쁨","mis":"K2-1-u3-X12"}],"explanation":["「책을 읽었다」는 내가 한 일이에요.","「책상」은 물건, 「기쁨」은 느낌이에요.","「~했다·봤다·들었다」로 말이 되는지 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L07_basic#3','kor',2,1,'u3','L07','g2_1_kor_u3_L07_basic','lesson_basic','K2-1-u3-C8',1,'ox','auto','일기 글감은 하루에 겪은 일 가운데 가장 인상 깊은 일 하나를 골라 정해요.',ARRAY['K2-1-u3-X13']::text[],true,'{"seq":3,"concept":"K2-1-u3-C8","difficulty":1,"kind":"ox","stem":"일기 글감은 하루에 겪은 일 가운데 가장 인상 깊은 일 하나를 골라 정해요.","answer":"O","reason_options":[{"t":"기억에 남는 일을 골라야 그날이 잘 드러나니까","correct":true},{"t":"하루 일을 모두 써야 하니까","mis":"K2-1-u3-X13"}],"mis":"K2-1-u3-X13","explanation":["글감은 가장 인상 깊은 일 하나를 골라요.","모두 쓰면 무엇이 마음에 남았는지 흐려져요.","고른 일을 자세히 써요."],"variant_rule":{"alt":[{"stem":"날마다 똑같이 하는 이 닦기가 가장 좋은 일기 글감이에요.","answer":"X","reason_options":[{"t":"마음이 움직인 인상 깊은 일이 좋은 글감이니까","correct":true},{"t":"날마다 하는 일이 가장 중요하니까","mis":"K2-1-u3-X13"}],"explanation":["날마다 똑같은 일은 그날만의 이야기가 되기 어려워요.","마음이 움직인 일을 골라요.","같은 일이라도 특별했다면 글감이 될 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L07_basic#4','kor',2,1,'u3','L07','g2_1_kor_u3_L07_basic','lesson_basic','K2-1-u3-C9',1,'mc','auto','줄넘기를 처음 성공한 날의 일기 제목으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X14']::text[],true,'{"seq":4,"concept":"K2-1-u3-C9","difficulty":1,"kind":"mc","stem":"줄넘기를 처음 성공한 날의 일기 제목으로 알맞은 것은 어느 것인가요?","options":[{"t":"줄넘기를 처음 성공한 날","correct":true},{"t":"오늘 날씨","mis":"K2-1-u3-X14"},{"t":"그냥 하루","mis":"K2-1-u3-X14"}],"explanation":["제목만 보아도 무슨 일인지 알 수 있어요.","「오늘 날씨」, 「그냥 하루」로는 내용을 알 수 없어요.","제목은 내용을 한눈에 보여 줘요."],"variant_rule":{"alt":[{"stem":"텃밭에서 처음 상추를 딴 날의 일기 제목으로 알맞은 것은 어느 것인가요?","options":[{"t":"내가 딴 첫 상추","correct":true},{"t":"일기","mis":"K2-1-u3-X14"},{"t":"수요일","mis":"K2-1-u3-X14"}],"explanation":["제목만 보아도 무슨 일인지 알 수 있어요.","「일기」, 「수요일」로는 내용을 알 수 없어요.","제목은 내용을 한눈에 보여 줘요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L07_basic#5','kor',2,1,'u3','L07','g2_1_kor_u3_L07_basic','lesson_basic','K2-1-u3-C10',2,'match','auto','겪은 일과 그때의 느낌을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u3-C10","difficulty":2,"kind":"match","stem":"겪은 일과 그때의 느낌을 알맞게 이어 보세요.","pairs":[{"l":"줄넘기 처음 성공","r":"뿌듯했어요"},{"l":"친구들 앞에서 노래","r":"긴장됐어요"},{"l":"동생과 책 읽기","r":"즐거웠어요"}],"mis":"K2-1-u3-X15","explanation":["처음 성공했을 때는 뿌듯했어요.","친구들 앞에 서면 긴장이 돼요.","동생과 책을 읽으니 즐거웠어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 겪은 일과 그때의 느낌을 알맞게 이어 보세요.","pairs":[{"l":"아끼던 연필을 잃어버림","r":"속상했어요"},{"l":"생일 선물을 받음","r":"기뻤어요"},{"l":"갑자기 천둥이 침","r":"깜짝 놀랐어요"}],"explanation":["아끼던 것을 잃어버리면 속상해요.","선물을 받으면 기뻐요.","갑자기 천둥이 치면 놀라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L07_basic#6','kor',2,1,'u3','L07','g2_1_kor_u3_L07_basic','lesson_basic','K2-1-u3-C8',2,'mc','auto','글을 읽고 답해 보세요. 하준이가 일기 글감으로 고르기에 가장 알맞은 일은 어느 것인가요?',ARRAY['K2-1-u3-X13']::text[],true,'{"seq":6,"concept":"K2-1-u3-C8","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 하준이가 일기 글감으로 고르기에 가장 알맞은 일은 어느 것인가요?","options":[{"t":"처음으로 줄넘기 열 번을 넘은 일","correct":true},{"t":"자기 전에 이를 닦은 일","mis":"K2-1-u3-X13"},{"t":"아침부터 저녁까지 한 일 모두","mis":"K2-1-u3-X13"}],"explanation":["처음 해낸 일이라 마음에 남는 일이에요.","이 닦기는 날마다 하는 일이에요.","하루 일을 모두 쓰면 글감이 흐려져요."],"asset":{"type":"passage","lines":["아침 — 창밖으로 맑은 하늘을 보았다.","낮 — 운동장에서 처음으로 줄넘기 열 번을 넘었다.","저녁 — 동생과 그림책을 읽었다.","자기 전 — 이를 닦았다."],"title":"하준이의 하루"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 서윤이가 일기 글감으로 고르기에 가장 알맞은 일은 어느 것인가요?","options":[{"t":"텃밭에서 처음으로 상추를 딴 일","correct":true},{"t":"숙제를 한 일","mis":"K2-1-u3-X13"},{"t":"아침부터 저녁까지 한 일 모두","mis":"K2-1-u3-X13"}],"explanation":["처음 해 본 일이라 마음에 남는 일이에요.","숙제는 날마다 하는 일이에요.","하루 일을 모두 쓰면 글감이 흐려져요."],"asset":{"type":"passage","lines":["아침 — 엄마가 차려 주신 밥을 먹었다.","낮 — 텃밭에서 처음으로 상추를 땄다.","오후 — 친구에게 「고마워.」라는 말을 들었다.","저녁 — 숙제를 했다."],"title":"서윤이의 하루"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L07_basic#7','kor',2,1,'u3','L07','g2_1_kor_u3_L07_basic','lesson_basic','K2-1-u3-C8',2,'mc','auto','하루에 「들은 것」에 해당하는 겪은 일은 어느 것인가요?',ARRAY['K2-1-u3-X19']::text[],true,'{"seq":7,"concept":"K2-1-u3-C8","difficulty":2,"kind":"mc","stem":"하루에 「들은 것」에 해당하는 겪은 일은 어느 것인가요?","options":[{"t":"선생님께 「잘했어.」라는 칭찬을 들었다","correct":true},{"t":"운동장에서 줄넘기를 했다","mis":"K2-1-u3-X19"},{"t":"창밖으로 맑은 하늘을 보았다","mis":"K2-1-u3-X19"}],"explanation":["칭찬을 들은 것은 「들은 것」이에요.","줄넘기는 「한 것」, 하늘은 「본 것」이에요.","한 것·본 것·들은 것을 나누어 떠올려요."],"variant_rule":{"alt":[{"stem":"하루에 「본 것」에 해당하는 겪은 일은 어느 것인가요?","options":[{"t":"공원에서 무지개를 보았다","correct":true},{"t":"친구와 술래잡기를 했다","mis":"K2-1-u3-X19"},{"t":"엄마의 노랫소리를 들었다","mis":"K2-1-u3-X19"}],"explanation":["무지개를 본 것은 「본 것」이에요.","술래잡기는 「한 것」, 노랫소리는 「들은 것」이에요.","한 것·본 것·들은 것을 나누어 떠올려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L07_basic#8','kor',2,1,'u3','L07','g2_1_kor_u3_L07_basic','lesson_basic','K2-1-u3-C9',2,'sa','auto','「할머니 댁에서 처음으로 송편을 빚었다.」가 글감인 일기의 제목을 짧게 지어 써 보세요.','{}'::text[],true,'{"seq":8,"concept":"K2-1-u3-C9","difficulty":2,"kind":"sa","stem":"「할머니 댁에서 처음으로 송편을 빚었다.」가 글감인 일기의 제목을 짧게 지어 써 보세요.","answer":["송편","송편을 빚은 날","처음 빚은 송편","할머니 댁에서 빚은 송편","내가 빚은 송편"],"explanation":["제목에는 「송편」처럼 무슨 일인지 드러나는 낱말이 들어가요.","「오늘」, 「일기」만으로는 내용을 알 수 없어요.","제목만 보고도 무슨 일인지 알 수 있게 지어요."],"variant_rule":{"alt":[{"stem":"「처음으로 두발자전거를 혼자 탔다.」가 글감인 일기의 제목을 짧게 지어 써 보세요.","answer":["자전거","두발자전거","처음 탄 두발자전거","자전거를 혼자 탄 날","혼자 탄 자전거"],"explanation":["제목에는 「자전거」처럼 무슨 일인지 드러나는 낱말이 들어가요.","「오늘」, 「일기」만으로는 내용을 알 수 없어요.","제목만 보고도 무슨 일인지 알 수 있게 지어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L07_basic#9','kor',2,1,'u3','L07','g2_1_kor_u3_L07_basic','lesson_basic','K2-1-u3-C9',2,'ox','auto','일기 제목은 「일기」라고만 써도 내용이 잘 드러나요.',ARRAY['K2-1-u3-X14']::text[],true,'{"seq":9,"concept":"K2-1-u3-C9","difficulty":2,"kind":"ox","stem":"일기 제목은 「일기」라고만 써도 내용이 잘 드러나요.","answer":"X","reason_options":[{"t":"제목만 보고 무슨 일인지 알 수 있어야 하니까","correct":true},{"t":"모든 일기는 같은 제목을 쓰니까","mis":"K2-1-u3-X14"}],"mis":"K2-1-u3-X14","explanation":["「일기」라는 제목으로는 무슨 일인지 알 수 없어요.","제목은 내용을 한눈에 보여 줘야 해요.","「처음 딴 상추」처럼 지어요."],"variant_rule":{"alt":[{"stem":"「동생과 만든 눈사람」은 내용이 잘 드러나는 일기 제목이에요.","answer":"O","reason_options":[{"t":"무슨 일이 있었는지 제목만 보아도 알 수 있으니까","correct":true},{"t":"제목이 길면 무조건 좋으니까","mis":"K2-1-u3-X14"}],"explanation":["제목만 보고도 동생과 눈사람을 만든 일임을 알 수 있어요.","길이가 아니라 내용이 드러나는지가 중요해요.","좋은 제목이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L07_basic#10','kor',2,1,'u3','L07','g2_1_kor_u3_L07_basic','lesson_basic','K2-1-u3-C8',3,'error','auto','친구들이 하루에 겪은 일을 말했어요. 겪은 일이 아닌 것을 말한 친구는 누구인가요?',ARRAY['K2-1-u3-X12','K2-1-u3-X19']::text[],true,'{"seq":10,"concept":"K2-1-u3-C8","difficulty":3,"kind":"error","stem":"친구들이 하루에 겪은 일을 말했어요. 겪은 일이 아닌 것을 말한 친구는 누구인가요?","options":[{"t":"태민 — 「즐거움」","correct":true,"mis_target":"K2-1-u3-X12"},{"t":"하린 — 「친구와 줄넘기를 했어.」","mis":"K2-1-u3-X19"},{"t":"지안 — 「도서관에서 책을 읽었어.」","mis":"K2-1-u3-X19"}],"explanation":["「즐거움」은 느낌을 나타내는 낱말이에요.","줄넘기를 한 일, 책을 읽은 일은 겪은 일이에요.","「~했다·봤다·들었다」를 붙여 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구들이 하루에 겪은 일을 말했어요. 겪은 일이 아닌 것을 말한 친구는 누구인가요?","options":[{"t":"로아 — 「지우개」","correct":true,"mis_target":"K2-1-u3-X12"},{"t":"시우 — 「할머니께 전화를 드렸어.」","mis":"K2-1-u3-X19"},{"t":"은솔 — 「길에서 고양이를 봤어.」","mis":"K2-1-u3-X19"}],"explanation":["「지우개」는 물건이에요.","전화를 드린 일, 고양이를 본 일은 겪은 일이에요.","「~했다·봤다·들었다」를 붙여 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L07_challenge#1','kor',2,1,'u3','L07','g2_1_kor_u3_L07_challenge','lesson_challenge','K2-1-u3-C8',2,'mc','auto','글감을 정하는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X10','K2-1-u3-X14']::text[],false,'{"seq":1,"concept":"K2-1-u3-C8","difficulty":2,"kind":"mc","stem":"글감을 정하는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"한 것·본 것·들은 것 떠올리기 → 마음이 움직인 일 생각하기 → 가장 인상 깊은 일 고르기","correct":true},{"t":"가장 인상 깊은 일 고르기 → 한 것·본 것·들은 것 떠올리기 → 제목 쓰기","mis":"K2-1-u3-X10"},{"t":"제목 먼저 쓰기 → 아무 일이나 고르기","mis":"K2-1-u3-X14"}],"explanation":["먼저 하루를 떠올리고, 마음이 움직인 일을 찾아요.","그다음 가장 인상 깊은 일 하나를 골라요.","제목은 글감을 정한 뒤 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L07_challenge#2','kor',2,1,'u3','L07','g2_1_kor_u3_L07_challenge','lesson_challenge','K2-1-u3-C9',2,'mc','auto','두 제목 가운데 내용이 더 잘 드러나는 것은 어느 것인가요?',ARRAY['K2-1-u3-X14']::text[],false,'{"seq":2,"concept":"K2-1-u3-C9","difficulty":2,"kind":"mc","stem":"두 제목 가운데 내용이 더 잘 드러나는 것은 어느 것인가요?","options":[{"t":"「비 오는 날 무지개를 본 날」","correct":true},{"t":"「즐거운 날」","mis":"K2-1-u3-X14"},{"t":"「5월 3일」","mis":"K2-1-u3-X14"}],"explanation":["무슨 일이 있었는지 제목에서 알 수 있어요.","「즐거운 날」은 느낌만, 「5월 3일」은 날짜만 알려 줘요.","제목에는 겪은 일이 드러나야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L07_challenge#3','kor',2,1,'u3','L07','g2_1_kor_u3_L07_challenge','lesson_challenge','K2-1-u3-C8',3,'mc','auto','글을 읽고 답해 보세요. 서윤이가 「고마워.」라는 말을 들은 일을 글감으로 고른다면, 그 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X13']::text[],false,'{"seq":3,"concept":"K2-1-u3-C8","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 서윤이가 「고마워.」라는 말을 들은 일을 글감으로 고른다면, 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"그 말을 듣고 마음이 따뜻해져서 오래 기억하고 싶었기 때문이에요","correct":true},{"t":"오후에 있었던 일이기 때문이에요","mis":"K2-1-u3-X13"},{"t":"날마다 듣는 말이기 때문이에요","mis":"K2-1-u3-X13"}],"explanation":["마음이 움직여 기억하고 싶은 일이 좋은 글감이에요.","몇 시에 있었는지는 까닭이 되지 않아요.","날마다 듣는 말이라면 특별하지 않아요."],"asset":{"type":"passage","lines":["아침 — 엄마가 차려 주신 밥을 먹었다.","낮 — 텃밭에서 처음으로 상추를 땄다.","오후 — 친구에게 「고마워.」라는 말을 들었다.","저녁 — 숙제를 했다."],"title":"서윤이의 하루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L07_challenge#4','kor',2,1,'u3','L07','g2_1_kor_u3_L07_challenge','lesson_challenge','K2-1-u3-C9',3,'error','auto','「처음으로 바다에서 수영한 날」이 글감이에요. 제목을 알맞지 않게 지은 친구는 누구인가요?',ARRAY['K2-1-u3-X14','K2-1-u3-X19']::text[],false,'{"seq":4,"concept":"K2-1-u3-C9","difficulty":3,"kind":"error","stem":"「처음으로 바다에서 수영한 날」이 글감이에요. 제목을 알맞지 않게 지은 친구는 누구인가요?","options":[{"t":"민지 — 「여름」","correct":true,"mis_target":"K2-1-u3-X14"},{"t":"아린 — 「바다에서 처음 수영한 날」","mis":"K2-1-u3-X19"},{"t":"지호 — 「파도와 첫 수영」","mis":"K2-1-u3-X19"}],"explanation":["「여름」만으로는 무슨 일인지 알 수 없어요.","바다·수영이 드러나야 내용을 알 수 있어요.","아린이와 지호는 내용이 드러나게 지었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L07_challenge#5','kor',2,1,'u3','L07','g2_1_kor_u3_L07_challenge','lesson_challenge','K2-1-u3-C10',3,'mc','auto','「친구들 앞에서 처음 발표를 했다.」를 겪었을 때 들 수 있는 느낌으로 가장 알맞지 않은 것은 어느 것인가요?',ARRAY['K2-1-u3-X19']::text[],false,'{"seq":5,"concept":"K2-1-u3-C10","difficulty":3,"kind":"mc","stem":"「친구들 앞에서 처음 발표를 했다.」를 겪었을 때 들 수 있는 느낌으로 가장 알맞지 않은 것은 어느 것인가요?","options":[{"t":"「배가 불러 졸렸다.」","correct":true},{"t":"「떨렸지만 끝까지 해서 뿌듯했다.」","mis":"K2-1-u3-X19"},{"t":"「긴장돼서 목소리가 작아졌다.」","mis":"K2-1-u3-X19"}],"explanation":["「배가 불러 졸렸다」는 발표와 어울리지 않는 느낌이에요.","떨림·뿌듯함·긴장은 발표할 때 들 수 있는 느낌이에요.","「알맞지 않은」을 묻는 물음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L07_challenge#6','kor',2,1,'u3','L07','g2_1_kor_u3_L07_challenge','lesson_challenge','K2-1-u3-C8',3,'ox','auto','「연필」, 「운동장」처럼 물건이나 장소 이름만 써도 겪은 일이 돼요.',ARRAY['K2-1-u3-X12']::text[],false,'{"seq":6,"concept":"K2-1-u3-C8","difficulty":3,"kind":"ox","stem":"「연필」, 「운동장」처럼 물건이나 장소 이름만 써도 겪은 일이 돼요.","answer":"X","reason_options":[{"t":"무엇을 했는지·보았는지·들었는지가 있어야 겪은 일이니까","correct":true},{"t":"이름만 써도 무슨 일인지 다 알 수 있으니까","mis":"K2-1-u3-X12"}],"mis":"K2-1-u3-X12","explanation":["「운동장에서 줄넘기를 했다」처럼 써야 겪은 일이에요.","이름만으로는 무슨 일이 있었는지 알 수 없어요.","「~했다·봤다·들었다」를 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L07_challenge#7','kor',2,1,'u3','L07','g2_1_kor_u3_L07_challenge','lesson_challenge','K2-1-u3-C8',3,'mc','auto','글을 읽고 답해 보세요. 하준이의 하루를 「한 것·본 것」으로 나눌 때 「본 것」은 어느 것인가요?',ARRAY['K2-1-u3-X19']::text[],false,'{"seq":7,"concept":"K2-1-u3-C8","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 하준이의 하루를 「한 것·본 것」으로 나눌 때 「본 것」은 어느 것인가요?","options":[{"t":"맑은 하늘","correct":true},{"t":"줄넘기 열 번","mis":"K2-1-u3-X19"},{"t":"이 닦기","mis":"K2-1-u3-X19"}],"explanation":["창밖으로 맑은 하늘을 「보았다」고 했어요.","줄넘기와 이 닦기는 「한 것」이에요.","어떤 낱말로 끝나는지 보면 나눌 수 있어요."],"asset":{"type":"passage","lines":["아침 — 창밖으로 맑은 하늘을 보았다.","낮 — 운동장에서 처음으로 줄넘기 열 번을 넘었다.","저녁 — 동생과 그림책을 읽었다.","자기 전 — 이를 닦았다."],"title":"하준이의 하루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L07_challenge#8','kor',2,1,'u3','L07','g2_1_kor_u3_L07_challenge','lesson_challenge','K2-1-u3-C8',4,'mc','auto','두 친구가 글감을 정했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L07_challenge#9','kor',2,1,'u3','L07','g2_1_kor_u3_L07_challenge','lesson_challenge','K2-1-u3-C8',4,'essay','teacher','어제 하루를 떠올려 한 것·본 것·들은 것을 하나씩 쓰고, 그 가운데 일기 글감으로 고를 일과 고른 까닭을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u3-C8","difficulty":4,"kind":"essay","stem":"어제 하루를 떠올려 한 것·본 것·들은 것을 하나씩 쓰고, 그 가운데 일기 글감으로 고를 일과 고른 까닭을 써 보세요.","answer_guide":{"answer":"예: 한 것 — 공원 산책, 본 것 — 무지개, 들은 것 — 새소리. 글감: 무지개를 본 일. 까닭: 처음 본 커다란 무지개가 정말 신기했기 때문이에요.","scoring_points":["한 것·본 것·들은 것을 하나씩 썼는가","글감으로 고를 일 하나를 정했는가","그 일을 고른 까닭(마음이 움직인 점)을 썼는가"]},"explanation":["하루 떠올리기.","글감 하나.","고른 까닭."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L07_challenge#10','kor',2,1,'u3','L07','g2_1_kor_u3_L07_challenge','lesson_challenge','K2-1-u3-C9',4,'essay','teacher','「동생과 함께 처음으로 김밥을 만들었다.」가 글감인 일기의 제목을 짓고, 그렇게 지은 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u3-C9","difficulty":4,"kind":"essay","stem":"「동생과 함께 처음으로 김밥을 만들었다.」가 글감인 일기의 제목을 짓고, 그렇게 지은 까닭을 써 보세요.","answer_guide":{"answer":"예: 「동생과 만든 첫 김밥」 — 누구와 무엇을 처음 했는지 제목만 보아도 알 수 있게 지었어요.","scoring_points":["제목을 지었는가","제목에 겪은 일(김밥 만들기)이 드러나는가","지은 까닭을 썼는가"]},"explanation":["제목.","내용이 드러남.","까닭."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L09_basic#1','kor',2,1,'u3','L09','g2_1_kor_u3_L09_basic','lesson_basic','K2-1-u3-C7',1,'mc','auto','일기에서 맨 처음에 쓰는 것은 어느 것인가요?',ARRAY['K2-1-u3-X10']::text[],true,'{"seq":1,"concept":"K2-1-u3-C7","difficulty":1,"kind":"mc","stem":"일기에서 맨 처음에 쓰는 것은 어느 것인가요?","options":[{"t":"날짜·요일·날씨","correct":true},{"t":"생각이나 느낌","mis":"K2-1-u3-X10"},{"t":"제목","mis":"K2-1-u3-X10"}],"explanation":["일기는 날짜·요일·날씨부터 써요.","그다음 제목, 이어서 겪은 일과 생각이나 느낌을 써요.","차례를 지켜 쓰면 읽기 쉬워요."],"variant_rule":{"alt":[{"stem":"일기에서 맨 마지막 부분에 담는 것은 어느 것인가요?","options":[{"t":"겪은 일에 대한 생각이나 느낌","correct":true},{"t":"날짜와 날씨","mis":"K2-1-u3-X10"},{"t":"제목","mis":"K2-1-u3-X10"}],"explanation":["겪은 일을 쓰고 그때의 생각이나 느낌으로 마무리해요.","날짜·날씨와 제목은 앞부분에 써요.","차례: 날짜·날씨 → 제목 → 겪은 일 → 생각이나 느낌."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L09_basic#2','kor',2,1,'u3','L09','g2_1_kor_u3_L09_basic','lesson_basic','K2-1-u3-C10',1,'mc','auto','일기에 생각이나 느낌을 쓸 때 가장 알맞은 방법은 어느 것인가요?',ARRAY['K2-1-u3-X15']::text[],true,'{"seq":2,"concept":"K2-1-u3-C10","difficulty":1,"kind":"mc","stem":"일기에 생각이나 느낌을 쓸 때 가장 알맞은 방법은 어느 것인가요?","options":[{"t":"그때 든 마음을 솔직하게 써요","correct":true},{"t":"친구가 느꼈을 마음을 대신 써요","mis":"K2-1-u3-X15"},{"t":"느낌은 빼고 한 일만 써요","mis":"K2-1-u3-X15"}],"explanation":["일기에는 내 마음을 솔직하게 써요.","남의 느낌을 쓰거나 느낌을 빼면 그날의 내가 드러나지 않아요.","작은 일이라도 솔직하게 쓰면 좋은 일기예요."],"variant_rule":{"alt":[{"stem":"일기에 겪은 일을 쓸 때 가장 알맞은 방법은 어느 것인가요?","options":[{"t":"언제·어디서·누구와 무슨 일이 있었는지 자세하게 써요","correct":true},{"t":"「놀았다.」처럼 짧게만 써요","mis":"K2-1-u3-X16"},{"t":"겪지 않은 일도 지어서 써요","mis":"K2-1-u3-X15"}],"explanation":["언제·어디서·누구와를 쓰면 그날이 자세하게 드러나요.","짧게만 쓰면 무슨 일인지 잘 알 수 없어요.","일기는 내가 겪은 일을 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L09_basic#3','kor',2,1,'u3','L09','g2_1_kor_u3_L09_basic','lesson_basic','K2-1-u3-C7',1,'mc','auto','일기에 꼭 들어갈 내용이 아닌 것은 어느 것인가요?',ARRAY['K2-1-u3-X19']::text[],true,'{"seq":3,"concept":"K2-1-u3-C7","difficulty":1,"kind":"mc","stem":"일기에 꼭 들어갈 내용이 아닌 것은 어느 것인가요?","options":[{"t":"친구 전화번호","correct":true},{"t":"겪은 일","mis":"K2-1-u3-X19"},{"t":"생각이나 느낌","mis":"K2-1-u3-X19"}],"explanation":["전화번호는 그날을 돌아보는 내용이 아니에요.","겪은 일과 생각이나 느낌은 꼭 들어가요.","「아닌 것」을 묻는 물음이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 일기에 꼭 들어갈 내용이 아닌 것은 어느 것인가요?","options":[{"t":"내일 시간표","correct":true},{"t":"날짜와 날씨","mis":"K2-1-u3-X19"},{"t":"겪은 일","mis":"K2-1-u3-X19"}],"explanation":["내일 시간표는 그날을 돌아보는 내용이 아니에요.","날짜와 날씨, 겪은 일은 꼭 들어가요.","「아닌 것」을 묻는 물음이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L09_basic#4','kor',2,1,'u3','L09','g2_1_kor_u3_L09_basic','lesson_basic','K2-1-u3-C10',1,'ox','auto','일기는 작은 일이라도 마음이 움직였다면 좋은 일기가 될 수 있어요.',ARRAY['K2-1-u3-X13']::text[],true,'{"seq":4,"concept":"K2-1-u3-C10","difficulty":1,"kind":"ox","stem":"일기는 작은 일이라도 마음이 움직였다면 좋은 일기가 될 수 있어요.","answer":"O","reason_options":[{"t":"마음이 움직인 일을 솔직하게 쓰면 되니까","correct":true},{"t":"큰일이 있었던 날에만 쓸 수 있으니까","mis":"K2-1-u3-X13"}],"mis":"K2-1-u3-X13","explanation":["작은 일도 마음이 움직였다면 좋은 글감이에요.","특별한 날에만 쓰는 글이 아니에요.","솔직한 생각이나 느낌을 담아요."],"variant_rule":{"alt":[{"stem":"일기에는 겪은 일만 쓰고 생각이나 느낌은 쓰지 않아요.","answer":"X","reason_options":[{"t":"겪은 일에 대한 생각이나 느낌도 함께 써야 하니까","correct":true},{"t":"느낌은 쓰면 안 되니까","mis":"K2-1-u3-X15"}],"explanation":["일기에는 생각이나 느낌을 꼭 함께 써요.","느낌이 빠지면 그날의 내 마음이 남지 않아요.","솔직하게 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L09_basic#5','kor',2,1,'u3','L09','g2_1_kor_u3_L09_basic','lesson_basic','K2-1-u3-C7',2,'match','auto','일기 요소와 알맞은 설명을 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u3-C7","difficulty":2,"kind":"match","stem":"일기 요소와 알맞은 설명을 이어 보세요.","pairs":[{"l":"날짜와 날씨","r":"맨 처음에 써요"},{"l":"제목","r":"내용을 잘 나타내요"},{"l":"생각이나 느낌","r":"솔직하게 써요"}],"mis":"K2-1-u3-X10","explanation":["날짜와 날씨는 맨 처음에 써요.","제목은 내용을 잘 나타내요.","생각이나 느낌은 솔직하게 써요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 일기 요소와 알맞은 설명을 이어 보세요.","pairs":[{"l":"겪은 일","r":"언제·어디서 무슨 일인지 자세히 써요"},{"l":"날씨","r":"「포근하게 맑은 날」처럼 생생하게 써요"},{"l":"제목","r":"날짜 다음에 써요"}],"explanation":["겪은 일은 언제·어디서 무슨 일인지 자세히 써요.","날씨도 꾸며 주는 말로 생생하게 쓸 수 있어요.","제목은 날짜·날씨 다음에 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L09_basic#6','kor',2,1,'u3','L09','g2_1_kor_u3_L09_basic','lesson_basic','K2-1-u3-C10',2,'mc','auto','일기에 쓰면 더 좋은 문장은 어느 것인가요?',ARRAY['K2-1-u3-X03','K2-1-u3-X06']::text[],true,'{"seq":6,"concept":"K2-1-u3-C10","difficulty":2,"kind":"mc","stem":"일기에 쓰면 더 좋은 문장은 어느 것인가요?","options":[{"t":"넓은 운동장에서 줄넘기를 신나게 했다.","correct":true},{"t":"운동장에서 줄넘기를 했다.","mis":"K2-1-u3-X03"},{"t":"줄넘기.","mis":"K2-1-u3-X06"}],"explanation":["「넓은」·「신나게」가 그날 모습을 생생하게 해요.","꾸며 주는 말이 없으면 덜 생생해요.","「줄넘기.」는 문장이 아니에요."],"variant_rule":{"alt":[{"stem":"일기에 쓰면 더 좋은 날씨 표현은 어느 것인가요?","options":[{"t":"포근하게 맑은 날","correct":true},{"t":"맑음","mis":"K2-1-u3-X03"},{"t":"날씨","mis":"K2-1-u3-X09"}],"explanation":["「포근하게」를 넣으니 그날 날씨가 느껴져요.","「맑음」도 되지만 덜 생생해요.","날씨도 꾸며 주는 말로 써 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L09_basic#7','kor',2,1,'u3','L09','g2_1_kor_u3_L09_basic','lesson_basic','K2-1-u3-C7',2,'mc','auto','글을 읽고 답해 보세요. 지호의 일기에서 「드디어 혼자 쭉 나아갔을 때 정말 뿌듯했다.」는 일기의 어느 부분인가요?',ARRAY['K2-1-u3-X10']::text[],true,'{"seq":7,"concept":"K2-1-u3-C7","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 지호의 일기에서 「드디어 혼자 쭉 나아갔을 때 정말 뿌듯했다.」는 일기의 어느 부분인가요?","options":[{"t":"생각이나 느낌","correct":true},{"t":"날짜와 날씨","mis":"K2-1-u3-X10"},{"t":"제목","mis":"K2-1-u3-X10"}],"explanation":["「뿌듯했다」는 지호의 느낌이에요.","날짜·날씨와 제목은 맨 위에 있어요.","일기는 생각이나 느낌으로 마무리해요."],"asset":{"type":"passage","lines":["5월 7일 화요일, 바람이 살랑살랑 부는 날","제목: 처음 탄 두발자전거","공원에서 아빠와 두발자전거 타기를 연습했다.","몇 번이나 넘어졌지만 페달을 힘껏 밟았다.","드디어 혼자 쭉 나아갔을 때 정말 뿌듯했다."],"title":"지호의 일기"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 지호의 일기에서 「바람이 살랑살랑 부는 날」은 일기의 어느 부분인가요?","options":[{"t":"날씨","correct":true},{"t":"제목","mis":"K2-1-u3-X10"},{"t":"생각이나 느낌","mis":"K2-1-u3-X10"}],"explanation":["「바람이 살랑살랑 부는 날」은 그날의 날씨예요.","제목은 「처음 탄 두발자전거」예요.","날씨도 꾸며 주는 말로 생생하게 썼어요."],"asset":{"type":"passage","lines":["5월 7일 화요일, 바람이 살랑살랑 부는 날","제목: 처음 탄 두발자전거","공원에서 아빠와 두발자전거 타기를 연습했다.","몇 번이나 넘어졌지만 페달을 힘껏 밟았다.","드디어 혼자 쭉 나아갔을 때 정말 뿌듯했다."],"title":"지호의 일기"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L09_basic#8','kor',2,1,'u3','L09','g2_1_kor_u3_L09_basic','lesson_basic','K2-1-u3-C7',2,'sa','auto','글을 읽고 답해 보세요. 지호의 일기 제목을 그대로 써 보세요.','{}'::text[],true,'{"seq":8,"concept":"K2-1-u3-C7","difficulty":2,"kind":"sa","stem":"글을 읽고 답해 보세요. 지호의 일기 제목을 그대로 써 보세요.","answer":["처음 탄 두발자전거"],"explanation":["제목은 「처음 탄 두발자전거」예요.","제목은 날짜·날씨 다음에 있어요.","제목만 보아도 무슨 일인지 알 수 있어요."],"asset":{"type":"passage","lines":["5월 7일 화요일, 바람이 살랑살랑 부는 날","제목: 처음 탄 두발자전거","공원에서 아빠와 두발자전거 타기를 연습했다.","몇 번이나 넘어졌지만 페달을 힘껏 밟았다.","드디어 혼자 쭉 나아갔을 때 정말 뿌듯했다."],"title":"지호의 일기"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 지호가 자전거 타기를 연습한 곳은 어디인가요? 한 낱말로 써 보세요.","answer":["공원","공원에서"],"explanation":["「공원에서 아빠와 두발자전거 타기를 연습했다.」라고 했어요.","어디서 했는지 써 두어 일기가 자세해요.","글에서 찾아 짚어 봐요."],"asset":{"type":"passage","lines":["5월 7일 화요일, 바람이 살랑살랑 부는 날","제목: 처음 탄 두발자전거","공원에서 아빠와 두발자전거 타기를 연습했다.","몇 번이나 넘어졌지만 페달을 힘껏 밟았다.","드디어 혼자 쭉 나아갔을 때 정말 뿌듯했다."],"title":"지호의 일기"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L09_basic#9','kor',2,1,'u3','L09','g2_1_kor_u3_L09_basic','lesson_basic','K2-1-u3-C10',2,'ox','auto','글을 읽고 답해 보세요. 다은이의 일기는 겪은 일과 생각이나 느낌이 잘 드러난 일기예요.',ARRAY['K2-1-u3-X15']::text[],true,'{"seq":9,"concept":"K2-1-u3-C10","difficulty":2,"kind":"ox","stem":"글을 읽고 답해 보세요. 다은이의 일기는 겪은 일과 생각이나 느낌이 잘 드러난 일기예요.","answer":"X","reason_options":[{"t":"한 일만 짧게 늘어놓고 생각이나 느낌이 없으니까","correct":true},{"t":"날짜와 날씨가 있으면 좋은 일기니까","mis":"K2-1-u3-X15"}],"mis":"K2-1-u3-X15","explanation":["다은이는 한 일만 짧게 썼어요.","어떤 떡을 왜 샀는지, 그때 마음이 어땠는지 없어요.","생각이나 느낌을 솔직하게 더하면 좋아요."],"asset":{"type":"passage","lines":["6월 2일 월요일, 맑음","제목: 시장","시장에 갔다. 떡을 샀다. 집에 왔다."],"title":"다은이의 일기"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 지호의 일기는 겪은 일과 느낌이 잘 드러난 일기예요.","answer":"O","reason_options":[{"t":"어디서 누구와 무엇을 했는지와 뿌듯한 느낌이 있으니까","correct":true},{"t":"제목이 길어서 좋은 일기니까","mis":"K2-1-u3-X15"}],"explanation":["공원에서 아빠와 연습한 일이 자세해요.","「뿌듯했다」로 느낌을 솔직하게 썼어요.","그래서 그날이 잘 드러나요."],"asset":{"type":"passage","lines":["5월 7일 화요일, 바람이 살랑살랑 부는 날","제목: 처음 탄 두발자전거","공원에서 아빠와 두발자전거 타기를 연습했다.","몇 번이나 넘어졌지만 페달을 힘껏 밟았다.","드디어 혼자 쭉 나아갔을 때 정말 뿌듯했다."],"title":"지호의 일기"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L09_basic#10','kor',2,1,'u3','L09','g2_1_kor_u3_L09_basic','lesson_basic','K2-1-u3-C7',3,'error','auto','일기를 쓰는 차례를 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K2-1-u3-X10','K2-1-u3-X19']::text[],true,'{"seq":10,"concept":"K2-1-u3-C7","difficulty":3,"kind":"error","stem":"일기를 쓰는 차례를 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「제목을 맨 먼저 쓰고, 날짜는 맨 끝에 써.」","correct":true,"mis_target":"K2-1-u3-X10"},{"t":"하람 — 「날짜와 날씨를 쓰고 그다음 제목을 써.」","mis":"K2-1-u3-X19"},{"t":"준우 — 「겪은 일을 쓰고 생각이나 느낌을 써.」","mis":"K2-1-u3-X19"}],"explanation":["날짜·날씨가 맨 처음, 그다음이 제목이에요.","날짜를 맨 끝에 쓰지 않아요.","하람이와 준우는 바르게 말했어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 일기를 쓰는 차례를 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"현우 — 「느낌을 먼저 쓰고, 겪은 일은 맨 끝에 날짜와 함께 써.」","correct":true,"mis_target":"K2-1-u3-X10"},{"t":"은솔 — 「맨 처음에 날짜·요일·날씨를 써.」","mis":"K2-1-u3-X19"},{"t":"다은 — 「제목 다음에 겪은 일을 자세히 써.」","mis":"K2-1-u3-X19"}],"explanation":["겪은 일을 쓴 뒤 그에 대한 느낌을 써요.","날짜는 맨 처음에 써요.","은솔이와 다은이는 바르게 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L09_challenge#1','kor',2,1,'u3','L09','g2_1_kor_u3_L09_challenge','lesson_challenge','K2-1-u3-C9',2,'mc','auto','글을 읽고 답해 보세요. 다은이의 일기 제목 「시장」을 내용이 잘 드러나게 고친 것은 어느 것인가요?',ARRAY['K2-1-u3-X14']::text[],false,'{"seq":1,"concept":"K2-1-u3-C9","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 다은이의 일기 제목 「시장」을 내용이 잘 드러나게 고친 것은 어느 것인가요?","options":[{"t":"「시장에서 산 떡」","correct":true},{"t":"「월요일」","mis":"K2-1-u3-X14"},{"t":"「일기」","mis":"K2-1-u3-X14"}],"explanation":["무엇을 했는지 제목에서 알 수 있어요.","「월요일」, 「일기」로는 내용을 알 수 없어요.","제목에 겪은 일이 드러나야 해요."],"asset":{"type":"passage","lines":["6월 2일 월요일, 맑음","제목: 시장","시장에 갔다. 떡을 샀다. 집에 왔다."],"title":"다은이의 일기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L09_challenge#2','kor',2,1,'u3','L09','g2_1_kor_u3_L09_challenge','lesson_challenge','K2-1-u3-C10',2,'mc','auto','글을 읽고 답해 보세요. 다은이의 일기에 덧붙이면 가장 좋은 문장은 어느 것인가요?',ARRAY['K2-1-u3-X15','K2-1-u3-X11']::text[],false,'{"seq":2,"concept":"K2-1-u3-C10","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 다은이의 일기에 덧붙이면 가장 좋은 문장은 어느 것인가요?","options":[{"t":"「갓 쪄서 말랑말랑한 떡을 먹으니 입안이 따뜻해져 행복했다.」","correct":true},{"t":"「시장에 갔다.」","mis":"K2-1-u3-X15"},{"t":"「내일 시간표: 국어, 수학」","mis":"K2-1-u3-X11"}],"explanation":["떡의 모습과 그때의 느낌이 생생하게 드러나요.","이미 쓴 말을 되풀이하면 나아지지 않아요.","시간표는 일기와 관계없어요."],"asset":{"type":"passage","lines":["6월 2일 월요일, 맑음","제목: 시장","시장에 갔다. 떡을 샀다. 집에 왔다."],"title":"다은이의 일기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L09_challenge#3','kor',2,1,'u3','L09','g2_1_kor_u3_L09_challenge','lesson_challenge','K2-1-u3-C7',3,'mc','auto','글을 읽고 답해 보세요. 도윤이의 일기에서 빠진 것은 어느 것인가요?',ARRAY['K2-1-u3-X09']::text[],false,'{"seq":3,"concept":"K2-1-u3-C7","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 도윤이의 일기에서 빠진 것은 어느 것인가요?","options":[{"t":"생각이나 느낌","correct":true},{"t":"날짜와 날씨","mis":"K2-1-u3-X09"},{"t":"제목","mis":"K2-1-u3-X09"}],"explanation":["송편을 빚은 일은 썼지만 그때 마음이 없어요.","날짜·날씨와 제목은 맨 위에 있어요.","「빠진 것」을 묻는 물음이에요."],"asset":{"type":"passage","lines":["4월 18일 금요일, 구름 조금","제목: 할머니와 만든 송편","저녁에 할머니 댁 부엌에서 송편을 빚었다.","할머니께서 반죽을 동글동글 굴리는 방법을 알려 주셨다."],"title":"도윤이의 일기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L09_challenge#4','kor',2,1,'u3','L09','g2_1_kor_u3_L09_challenge','lesson_challenge','K2-1-u3-C7',3,'mc','auto','글을 읽고 답해 보세요. 시우의 일기에서 빠진 것은 어느 것인가요?',ARRAY['K2-1-u3-X09']::text[],false,'{"seq":4,"concept":"K2-1-u3-C7","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 시우의 일기에서 빠진 것은 어느 것인가요?","options":[{"t":"날짜·요일·날씨","correct":true},{"t":"생각이나 느낌","mis":"K2-1-u3-X09"},{"t":"겪은 일","mis":"K2-1-u3-X09"}],"explanation":["시우는 맨 처음에 쓸 날짜·요일·날씨를 빠뜨렸어요.","「무척 신기했다」는 느낌이 있어요.","무지개를 본 겪은 일도 있어요."],"asset":{"type":"passage","lines":["제목: 운동장의 무지개","점심시간에 운동장에서 커다란 무지개를 보았다.","일곱 빛깔이 또렷해서 친구들과 와 하고 소리쳤다.","무지개를 처음 가까이 본 것 같아 무척 신기했다."],"title":"시우의 일기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L09_challenge#5','kor',2,1,'u3','L09','g2_1_kor_u3_L09_challenge','lesson_challenge','K2-1-u3-C10',3,'error','auto','친구들이 지호의 일기를 읽고 잘된 점을 말했어요. 글과 다르게 말한 친구는 누구인가요?',ARRAY['K2-1-u3-X07','K2-1-u3-X19']::text[],false,'{"seq":5,"concept":"K2-1-u3-C10","difficulty":3,"kind":"error","stem":"친구들이 지호의 일기를 읽고 잘된 점을 말했어요. 글과 다르게 말한 친구는 누구인가요?","options":[{"t":"도담 — 「엄마랑 자전거를 탄 일을 썼어.」","correct":true,"mis_target":"K2-1-u3-X07"},{"t":"하늘 — 「어디서 누구와 했는지 자세히 썼어.」","mis":"K2-1-u3-X19"},{"t":"로아 — 「뿌듯한 마음을 솔직하게 썼어.」","mis":"K2-1-u3-X19"}],"explanation":["지호는 아빠와 연습했어요.","글에 없는 내용을 말하면 안 돼요.","하늘이와 로아는 글과 같게 말했어요."],"asset":{"type":"passage","lines":["5월 7일 화요일, 바람이 살랑살랑 부는 날","제목: 처음 탄 두발자전거","공원에서 아빠와 두발자전거 타기를 연습했다.","몇 번이나 넘어졌지만 페달을 힘껏 밟았다.","드디어 혼자 쭉 나아갔을 때 정말 뿌듯했다."],"title":"지호의 일기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L09_challenge#6','kor',2,1,'u3','L09','g2_1_kor_u3_L09_challenge','lesson_challenge','K2-1-u3-C10',3,'ox','auto','글을 읽고 답해 보세요. 도윤이의 일기에 「할머니처럼 반죽을 동글동글 굴리니 송편이 예쁘게 빚어져서 무척 뿌듯했다.」를 덧붙이면 더 좋은 일기가 돼요.',ARRAY['K2-1-u3-X15']::text[],false,'{"seq":6,"concept":"K2-1-u3-C10","difficulty":3,"kind":"ox","stem":"글을 읽고 답해 보세요. 도윤이의 일기에 「할머니처럼 반죽을 동글동글 굴리니 송편이 예쁘게 빚어져서 무척 뿌듯했다.」를 덧붙이면 더 좋은 일기가 돼요.","answer":"O","reason_options":[{"t":"빠졌던 생각이나 느낌이 생겨 그날 마음이 드러나니까","correct":true},{"t":"글자가 많아질수록 좋은 일기니까","mis":"K2-1-u3-X15"}],"mis":"K2-1-u3-X15","explanation":["도윤이의 일기에는 느낌이 빠져 있었어요.","덧붙인 문장에 뿌듯한 마음이 담겨요.","길이가 아니라 느낌이 생겨서 좋아진 거예요."],"asset":{"type":"passage","lines":["4월 18일 금요일, 구름 조금","제목: 할머니와 만든 송편","저녁에 할머니 댁 부엌에서 송편을 빚었다.","할머니께서 반죽을 동글동글 굴리는 방법을 알려 주셨다."],"title":"도윤이의 일기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L09_challenge#7','kor',2,1,'u3','L09','g2_1_kor_u3_L09_challenge','lesson_challenge','K2-1-u3-C10',3,'mc','auto','일기를 다 쓰고 스스로 점검할 때 살펴볼 것으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K2-1-u3-X19']::text[],false,'{"seq":7,"concept":"K2-1-u3-C10","difficulty":3,"kind":"mc","stem":"일기를 다 쓰고 스스로 점검할 때 살펴볼 것으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"글씨를 가장 크게 썼나요?","correct":true},{"t":"날짜와 요일을 정확하게 썼나요?","mis":"K2-1-u3-X19"},{"t":"겪은 일에 대한 생각이나 느낌을 솔직하게 썼나요?","mis":"K2-1-u3-X19"}],"explanation":["글씨 크기는 점검할 내용이 아니에요.","날짜·요일과 생각이나 느낌은 꼭 점검해요.","「알맞지 않은」을 묻는 물음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L09_challenge#8','kor',2,1,'u3','L09','g2_1_kor_u3_L09_challenge','lesson_challenge','K2-1-u3-C10',4,'mc','auto','두 친구가 같은 날 운동회 일기를 썼어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L09_challenge#9','kor',2,1,'u3','L09','g2_1_kor_u3_L09_challenge','lesson_challenge','K2-1-u3-C10',4,'essay','teacher','다은이의 일기 「시장에 갔다. 떡을 샀다. 집에 왔다.」를 언제·누구와·어떤 떡이었는지, 그리고 그때의 느낌이 드러나게 고쳐 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u3-C10","difficulty":4,"kind":"essay","stem":"다은이의 일기 「시장에 갔다. 떡을 샀다. 집에 왔다.」를 언제·누구와·어떤 떡이었는지, 그리고 그때의 느낌이 드러나게 고쳐 써 보세요.","answer_guide":{"answer":"예: 아침에 엄마와 시장에 갔다. 김이 모락모락 나는 말랑말랑한 꿀떡을 샀다. 집에 와서 먹으니 달콤해서 기분이 정말 좋았다.","scoring_points":["언제·누구와 같은 내용을 더했는가","꾸며 주는 말로 떡이나 장면을 생생하게 나타냈는가","그때의 생각이나 느낌을 솔직하게 썼는가"]},"explanation":["언제·누구와.","꾸며 주는 말.","느낌."],"asset":{"type":"passage","lines":["6월 2일 월요일, 맑음","제목: 시장","시장에 갔다. 떡을 샀다. 집에 왔다."],"title":"다은이의 일기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L09_challenge#10','kor',2,1,'u3','L09','g2_1_kor_u3_L09_challenge','lesson_challenge','K2-1-u3-C7',4,'essay','teacher','최근에 겪은 인상 깊은 일로 짧은 일기를 써 보세요. 날짜·요일·날씨, 제목, 겪은 일, 생각이나 느낌을 모두 넣어요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u3-C7","difficulty":4,"kind":"essay","stem":"최근에 겪은 인상 깊은 일로 짧은 일기를 써 보세요. 날짜·요일·날씨, 제목, 겪은 일, 생각이나 느낌을 모두 넣어요.","answer_guide":{"answer":"예: 10월 9일 금요일, 하늘이 높고 파란 날 / 제목: 처음 따 본 밤 / 할아버지와 뒷산에서 밤을 주웠다. 가시가 뾰족뾰족해서 조심조심 껍질을 벌렸다. 반짝반짝 윤이 나는 밤을 보니 무척 신기했다.","scoring_points":["날짜·요일·날씨와 제목을 차례대로 썼는가","언제·어디서·누구와 무슨 일인지 자세히 썼는가","생각이나 느낌을 솔직하게 썼는가"]},"explanation":["날짜·날씨·제목.","자세한 겪은 일.","솔직한 느낌."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L12_basic#1','kor',2,1,'u3','L12','g2_1_kor_u3_L12_basic','lesson_basic','K2-1-u3-C11',1,'mc','auto','식물이나 물건을 자세히 살펴보고 쓰는 일기는 어느 것인가요?',ARRAY['K2-1-u3-X17']::text[],true,'{"seq":1,"concept":"K2-1-u3-C11","difficulty":1,"kind":"mc","stem":"식물이나 물건을 자세히 살펴보고 쓰는 일기는 어느 것인가요?","options":[{"t":"관찰 일기","correct":true},{"t":"요리 일기","mis":"K2-1-u3-X17"},{"t":"그림 일기","mis":"K2-1-u3-X17"}],"explanation":["자세히 살펴본 모습을 쓰는 일기는 관찰 일기예요.","요리 일기는 음식을 만든 차례를 써요.","그림 일기는 그림과 글로 함께 나타내요."],"variant_rule":{"alt":[{"stem":"음식을 만든 차례를 쓰는 일기는 어느 것인가요?","options":[{"t":"요리 일기","correct":true},{"t":"관찰 일기","mis":"K2-1-u3-X17"},{"t":"그림 일기","mis":"K2-1-u3-X17"}],"explanation":["음식을 만든 차례를 쓰는 일기는 요리 일기예요.","관찰 일기는 자세히 살핀 모습을 써요.","그림 일기는 그림과 글로 함께 나타내요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L12_basic#2','kor',2,1,'u3','L12','g2_1_kor_u3_L12_basic','lesson_basic','K2-1-u3-C4',1,'mc','auto','방울토마토를 관찰하고 쓰려고 해요. 방울토마토에 어울리는 꾸며 주는 말은 어느 것인가요?',ARRAY['K2-1-u3-X04']::text[],true,'{"seq":2,"concept":"K2-1-u3-C4","difficulty":1,"kind":"mc","stem":"방울토마토를 관찰하고 쓰려고 해요. 방울토마토에 어울리는 꾸며 주는 말은 어느 것인가요?","options":[{"t":"동그란","correct":true},{"t":"시끄러운","mis":"K2-1-u3-X04"},{"t":"졸린","mis":"K2-1-u3-X04"}],"explanation":["방울토마토의 모양에는 「동그란」이 어울려요.","방울토마토는 시끄럽거나 졸리지 않아요.","관찰한 모습에 맞는 말을 골라요."],"asset":{"type":"scene","icon":"🍅"},"variant_rule":{"alt":[{"stem":"상추 잎을 관찰하고 쓰려고 해요. 상추 잎에 어울리는 꾸며 주는 말은 어느 것인가요?","options":[{"t":"넓적한","correct":true},{"t":"뾰족한 가시가 난","mis":"K2-1-u3-X04"},{"t":"달리는","mis":"K2-1-u3-X04"}],"explanation":["상추 잎의 모양에는 「넓적한」이 어울려요.","상추 잎에는 가시가 없고, 달리지도 않아요.","관찰한 모습에 맞는 말을 골라요."],"asset":{"type":"scene","icon":"🥬"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L12_basic#3','kor',2,1,'u3','L12','g2_1_kor_u3_L12_basic','lesson_basic','K2-1-u3-C11',1,'mc','auto','식물을 관찰할 때 살펴볼 점은 어느 것인가요?',ARRAY['K2-1-u3-X17']::text[],true,'{"seq":3,"concept":"K2-1-u3-C11","difficulty":1,"kind":"mc","stem":"식물을 관찰할 때 살펴볼 점은 어느 것인가요?","options":[{"t":"잎의 색과 모양","correct":true},{"t":"식물의 가격","mis":"K2-1-u3-X17"},{"t":"화분을 만든 사람","mis":"K2-1-u3-X17"}],"explanation":["색과 모양은 눈으로 살펴 알 수 있어요.","가격이나 만든 사람은 관찰해서 알 수 없어요.","눈·코·손으로 알 수 있는 것을 살펴요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 식물을 관찰할 때 살펴볼 점은 어느 것인가요?","options":[{"t":"꽃의 냄새","correct":true},{"t":"화분을 산 가게 이름","mis":"K2-1-u3-X17"},{"t":"식물의 값","mis":"K2-1-u3-X17"}],"explanation":["꽃의 냄새는 코로 맡아 알 수 있어요.","가게 이름이나 값은 관찰해서 알 수 없어요.","여러 감각으로 살펴요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L12_basic#4','kor',2,1,'u3','L12','g2_1_kor_u3_L12_basic','lesson_basic','K2-1-u3-C11',1,'ox','auto','관찰할 때는 눈뿐 아니라 코와 손으로도 살펴볼 수 있어요.',ARRAY['K2-1-u3-X17']::text[],true,'{"seq":4,"concept":"K2-1-u3-C11","difficulty":1,"kind":"ox","stem":"관찰할 때는 눈뿐 아니라 코와 손으로도 살펴볼 수 있어요.","answer":"O","reason_options":[{"t":"냄새와 촉감도 관찰한 모습이니까","correct":true},{"t":"관찰은 눈으로만 하는 것이니까","mis":"K2-1-u3-X17"}],"mis":"K2-1-u3-X17","explanation":["색·모양은 눈으로, 냄새는 코로, 촉감은 손으로 살펴요.","여러 감각을 쓰면 더 자세히 쓸 수 있어요.","그래서 관찰 일기가 생생해져요."],"variant_rule":{"alt":[{"stem":"관찰 일기에는 관찰한 모습만 쓰고 생각이나 느낌은 쓰지 않아요.","answer":"X","reason_options":[{"t":"관찰한 모습에 생각이나 느낌을 더하면 더 좋은 일기니까","correct":true},{"t":"일기에 느낌을 쓰면 안 되니까","mis":"K2-1-u3-X09"}],"explanation":["관찰 일기에도 생각이나 느낌을 써요.","「무척 신기했다」처럼 마음을 더해요.","그래야 일기가 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L12_basic#5','kor',2,1,'u3','L12','g2_1_kor_u3_L12_basic','lesson_basic','K2-1-u3-C11',2,'match','auto','일기 종류와 쓰는 내용을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u3-C11","difficulty":2,"kind":"match","stem":"일기 종류와 쓰는 내용을 알맞게 이어 보세요.","pairs":[{"l":"관찰 일기","r":"자세히 살핀 모습"},{"l":"요리 일기","r":"음식을 만든 차례"},{"l":"그림 일기","r":"그림과 글"}],"mis":"K2-1-u3-X17","explanation":["관찰 일기는 자세히 살핀 모습을 써요.","요리 일기는 음식을 만든 차례를 써요.","그림 일기는 그림과 글로 함께 나타내요."],"variant_rule":{"alt":[{"stem":"관찰할 것과 알 수 있는 감각을 알맞게 이어 보세요.","pairs":[{"l":"잎의 색","r":"눈으로 봐요"},{"l":"꽃의 향기","r":"코로 맡아요"},{"l":"잎의 보들보들함","r":"손으로 만져요"}],"explanation":["색은 눈으로 봐서 알아요.","향기는 코로 맡아서 알아요.","보들보들한 촉감은 손으로 만져서 알아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L12_basic#6','kor',2,1,'u3','L12','g2_1_kor_u3_L12_basic','lesson_basic','K2-1-u3-C11',2,'mc','auto','글을 읽고 답해 보세요. 이 관찰 일기에서 「냄새」를 살펴본 문장은 어느 것인가요?',ARRAY['K2-1-u3-X07']::text[],true,'{"seq":6,"concept":"K2-1-u3-C11","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 이 관찰 일기에서 「냄새」를 살펴본 문장은 어느 것인가요?","options":[{"t":"코를 대 보니 풀 냄새가 살짝 났다.","correct":true},{"t":"사흘 만에 하얀 뿌리가 쏙 나왔다.","mis":"K2-1-u3-X07"},{"t":"내일은 얼마나 자랄지 무척 궁금하다.","mis":"K2-1-u3-X07"}],"explanation":["코를 대어 냄새를 맡았어요.","뿌리 문장은 눈으로 본 모습이에요.","「궁금하다」는 느낌이에요."],"asset":{"type":"passage","lines":["제목: 콩이 싹텄어요","물에 적신 솜 위에 콩을 올려 두었다.","사흘 만에 하얀 뿌리가 쏙 나왔다.","오늘은 연두색 떡잎 두 장이 동그랗게 벌어졌다.","코를 대 보니 풀 냄새가 살짝 났다.","내일은 얼마나 자랄지 무척 궁금하다."],"title":"관찰 일기"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 이 관찰 일기에서 「생각이나 느낌」이 드러난 문장은 어느 것인가요?","options":[{"t":"내일은 얼마나 자랄지 무척 궁금하다.","correct":true},{"t":"물에 적신 솜 위에 콩을 올려 두었다.","mis":"K2-1-u3-X07"},{"t":"사흘 만에 하얀 뿌리가 쏙 나왔다.","mis":"K2-1-u3-X07"}],"explanation":["「궁금하다」는 글쓴이의 마음이에요.","다른 두 문장은 한 일과 본 모습이에요.","관찰 일기에도 느낌을 써요."],"asset":{"type":"passage","lines":["제목: 콩이 싹텄어요","물에 적신 솜 위에 콩을 올려 두었다.","사흘 만에 하얀 뿌리가 쏙 나왔다.","오늘은 연두색 떡잎 두 장이 동그랗게 벌어졌다.","코를 대 보니 풀 냄새가 살짝 났다.","내일은 얼마나 자랄지 무척 궁금하다."],"title":"관찰 일기"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L12_basic#7','kor',2,1,'u3','L12','g2_1_kor_u3_L12_basic','lesson_basic','K2-1-u3-C11',2,'mc','auto','글을 읽고 답해 보세요. 요리 일기에서 가장 먼저 한 일은 무엇인가요?',ARRAY['K2-1-u3-X07']::text[],true,'{"seq":7,"concept":"K2-1-u3-C11","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 요리 일기에서 가장 먼저 한 일은 무엇인가요?","options":[{"t":"손을 깨끗이 씻었다","correct":true},{"t":"밥을 동글동글 뭉쳤다","mis":"K2-1-u3-X07"},{"t":"가족이 맛있게 먹었다","mis":"K2-1-u3-X07"}],"explanation":["「먼저 손을 깨끗이 씻었다.」라고 했어요.","밥을 뭉친 것은 그다음이에요.","요리 일기는 만든 차례대로 써요."],"asset":{"type":"passage","lines":["제목: 내가 만든 주먹밥","먼저 손을 깨끗이 씻었다.","따뜻한 밥에 김 가루와 깨를 솔솔 뿌려 섞었다.","손에 물을 묻히고 밥을 동글동글 뭉쳤다.","내가 만든 주먹밥을 가족이 맛있게 먹어서 뿌듯했다."],"title":"요리 일기"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 요리 일기에서 김 가루와 깨를 뿌린 다음에 한 일은 무엇인가요?","options":[{"t":"손에 물을 묻히고 밥을 뭉쳤다","correct":true},{"t":"손을 깨끗이 씻었다","mis":"K2-1-u3-X07"},{"t":"콩을 솜 위에 올렸다","mis":"K2-1-u3-X07"}],"explanation":["섞은 다음 밥을 동글동글 뭉쳤어요.","손 씻기는 맨 처음이에요.","콩 이야기는 이 글에 없어요."],"asset":{"type":"passage","lines":["제목: 내가 만든 주먹밥","먼저 손을 깨끗이 씻었다.","따뜻한 밥에 김 가루와 깨를 솔솔 뿌려 섞었다.","손에 물을 묻히고 밥을 동글동글 뭉쳤다.","내가 만든 주먹밥을 가족이 맛있게 먹어서 뿌듯했다."],"title":"요리 일기"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L12_basic#8','kor',2,1,'u3','L12','g2_1_kor_u3_L12_basic','lesson_basic','K2-1-u3-C11',2,'sa','auto','글을 읽고 답해 보세요. 오늘 벌어진 떡잎은 몇 장인가요? 숫자로 써 보세요.','{}'::text[],true,'{"seq":8,"concept":"K2-1-u3-C11","difficulty":2,"kind":"sa","stem":"글을 읽고 답해 보세요. 오늘 벌어진 떡잎은 몇 장인가요? 숫자로 써 보세요.","answer":["2","2장","두","두 장"],"explanation":["「연두색 떡잎 두 장이 동그랗게 벌어졌다.」라고 했어요.","몇 장인지 세어 쓰면 관찰이 자세해져요.","글에서 찾아 짚어 봐요."],"asset":{"type":"passage","lines":["제목: 콩이 싹텄어요","물에 적신 솜 위에 콩을 올려 두었다.","사흘 만에 하얀 뿌리가 쏙 나왔다.","오늘은 연두색 떡잎 두 장이 동그랗게 벌어졌다.","코를 대 보니 풀 냄새가 살짝 났다.","내일은 얼마나 자랄지 무척 궁금하다."],"title":"관찰 일기"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 콩을 올려 두고 며칠 만에 뿌리가 나왔나요? 숫자로 써 보세요.","answer":["3","3일","사흘","삼"],"explanation":["「사흘 만에 하얀 뿌리가 쏙 나왔다.」라고 했어요.","사흘은 3일이에요.","날짜를 세어 쓰면 관찰이 자세해져요."],"asset":{"type":"passage","lines":["제목: 콩이 싹텄어요","물에 적신 솜 위에 콩을 올려 두었다.","사흘 만에 하얀 뿌리가 쏙 나왔다.","오늘은 연두색 떡잎 두 장이 동그랗게 벌어졌다.","코를 대 보니 풀 냄새가 살짝 났다.","내일은 얼마나 자랄지 무척 궁금하다."],"title":"관찰 일기"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L12_basic#9','kor',2,1,'u3','L12','g2_1_kor_u3_L12_basic','lesson_basic','K2-1-u3-C4',2,'ox','auto','관찰 일기에 「길쭉한 잎이 바람에 살랑살랑 흔들린다.」처럼 꾸며 주는 말을 넣으면 모습이 더 생생해져요.',ARRAY['K2-1-u3-X03']::text[],true,'{"seq":9,"concept":"K2-1-u3-C4","difficulty":2,"kind":"ox","stem":"관찰 일기에 「길쭉한 잎이 바람에 살랑살랑 흔들린다.」처럼 꾸며 주는 말을 넣으면 모습이 더 생생해져요.","answer":"O","reason_options":[{"t":"잎의 모양과 움직임이 떠오르니까","correct":true},{"t":"꾸며 주는 말은 관찰 일기에 쓰면 안 되니까","mis":"K2-1-u3-X03"}],"mis":"K2-1-u3-X03","explanation":["「길쭉한」·「살랑살랑」이 잎의 모습을 보여 줘요.","관찰 일기에도 꾸며 주는 말을 넣어요.","그래서 읽는 사람도 모습을 떠올려요."],"variant_rule":{"alt":[{"stem":"관찰 일기에는 「잎이 있다.」처럼 짧게만 쓰는 것이 가장 좋아요.","answer":"X","reason_options":[{"t":"모양·색을 꾸며 주는 말로 자세히 써야 모습이 드러나니까","correct":true},{"t":"짧을수록 관찰을 잘한 것이니까","mis":"K2-1-u3-X03"}],"explanation":["「잎이 있다.」로는 어떤 잎인지 알 수 없어요.","「넓적한 초록 잎」처럼 자세히 써요.","꾸며 주는 말이 관찰한 모습을 살려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L12_basic#10','kor',2,1,'u3','L12','g2_1_kor_u3_L12_basic','lesson_basic','K2-1-u3-C11',3,'error','auto','친구들이 관찰할 점을 말했어요. 관찰할 점이 아닌 것을 말한 친구는 누구인가요?',ARRAY['K2-1-u3-X17','K2-1-u3-X19']::text[],true,'{"seq":10,"concept":"K2-1-u3-C11","difficulty":3,"kind":"error","stem":"친구들이 관찰할 점을 말했어요. 관찰할 점이 아닌 것을 말한 친구는 누구인가요?","options":[{"t":"지우 — 「화분 값이 얼마인지 볼래.」","correct":true,"mis_target":"K2-1-u3-X17"},{"t":"태민 — 「잎을 만져서 촉감을 알아볼래.」","mis":"K2-1-u3-X19"},{"t":"하린 — 「꽃에 코를 대 보고 냄새를 맡을래.」","mis":"K2-1-u3-X19"}],"explanation":["화분 값은 관찰해서 알 수 없어요.","촉감과 냄새는 손과 코로 관찰해요.","태민이와 하린이는 바르게 말했어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구들이 관찰할 점을 말했어요. 관찰할 점이 아닌 것을 말한 친구는 누구인가요?","options":[{"t":"예린 — 「이 씨앗을 판 사람 이름을 쓸래.」","correct":true,"mis_target":"K2-1-u3-X17"},{"t":"아린 — 「뿌리가 몇 개인지 세어 볼래.」","mis":"K2-1-u3-X19"},{"t":"도윤 — 「줄기 색을 살펴볼래.」","mis":"K2-1-u3-X19"}],"explanation":["판 사람 이름은 관찰해서 알 수 없어요.","뿌리 수와 줄기 색은 눈으로 살펴요.","아린이와 도윤이는 바르게 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L12_challenge#1','kor',2,1,'u3','L12','g2_1_kor_u3_L12_challenge','lesson_challenge','K2-1-u3-C11',2,'mc','auto','「동그란 방울토마토가 조롱조롱 열렸다.」는 무엇을 살펴보고 쓴 문장인가요?',ARRAY['K2-1-u3-X17']::text[],false,'{"seq":1,"concept":"K2-1-u3-C11","difficulty":2,"kind":"mc","stem":"「동그란 방울토마토가 조롱조롱 열렸다.」는 무엇을 살펴보고 쓴 문장인가요?","options":[{"t":"방울토마토의 모양과 열린 모습","correct":true},{"t":"방울토마토의 맛","mis":"K2-1-u3-X17"},{"t":"방울토마토를 산 곳","mis":"K2-1-u3-X17"}],"explanation":["「동그란」은 모양, 「조롱조롱」은 열린 모습이에요.","맛이나 산 곳은 이 문장에 없어요.","눈으로 관찰한 모습을 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L12_challenge#2','kor',2,1,'u3','L12','g2_1_kor_u3_L12_challenge','lesson_challenge','K2-1-u3-C11',2,'mc','auto','글을 읽고 답해 보세요. 이 글이 요리 일기인 까닭은 무엇인가요?',ARRAY['K2-1-u3-X17']::text[],false,'{"seq":2,"concept":"K2-1-u3-C11","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 이 글이 요리 일기인 까닭은 무엇인가요?","options":[{"t":"주먹밥을 만든 차례를 썼기 때문이에요","correct":true},{"t":"식물이 자라는 모습을 살폈기 때문이에요","mis":"K2-1-u3-X17"},{"t":"그림을 함께 그렸기 때문이에요","mis":"K2-1-u3-X17"}],"explanation":["손 씻기 → 섞기 → 뭉치기, 만든 차례가 있어요.","식물을 살핀 것은 관찰 일기예요.","그림과 글은 그림 일기예요."],"asset":{"type":"passage","lines":["제목: 내가 만든 주먹밥","먼저 손을 깨끗이 씻었다.","따뜻한 밥에 김 가루와 깨를 솔솔 뿌려 섞었다.","손에 물을 묻히고 밥을 동글동글 뭉쳤다.","내가 만든 주먹밥을 가족이 맛있게 먹어서 뿌듯했다."],"title":"요리 일기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L12_challenge#3','kor',2,1,'u3','L12','g2_1_kor_u3_L12_challenge','lesson_challenge','K2-1-u3-C11',3,'mc','auto','글을 읽고 답해 보세요. 관찰 일기에서 눈으로 살펴본 것만 모은 것은 어느 것인가요?',ARRAY['K2-1-u3-X17']::text[],false,'{"seq":3,"concept":"K2-1-u3-C11","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 관찰 일기에서 눈으로 살펴본 것만 모은 것은 어느 것인가요?","options":[{"t":"하얀 뿌리 · 연두색 떡잎 · 동그랗게 벌어짐","correct":true},{"t":"풀 냄새 · 하얀 뿌리","mis":"K2-1-u3-X17"},{"t":"궁금함 · 떡잎","mis":"K2-1-u3-X17"}],"explanation":["색과 모양은 눈으로 살펴본 거예요.","풀 냄새는 코로 맡은 거예요.","「궁금하다」는 느낌이에요."],"asset":{"type":"passage","lines":["제목: 콩이 싹텄어요","물에 적신 솜 위에 콩을 올려 두었다.","사흘 만에 하얀 뿌리가 쏙 나왔다.","오늘은 연두색 떡잎 두 장이 동그랗게 벌어졌다.","코를 대 보니 풀 냄새가 살짝 났다.","내일은 얼마나 자랄지 무척 궁금하다."],"title":"관찰 일기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L12_challenge#4','kor',2,1,'u3','L12','g2_1_kor_u3_L12_challenge','lesson_challenge','K2-1-u3-C11',3,'error','auto','친구들이 일기 종류와 쓸 내용을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K2-1-u3-X17','K2-1-u3-X19']::text[],false,'{"seq":4,"concept":"K2-1-u3-C11","difficulty":3,"kind":"error","stem":"친구들이 일기 종류와 쓸 내용을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"소율 — 「요리 일기에는 강낭콩이 자란 모습을 날마다 써.」","correct":true,"mis_target":"K2-1-u3-X17"},{"t":"하준 — 「관찰 일기에는 자세히 살핀 모습을 써.」","mis":"K2-1-u3-X19"},{"t":"서아 — 「그림 일기에는 그림과 글을 함께 써.」","mis":"K2-1-u3-X19"}],"explanation":["식물이 자란 모습은 관찰 일기에 써요.","요리 일기에는 음식을 만든 차례를 써요.","하준이와 서아는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L12_challenge#5','kor',2,1,'u3','L12','g2_1_kor_u3_L12_challenge','lesson_challenge','K2-1-u3-C11',3,'ox','auto','글을 읽고 답해 보세요. 요리 일기에서 「밥을 동글동글 뭉쳤다」를 「손을 깨끗이 씻었다」보다 먼저 쓰면 차례가 더 잘 드러나요.',ARRAY['K2-1-u3-X07']::text[],false,'{"seq":5,"concept":"K2-1-u3-C11","difficulty":3,"kind":"ox","stem":"글을 읽고 답해 보세요. 요리 일기에서 「밥을 동글동글 뭉쳤다」를 「손을 깨끗이 씻었다」보다 먼저 쓰면 차례가 더 잘 드러나요.","answer":"X","reason_options":[{"t":"손을 먼저 씻고 밥을 뭉쳤으니 한 차례대로 써야 하니까","correct":true},{"t":"요리 일기는 차례가 상관없으니까","mis":"K2-1-u3-X07"}],"mis":"K2-1-u3-X07","explanation":["요리 일기는 만든 차례대로 써요.","순서를 바꾸면 읽는 사람이 따라 하기 어려워요.","손 씻기가 맨 처음이에요."],"asset":{"type":"passage","lines":["제목: 내가 만든 주먹밥","먼저 손을 깨끗이 씻었다.","따뜻한 밥에 김 가루와 깨를 솔솔 뿌려 섞었다.","손에 물을 묻히고 밥을 동글동글 뭉쳤다.","내가 만든 주먹밥을 가족이 맛있게 먹어서 뿌듯했다."],"title":"요리 일기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L12_challenge#6','kor',2,1,'u3','L12','g2_1_kor_u3_L12_challenge','lesson_challenge','K2-1-u3-C4',3,'mc','auto','보들보들한 강아지풀을 손으로 만져 본 느낌에 가장 어울리는 문장은 어느 것인가요?',ARRAY['K2-1-u3-X04']::text[],false,'{"seq":6,"concept":"K2-1-u3-C4","difficulty":3,"kind":"mc","stem":"보들보들한 강아지풀을 손으로 만져 본 느낌에 가장 어울리는 문장은 어느 것인가요?","options":[{"t":"「복슬복슬한 이삭이 손바닥을 간질간질 간질였다.」","correct":true},{"t":"「딱딱한 이삭이 손바닥을 찔렀다.」","mis":"K2-1-u3-X04"},{"t":"「시끄러운 이삭이 손을 간질였다.」","mis":"K2-1-u3-X04"}],"explanation":["「복슬복슬한」·「간질간질」이 부드러운 촉감을 살려요.","강아지풀은 딱딱하지 않아요.","이삭은 소리를 내지 않아요."],"asset":{"type":"scene","icon":"🌾✋"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L12_challenge#7','kor',2,1,'u3','L12','g2_1_kor_u3_L12_challenge','lesson_challenge','K2-1-u3-C11',3,'mc','auto','관찰 일기를 쓸 때 알맞지 않은 것은 어느 것인가요?',ARRAY['K2-1-u3-X19']::text[],false,'{"seq":7,"concept":"K2-1-u3-C11","difficulty":3,"kind":"mc","stem":"관찰 일기를 쓸 때 알맞지 않은 것은 어느 것인가요?","options":[{"t":"관찰하지 않은 모습을 지어내어 써요","correct":true},{"t":"날마다 달라진 점을 비교해 써요","mis":"K2-1-u3-X19"},{"t":"색·모양·냄새를 꾸며 주는 말로 써요","mis":"K2-1-u3-X19"}],"explanation":["관찰 일기는 직접 살펴본 것을 써요.","달라진 점을 비교하면 자라는 모습이 드러나요.","「알맞지 않은」을 묻는 물음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L12_challenge#8','kor',2,1,'u3','L12','g2_1_kor_u3_L12_challenge','lesson_challenge','K2-1-u3-C11',4,'mc','auto','두 친구가 같은 화분의 상추를 관찰하고 썼어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L12_challenge#9','kor',2,1,'u3','L12','g2_1_kor_u3_L12_challenge','lesson_challenge','K2-1-u3-C11',4,'essay','teacher','교실이나 집에 있는 식물·물건 하나를 골라 관찰 일기를 써 보세요. 제목, 관찰한 모습 두 가지(색·모양·냄새·촉감 가운데), 생각이나 느낌을 넣어요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u3-C11","difficulty":4,"kind":"essay","stem":"교실이나 집에 있는 식물·물건 하나를 골라 관찰 일기를 써 보세요. 제목, 관찰한 모습 두 가지(색·모양·냄새·촉감 가운데), 생각이나 느낌을 넣어요.","answer_guide":{"answer":"예: 제목: 반짝이는 어항 / 어항 속 금붕어는 주황색 비늘이 반짝반짝 빛났다. 꼬리를 살랑살랑 흔들며 헤엄쳤다. 금붕어가 내 손가락을 따라올 때 무척 신기했다.","scoring_points":["제목을 썼는가","관찰한 모습을 두 가지 감각(색·모양·냄새·촉감)으로 꾸며 주는 말을 넣어 썼는가","생각이나 느낌을 썼는가"]},"explanation":["제목.","두 가지 감각 + 꾸며 주는 말.","느낌."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_L12_challenge#10','kor',2,1,'u3','L12','g2_1_kor_u3_L12_challenge','lesson_challenge','K2-1-u3-C11',4,'essay','teacher','좋아하는 간단한 음식(예: 샌드위치·과일 꼬치)을 만든 요리 일기를 써 보세요. 만든 차례를 세 단계 이상 쓰고, 만들고 난 느낌을 써요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u3-C11","difficulty":4,"kind":"essay","stem":"좋아하는 간단한 음식(예: 샌드위치·과일 꼬치)을 만든 요리 일기를 써 보세요. 만든 차례를 세 단계 이상 쓰고, 만들고 난 느낌을 써요.","answer_guide":{"answer":"예: 제목: 알록달록 과일 꼬치 / 먼저 손을 씻었다. 딸기와 바나나를 먹기 좋게 잘랐다. 꼬치에 빨강, 노랑 차례로 꽂았다. 알록달록한 꼬치를 보니 먹기 아까울 만큼 예뻐서 뿌듯했다.","scoring_points":["만든 음식이 드러나는 제목을 썼는가","만든 차례를 세 단계 이상 차례대로 썼는가","만들고 난 생각이나 느낌을 썼는가"]},"explanation":["제목.","차례 세 단계.","느낌."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#1','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C1',1,'mc','auto','다음 문장에서 꾸며 주는 말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#2','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C2',1,'mc','auto','「예쁜 꽃이 활짝 피었다.」에서 「활짝」이 꾸며 주는 말은 어느 것인가요?',ARRAY['K2-1-u3-X02']::text[],false,'{"seq":2,"concept":"K2-1-u3-C2","difficulty":1,"kind":"mc","stem":"「예쁜 꽃이 활짝 피었다.」에서 「활짝」이 꾸며 주는 말은 어느 것인가요?","options":[{"t":"피었다","correct":true},{"t":"예쁜","mis":"K2-1-u3-X02"},{"t":"꽃이","mis":"K2-1-u3-X02"}],"explanation":["「활짝」은 어떻게 피었는지 알려 줘요.","꾸며 주는 말을 뒤의 말에 붙여 읽어 보면 짝이 보여요.","「활짝 피었다」처럼 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#3','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C4',1,'mc','auto','사과 그림을 보고 꾸며 주는 말을 넣으려고 해요. 가장 어울리는 말은 어느 것인가요?',ARRAY['K2-1-u3-X04']::text[],false,'{"seq":3,"concept":"K2-1-u3-C4","difficulty":1,"kind":"mc","stem":"사과 그림을 보고 꾸며 주는 말을 넣으려고 해요. 가장 어울리는 말은 어느 것인가요?","options":[{"t":"붉은","correct":true},{"t":"시끄러운","mis":"K2-1-u3-X04"},{"t":"졸린","mis":"K2-1-u3-X04"}],"explanation":["사과의 색에는 「붉은」이 어울려요.","다른 말은 사과의 모습과 어울리지 않아요.","대상을 잘 살펴 색·모양·움직임에 맞는 말을 골라요."],"asset":{"type":"scene","icon":"🍎"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#4','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C7',1,'mc','auto','일기는 어떤 글인가요?',ARRAY['K2-1-u3-X09']::text[],false,'{"seq":4,"concept":"K2-1-u3-C7","difficulty":1,"kind":"mc","stem":"일기는 어떤 글인가요?","options":[{"t":"그날 겪은 일 가운데 기억하고 싶은 일과 생각이나 느낌을 쓴 글","correct":true},{"t":"하루에 한 일을 모두 적는 글","mis":"K2-1-u3-X09"},{"t":"내일 할 일을 적는 글","mis":"K2-1-u3-X09"}],"explanation":["일기는 기억하고 싶은 일을 골라 써요.","다른 것은 일기에 맞지 않아요.","일기는 겪은 일과 생각이나 느낌을 담는 글이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#5','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C8',1,'mc','auto','하루에 겪은 일로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X12']::text[],false,'{"seq":5,"concept":"K2-1-u3-C8","difficulty":1,"kind":"mc","stem":"하루에 겪은 일로 알맞은 것은 어느 것인가요?","options":[{"t":"운동장에서 줄넘기를 했다","correct":true},{"t":"줄넘기","mis":"K2-1-u3-X12"},{"t":"기쁨","mis":"K2-1-u3-X12"}],"explanation":["「운동장에서 줄넘기를 했다」는 내가 겪은 일이에요.","줄넘기는 물건, 기쁨은 느낌을 나타내는 낱말이에요.","「~했다·봤다·들었다」로 말이 되는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#6','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C9',1,'mc','auto','「처음 줄넘기를 성공한」 일을 쓴 일기의 제목으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X14']::text[],false,'{"seq":6,"concept":"K2-1-u3-C9","difficulty":1,"kind":"mc","stem":"「처음 줄넘기를 성공한」 일을 쓴 일기의 제목으로 알맞은 것은 어느 것인가요?","options":[{"t":"줄넘기를 처음 성공한 날","correct":true},{"t":"오늘 날씨","mis":"K2-1-u3-X14"},{"t":"그냥 하루","mis":"K2-1-u3-X14"}],"explanation":["「줄넘기를 처음 성공한 날」만 보아도 무슨 일인지 알 수 있어요.","「오늘 날씨」, 「그냥 하루」로는 내용을 알 수 없어요.","제목은 내용을 한눈에 보여 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#7','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C12',1,'mc','auto','바람개비가 돌아가는 모양을 흉내 낸 말은 어느 것인가요?',ARRAY['K2-1-u3-X18']::text[],false,'{"seq":7,"concept":"K2-1-u3-C12","difficulty":1,"kind":"mc","stem":"바람개비가 돌아가는 모양을 흉내 낸 말은 어느 것인가요?","options":[{"t":"빙글빙글","correct":true},{"t":"바람개비","mis":"K2-1-u3-X18"},{"t":"돌아간다","mis":"K2-1-u3-X18"}],"explanation":["「빙글빙글」은 둥글게 도는 모양을 흉내 낸 말이에요.","바람개비·돌아간다는 흉내 내는 말이 아니에요.","따라 했을 때 모습·소리·느낌이 떠오르면 흉내 내는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#8','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C11',1,'mc','auto','식물이나 물건을 자세히 살펴보고 쓰는 일기는 어느 것인가요?',ARRAY['K2-1-u3-X17']::text[],false,'{"seq":8,"concept":"K2-1-u3-C11","difficulty":1,"kind":"mc","stem":"식물이나 물건을 자세히 살펴보고 쓰는 일기는 어느 것인가요?","options":[{"t":"관찰 일기","correct":true},{"t":"요리 일기","mis":"K2-1-u3-X17"},{"t":"그림 일기","mis":"K2-1-u3-X17"}],"explanation":["자세히 살핀 모습을 쓰는 일기는 관찰 일기예요.","다른 일기는 쓰는 내용이 달라요.","관찰 일기·요리 일기·그림 일기의 쓰는 내용을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#9','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C3',2,'ox','auto','「비가 내린다.」보다 「비가 주룩주룩 세차게 내린다.」가 더 생생하게 느껴져요.',ARRAY['K2-1-u3-X03']::text[],false,'{"seq":9,"concept":"K2-1-u3-C3","difficulty":2,"kind":"ox","stem":"「비가 내린다.」보다 「비가 주룩주룩 세차게 내린다.」가 더 생생하게 느껴져요.","answer":"O","reason_options":[{"t":"꾸며 주는 말이 모습을 그려 주니까","correct":true},{"t":"글자가 많을수록 좋은 문장이니까","mis":"K2-1-u3-X03"}],"mis":"K2-1-u3-X03","explanation":["「주룩주룩」·「세차게」가 비 내리는 모습을 보여 줘요.","길어서가 아니라 모습이 떠올라서 생생한 거예요.","꾸며 주는 말은 문장을 자세하게 해 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#10','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C5',2,'mc','auto','꾸며 주는 말을 넣어 문장을 바르게 쓴 것은 어느 것인가요?',ARRAY['K2-1-u3-X06','K2-1-u3-X05']::text[],false,'{"seq":10,"concept":"K2-1-u3-C5","difficulty":2,"kind":"mc","stem":"꾸며 주는 말을 넣어 문장을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"노란 우산을 쓰고 천천히 걷는다.","correct":true},{"t":"노란 우산.","mis":"K2-1-u3-X06"},{"t":"노란 우산을 맛있게 시끄럽게 쓴다.","mis":"K2-1-u3-X05"}],"explanation":["「노란 우산을 쓰고 천천히 걷는다.」는 어울리는 꾸며 주는 말을 넣어 끝까지 쓴 문장이에요.","「노란 우산.」은 끝맺지 않았어요.","「노란 우산을 맛있게 시끄럽게 쓴다.」는 어울리지 않는 말이 들어갔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#11','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C6',2,'mc','auto','글을 읽고 답해 보세요. 여름이 되자 일어난 일은 무엇인가요?',ARRAY['K2-1-u3-X07']::text[],false,'{"seq":11,"concept":"K2-1-u3-C6","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 여름이 되자 일어난 일은 무엇인가요?","options":[{"t":"커다란 해바라기가 활짝 피었어요","correct":true},{"t":"새싹이 쏙 돋아났어요","mis":"K2-1-u3-X07"},{"t":"씨앗이 흙 속에서 잠을 잤어요","mis":"K2-1-u3-X07"}],"explanation":["「여름이 되자 커다란 해바라기가 활짝 피었어요.」라고 했어요.","다른 것은 글에 없거나 차례가 달라요.","글에서 찾아 손가락으로 짚어 봐요."],"asset":{"type":"passage","lines":["작은 씨앗이 흙 속에서 잠을 자요.","봄비가 내리자 조그만 새싹이 쏙 돋아났어요.","줄기는 하루하루 무럭무럭 자랐어요.","여름이 되자 커다란 해바라기가 활짝 피었어요.","가을에는 꽃 가운데에 까만 씨앗이 촘촘히 박혔어요."],"title":"해바라기가 자라요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#12','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C7',2,'mc','auto','일기를 쓰는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X10']::text[],false,'{"seq":12,"concept":"K2-1-u3-C7","difficulty":2,"kind":"mc","stem":"일기를 쓰는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"날짜·날씨 → 제목 → 겪은 일 → 생각이나 느낌","correct":true},{"t":"제목 → 겪은 일 → 생각이나 느낌 → 날짜·날씨","mis":"K2-1-u3-X10"},{"t":"생각이나 느낌 → 겪은 일 → 날짜·날씨 → 제목","mis":"K2-1-u3-X10"}],"explanation":["날짜·날씨가 맨 처음, 그다음 제목을 써요.","이어서 겪은 일, 마지막에 생각이나 느낌을 써요.","차례를 지키면 읽기 쉬워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#13','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C10',2,'mc','auto','「처음 줄넘기 성공」을 겪은 뒤 쓴 문장 가운데 생각이나 느낌이 드러난 것은 어느 것인가요?',ARRAY['K2-1-u3-X15','K2-1-u3-X16']::text[],false,'{"seq":13,"concept":"K2-1-u3-C10","difficulty":2,"kind":"mc","stem":"「처음 줄넘기 성공」을 겪은 뒤 쓴 문장 가운데 생각이나 느낌이 드러난 것은 어느 것인가요?","options":[{"t":"처음으로 줄넘기를 넘어서 정말 뿌듯했다.","correct":true},{"t":"줄넘기를 했다.","mis":"K2-1-u3-X15"},{"t":"했다.","mis":"K2-1-u3-X16"}],"explanation":["「처음으로 줄넘기를 넘어서 정말 뿌듯했다」에 그때의 마음이 담겨 있어요.","다른 문장은 한 일만 쓰거나 무슨 일인지 드러나지 않아요.","겪은 일에 솔직한 느낌을 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#14','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C12',2,'match','auto','흉내 내는 말과 어울리는 모습을 이어 보세요.','{}'::text[],false,'{"seq":14,"concept":"K2-1-u3-C12","difficulty":2,"kind":"match","stem":"흉내 내는 말과 어울리는 모습을 이어 보세요.","pairs":[{"l":"빙글빙글","r":"바람개비가 돈다"},{"l":"톡톡","r":"감꽃이 떨어진다"},{"l":"반짝반짝","r":"별이 빛난다"}],"mis":"K2-1-u3-X18","explanation":["「빙글빙글」은 「바람개비가 돈다」에 어울려요.","「톡톡」은 「감꽃이 떨어진다」에 어울려요.","「반짝반짝」은 「별이 빛난다」에 어울려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#15','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C11',2,'mc','auto','상추를 관찰할 때 살펴볼 점으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X17']::text[],false,'{"seq":15,"concept":"K2-1-u3-C11","difficulty":2,"kind":"mc","stem":"상추를 관찰할 때 살펴볼 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"잎의 색과 모양","correct":true},{"t":"상추의 값","mis":"K2-1-u3-X17"},{"t":"상추를 판 가게","mis":"K2-1-u3-X17"}],"explanation":["색과 모양은 눈으로 살펴 알 수 있어요.","상추의 값·상추를 판 가게는 관찰해서 알 수 없어요.","눈·코·손으로 알 수 있는 것을 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#16','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C8',2,'mc','auto','하준이의 하루예요. 일기 글감으로 가장 알맞은 일은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#17','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C2',3,'error','auto','「귀여운 동생이 새 신발을 신고 깡충깡충 뛰었다.」에서 꾸며 주는 말과 꾸밈을 받는 말을 이었어요. 잘못 이은 친구는 누구인가요?',ARRAY['K2-1-u3-X02','K2-1-u3-X19']::text[],false,'{"seq":17,"concept":"K2-1-u3-C2","difficulty":3,"kind":"error","stem":"「귀여운 동생이 새 신발을 신고 깡충깡충 뛰었다.」에서 꾸며 주는 말과 꾸밈을 받는 말을 이었어요. 잘못 이은 친구는 누구인가요?","options":[{"t":"시우 — 「귀여운 → 신발」","correct":true,"mis_target":"K2-1-u3-X02"},{"t":"다은 — 「새 → 신발」","mis":"K2-1-u3-X19"},{"t":"로아 — 「깡충깡충 → 뛰었다」","mis":"K2-1-u3-X19"}],"explanation":["「귀여운」은 동생을 꾸며요.","다른 두 친구는 바르게 이었어요.","꾸며 주는 말을 바로 뒤의 말에 붙여 읽어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#18','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C7',3,'mc','auto','글을 읽고 답해 보세요. 이 일기에서 빠진 것은 어느 것인가요?',ARRAY['K2-1-u3-X09']::text[],false,'{"seq":18,"concept":"K2-1-u3-C7","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 이 일기에서 빠진 것은 어느 것인가요?","options":[{"t":"날짜·요일·날씨","correct":true},{"t":"생각이나 느낌","mis":"K2-1-u3-X09"},{"t":"제목","mis":"K2-1-u3-X09"}],"explanation":["하람이는 맨 처음에 쓸 날짜·요일·날씨를 빠뜨렸어요.","다른 두 가지는 일기에 들어 있어요.","「빠진 것」을 묻는 물음 — 네 손가락을 접으며 확인해요."],"asset":{"type":"passage","lines":["제목: 처음 끓인 라면","저녁에 아빠와 부엌에서 라면을 끓였다.","보글보글 끓는 물에 면을 넣고 젓가락으로 살살 저었다.","내가 끓인 라면이라 더 맛있게 느껴졌다."],"title":"하람이의 일기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#19','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C4',3,'mc','auto','바닷가 모습을 쓴 문장 가운데 어울리지 않는 꾸며 주는 말이 들어간 것은 어느 것인가요?',ARRAY['K2-1-u3-X19']::text[],false,'{"seq":19,"concept":"K2-1-u3-C4","difficulty":3,"kind":"mc","stem":"바닷가 모습을 쓴 문장 가운데 어울리지 않는 꾸며 주는 말이 들어간 것은 어느 것인가요?","options":[{"t":"「달콤한 파도가 철썩 친다.」","correct":true},{"t":"「하얀 갈매기가 높이 난다.」","mis":"K2-1-u3-X19"},{"t":"「뜨거운 모래가 반짝인다.」","mis":"K2-1-u3-X19"}],"explanation":["파도는 맛이 없어 「달콤한」이 어울리지 않아요.","다른 두 문장은 모습에 어울리는 말을 넣었어요.","「어울리지 않는」을 묻는 물음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#20','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C9',3,'error','auto','「처음으로 바다에서 수영한 날」이 글감이에요. 제목을 알맞지 않게 지은 친구는 누구인가요?',ARRAY['K2-1-u3-X14','K2-1-u3-X19']::text[],false,'{"seq":20,"concept":"K2-1-u3-C9","difficulty":3,"kind":"error","stem":"「처음으로 바다에서 수영한 날」이 글감이에요. 제목을 알맞지 않게 지은 친구는 누구인가요?","options":[{"t":"민지 — 「여름」","correct":true,"mis_target":"K2-1-u3-X14"},{"t":"아린 — 「바다에서 처음 수영한 날」","mis":"K2-1-u3-X19"},{"t":"지호 — 「파도와 첫 수영」","mis":"K2-1-u3-X19"}],"explanation":["「여름」만으로는 무슨 일인지 알 수 없어요.","제목에 겪은 일이 드러나야 내용을 알 수 있어요.","다른 두 친구는 내용이 드러나게 지었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#21','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C6',3,'mc','auto','글을 읽고 답해 보세요. 「무럭무럭」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X08']::text[],false,'{"seq":21,"concept":"K2-1-u3-C6","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 「무럭무럭」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"힘차게 잘 자라는 모양","correct":true},{"t":"시들시들 마르는 모양","mis":"K2-1-u3-X08"},{"t":"작은 열매가 많이 매달린 모양","mis":"K2-1-u3-X08"}],"explanation":["줄기가 무럭무럭 자랐다는 것은 힘차게 잘 자랐다는 뜻이에요.","다른 뜻은 다른 낱말의 뜻이에요.","낱말을 소리 내어 읽으며 모양을 떠올려요."],"asset":{"type":"passage","lines":["작은 씨앗이 흙 속에서 잠을 자요.","봄비가 내리자 조그만 새싹이 쏙 돋아났어요.","줄기는 하루하루 무럭무럭 자랐어요.","여름이 되자 커다란 해바라기가 활짝 피었어요.","가을에는 꽃 가운데에 까만 씨앗이 촘촘히 박혔어요."],"title":"해바라기가 자라요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#22','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C12',3,'mc','auto','흉내 내는 말 가운데 모양을 흉내 낸 말이 아닌 것은 어느 것인가요?',ARRAY['K2-1-u3-X19']::text[],false,'{"seq":22,"concept":"K2-1-u3-C12","difficulty":3,"kind":"mc","stem":"흉내 내는 말 가운데 모양을 흉내 낸 말이 아닌 것은 어느 것인가요?","options":[{"t":"졸졸","correct":true},{"t":"빙글빙글","mis":"K2-1-u3-X19"},{"t":"둥실둥실","mis":"K2-1-u3-X19"}],"explanation":["「졸졸」은 물이 흐르는 소리를 흉내 낸 말이에요.","다른 두 말은 모양을 흉내 낸 말이에요.","「아닌 것」을 묻는 물음 — 따라 하며 무엇이 떠오르는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#23','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C10',4,'mc','auto','두 친구가 같은 날 「운동회」 일기를 썼어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#24','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C5',4,'essay','teacher','「고양이가 걷는다.」에 꾸며 주는 말을 두 개 넣어 더 생생한 문장으로 고쳐 쓰고, 넣은 꾸며 주는 말을 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u3-C5","difficulty":4,"kind":"essay","stem":"「고양이가 걷는다.」에 꾸며 주는 말을 두 개 넣어 더 생생한 문장으로 고쳐 쓰고, 넣은 꾸며 주는 말을 써 보세요.","answer_guide":{"answer":"예: 하얀 고양이가 살금살금 걷는다. (하얀, 살금살금)","scoring_points":["꾸며 주는 말을 두 개 넣었는가","넣은 말이 대상과 모습에 어울리는가","문장을 끝까지 쓰고 마침표를 찍었는가"]},"explanation":["꾸며 주는 말 두 개.","어울림.","끝까지 쓴 문장."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_a#25','kor',2,1,'u3','','g2_1_kor_u3_review_a','unit_review','K2-1-u3-C10',4,'essay','teacher','다음 일기를 언제·어디서·누구와, 그리고 그때의 생각이나 느낌이 드러나게 꾸며 주는 말을 넣어 고쳐 써 보세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#1','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C1',1,'mc','auto','다음 문장에서 꾸며 주는 말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#2','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C2',1,'mc','auto','「작은 새가 높이 날았다.」에서 「작은」이 꾸며 주는 말은 어느 것인가요?',ARRAY['K2-1-u3-X02']::text[],false,'{"seq":2,"concept":"K2-1-u3-C2","difficulty":1,"kind":"mc","stem":"「작은 새가 높이 날았다.」에서 「작은」이 꾸며 주는 말은 어느 것인가요?","options":[{"t":"새가","correct":true},{"t":"높이","mis":"K2-1-u3-X02"},{"t":"날았다","mis":"K2-1-u3-X02"}],"explanation":["「작은」은 새가 어떤지 알려 줘요.","꾸며 주는 말을 뒤의 말에 붙여 읽어 보면 짝이 보여요.","「작은 새가」처럼 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#3','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C4',1,'mc','auto','수박 그림을 보고 꾸며 주는 말을 넣으려고 해요. 가장 어울리는 말은 어느 것인가요?',ARRAY['K2-1-u3-X04']::text[],false,'{"seq":3,"concept":"K2-1-u3-C4","difficulty":1,"kind":"mc","stem":"수박 그림을 보고 꾸며 주는 말을 넣으려고 해요. 가장 어울리는 말은 어느 것인가요?","options":[{"t":"커다란","correct":true},{"t":"네모난","mis":"K2-1-u3-X04"},{"t":"파란","mis":"K2-1-u3-X04"}],"explanation":["수박의 크기에는 「커다란」이 어울려요.","다른 말은 수박의 모습과 어울리지 않아요.","대상을 잘 살펴 색·모양·움직임에 맞는 말을 골라요."],"asset":{"type":"scene","icon":"🍉"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#4','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C7',1,'mc','auto','일기에 꼭 들어가는 것은 어느 것인가요?',ARRAY['K2-1-u3-X11']::text[],false,'{"seq":4,"concept":"K2-1-u3-C7","difficulty":1,"kind":"mc","stem":"일기에 꼭 들어가는 것은 어느 것인가요?","options":[{"t":"생각이나 느낌","correct":true},{"t":"친구 전화번호","mis":"K2-1-u3-X11"},{"t":"내일 시간표","mis":"K2-1-u3-X11"}],"explanation":["일기에는 겪은 일에 대한 생각이나 느낌을 써요.","다른 것은 일기에 맞지 않아요.","일기는 겪은 일과 생각이나 느낌을 담는 글이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#5','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C8',1,'mc','auto','하루에 겪은 일로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X12']::text[],false,'{"seq":5,"concept":"K2-1-u3-C8","difficulty":1,"kind":"mc","stem":"하루에 겪은 일로 알맞은 것은 어느 것인가요?","options":[{"t":"공원에서 무지개를 봤다","correct":true},{"t":"우산","mis":"K2-1-u3-X12"},{"t":"놀라움","mis":"K2-1-u3-X12"}],"explanation":["「공원에서 무지개를 봤다」는 내가 겪은 일이에요.","우산은 물건, 놀라움은 느낌을 나타내는 낱말이에요.","「~했다·봤다·들었다」로 말이 되는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#6','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C9',1,'mc','auto','「동생과 눈사람을 만든」 일을 쓴 일기의 제목으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X14']::text[],false,'{"seq":6,"concept":"K2-1-u3-C9","difficulty":1,"kind":"mc","stem":"「동생과 눈사람을 만든」 일을 쓴 일기의 제목으로 알맞은 것은 어느 것인가요?","options":[{"t":"동생과 만든 눈사람","correct":true},{"t":"일기","mis":"K2-1-u3-X14"},{"t":"겨울","mis":"K2-1-u3-X14"}],"explanation":["「동생과 만든 눈사람」만 보아도 무슨 일인지 알 수 있어요.","「일기」, 「겨울」로는 내용을 알 수 없어요.","제목은 내용을 한눈에 보여 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#7','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C12',1,'mc','auto','감꽃이 떨어지는 소리를 흉내 낸 말은 어느 것인가요?',ARRAY['K2-1-u3-X18']::text[],false,'{"seq":7,"concept":"K2-1-u3-C12","difficulty":1,"kind":"mc","stem":"감꽃이 떨어지는 소리를 흉내 낸 말은 어느 것인가요?","options":[{"t":"톡톡","correct":true},{"t":"감꽃","mis":"K2-1-u3-X18"},{"t":"떨어진다","mis":"K2-1-u3-X18"}],"explanation":["「톡톡」은 가볍게 떨어지는 소리를 흉내 낸 말이에요.","감꽃·떨어진다는 흉내 내는 말이 아니에요.","따라 했을 때 모습·소리·느낌이 떠오르면 흉내 내는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#8','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C11',1,'mc','auto','음식을 만든 차례를 쓰는 일기는 어느 것인가요?',ARRAY['K2-1-u3-X17']::text[],false,'{"seq":8,"concept":"K2-1-u3-C11","difficulty":1,"kind":"mc","stem":"음식을 만든 차례를 쓰는 일기는 어느 것인가요?","options":[{"t":"요리 일기","correct":true},{"t":"관찰 일기","mis":"K2-1-u3-X17"},{"t":"그림 일기","mis":"K2-1-u3-X17"}],"explanation":["음식을 만든 차례는 요리 일기에 써요.","다른 일기는 쓰는 내용이 달라요.","관찰 일기·요리 일기·그림 일기의 쓰는 내용을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#9','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C3',2,'ox','auto','「옥수수밭에 갔다.」보다 「넓은 옥수수밭에 갔다.」가 더 생생하게 느껴져요.',ARRAY['K2-1-u3-X03']::text[],false,'{"seq":9,"concept":"K2-1-u3-C3","difficulty":2,"kind":"ox","stem":"「옥수수밭에 갔다.」보다 「넓은 옥수수밭에 갔다.」가 더 생생하게 느껴져요.","answer":"O","reason_options":[{"t":"꾸며 주는 말이 모습을 그려 주니까","correct":true},{"t":"글자가 많을수록 좋은 문장이니까","mis":"K2-1-u3-X03"}],"mis":"K2-1-u3-X03","explanation":["「넓은」이 옥수수밭의 모습을 보여 줘요.","길어서가 아니라 모습이 떠올라서 생생한 거예요.","꾸며 주는 말은 문장을 자세하게 해 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#10','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C5',2,'mc','auto','꾸며 주는 말을 넣어 문장을 바르게 쓴 것은 어느 것인가요?',ARRAY['K2-1-u3-X06','K2-1-u3-X05']::text[],false,'{"seq":10,"concept":"K2-1-u3-C5","difficulty":2,"kind":"mc","stem":"꾸며 주는 말을 넣어 문장을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"작은 새가 하늘을 높이 난다.","correct":true},{"t":"작은 새.","mis":"K2-1-u3-X06"},{"t":"작은 새가 하늘을 짭짤하게 네모나게 난다.","mis":"K2-1-u3-X05"}],"explanation":["「작은 새가 하늘을 높이 난다.」는 어울리는 꾸며 주는 말을 넣어 끝까지 쓴 문장이에요.","「작은 새.」는 끝맺지 않았어요.","「작은 새가 하늘을 짭짤하게 네모나게 난다.」는 어울리지 않는 말이 들어갔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#11','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C6',2,'mc','auto','글을 읽고 답해 보세요. 노란 꽃이 진 자리에 생긴 것은 무엇인가요?',ARRAY['K2-1-u3-X07']::text[],false,'{"seq":11,"concept":"K2-1-u3-C6","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 노란 꽃이 진 자리에 생긴 것은 무엇인가요?","options":[{"t":"초록 열매","correct":true},{"t":"빨간 꽃","mis":"K2-1-u3-X07"},{"t":"새 모종","mis":"K2-1-u3-X07"}],"explanation":["「꽃이 진 자리에 초록 열매가 조롱조롱 매달렸어요.」라고 했어요.","다른 것은 글에 없거나 차례가 달라요.","글에서 찾아 손가락으로 짚어 봐요."],"asset":{"type":"passage","lines":["텃밭에 토마토 모종을 심었어요.","줄기가 쑥쑥 곧게 자라고 노란 꽃이 피었어요.","꽃이 진 자리에 초록 열매가 조롱조롱 매달렸어요.","햇볕을 듬뿍 받은 열매는 빨갛게 익어 갔어요."],"title":"조롱조롱 토마토"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#12','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C7',2,'mc','auto','일기를 쓰는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X10']::text[],false,'{"seq":12,"concept":"K2-1-u3-C7","difficulty":2,"kind":"mc","stem":"일기를 쓰는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"날짜·날씨 → 제목 → 겪은 일 → 생각이나 느낌","correct":true},{"t":"겪은 일 → 날짜·날씨 → 제목 → 생각이나 느낌","mis":"K2-1-u3-X10"},{"t":"제목 → 날짜·날씨 → 생각이나 느낌 → 겪은 일","mis":"K2-1-u3-X10"}],"explanation":["날짜·날씨가 맨 처음, 그다음 제목을 써요.","이어서 겪은 일, 마지막에 생각이나 느낌을 써요.","차례를 지키면 읽기 쉬워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#13','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C10',2,'mc','auto','「동생과 눈사람 만들기」를 겪은 뒤 쓴 문장 가운데 생각이나 느낌이 드러난 것은 어느 것인가요?',ARRAY['K2-1-u3-X15','K2-1-u3-X16']::text[],false,'{"seq":13,"concept":"K2-1-u3-C10","difficulty":2,"kind":"mc","stem":"「동생과 눈사람 만들기」를 겪은 뒤 쓴 문장 가운데 생각이나 느낌이 드러난 것은 어느 것인가요?","options":[{"t":"동생과 만든 눈사람이 웃는 것 같아 마음이 따뜻했다.","correct":true},{"t":"눈사람을 만들었다.","mis":"K2-1-u3-X15"},{"t":"만들었다.","mis":"K2-1-u3-X16"}],"explanation":["「동생과 만든 눈사람이 웃는 것 같아 마음이 따뜻했다」에 그때의 마음이 담겨 있어요.","다른 문장은 한 일만 쓰거나 무슨 일인지 드러나지 않아요.","겪은 일에 솔직한 느낌을 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#14','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C12',2,'match','auto','흉내 내는 말과 어울리는 모습을 이어 보세요.','{}'::text[],false,'{"seq":14,"concept":"K2-1-u3-C12","difficulty":2,"kind":"match","stem":"흉내 내는 말과 어울리는 모습을 이어 보세요.","pairs":[{"l":"졸졸","r":"시냇물이 흐른다"},{"l":"둥실둥실","r":"구름이 떠간다"},{"l":"새근새근","r":"아기가 잔다"}],"mis":"K2-1-u3-X18","explanation":["「졸졸」은 「시냇물이 흐른다」에 어울려요.","「둥실둥실」은 「구름이 떠간다」에 어울려요.","「새근새근」은 「아기가 잔다」에 어울려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#15','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C11',2,'mc','auto','장미꽃을 관찰할 때 살펴볼 점으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X17']::text[],false,'{"seq":15,"concept":"K2-1-u3-C11","difficulty":2,"kind":"mc","stem":"장미꽃을 관찰할 때 살펴볼 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"꽃의 향기","correct":true},{"t":"꽃을 산 날짜","mis":"K2-1-u3-X17"},{"t":"꽃집 이름","mis":"K2-1-u3-X17"}],"explanation":["향기는 코로 맡아 알 수 있어요.","꽃을 산 날짜·꽃집 이름은 관찰해서 알 수 없어요.","눈·코·손으로 알 수 있는 것을 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#16','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C8',2,'mc','auto','서윤이의 하루예요. 일기 글감으로 가장 알맞은 일은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#17','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C2',3,'error','auto','「넓은 옥수수밭에서 할머니가 활짝 웃으셨다.」에서 꾸며 주는 말과 꾸밈을 받는 말을 이었어요. 잘못 이은 친구는 누구인가요?',ARRAY['K2-1-u3-X02','K2-1-u3-X19']::text[],false,'{"seq":17,"concept":"K2-1-u3-C2","difficulty":3,"kind":"error","stem":"「넓은 옥수수밭에서 할머니가 활짝 웃으셨다.」에서 꾸며 주는 말과 꾸밈을 받는 말을 이었어요. 잘못 이은 친구는 누구인가요?","options":[{"t":"준우 — 「넓은 → 웃으셨다」","correct":true,"mis_target":"K2-1-u3-X02"},{"t":"하린 — 「넓은 → 옥수수밭」","mis":"K2-1-u3-X19"},{"t":"지안 — 「활짝 → 웃으셨다」","mis":"K2-1-u3-X19"}],"explanation":["「넓은」은 옥수수밭을 꾸며요.","다른 두 친구는 바르게 이었어요.","꾸며 주는 말을 바로 뒤의 말에 붙여 읽어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#18','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C7',3,'mc','auto','글을 읽고 답해 보세요. 이 일기에서 빠진 것은 어느 것인가요?',ARRAY['K2-1-u3-X09']::text[],false,'{"seq":18,"concept":"K2-1-u3-C7","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 이 일기에서 빠진 것은 어느 것인가요?","options":[{"t":"생각이나 느낌","correct":true},{"t":"날짜·요일·날씨","mis":"K2-1-u3-X09"},{"t":"제목","mis":"K2-1-u3-X09"}],"explanation":["민지는 겪은 일은 자세히 썼지만 그때의 마음을 쓰지 않았어요.","다른 두 가지는 일기에 들어 있어요.","「빠진 것」을 묻는 물음 — 네 손가락을 접으며 확인해요."],"asset":{"type":"passage","lines":["9월 14일 토요일, 선선한 바람이 부는 날","제목: 할아버지와 고구마 캐기","오전에 할아버지 밭에서 고구마를 캤다.","흙을 살살 파내니 커다란 고구마가 줄줄이 딸려 나왔다."],"title":"민지의 일기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#19','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C4',3,'mc','auto','공원 모습을 쓴 문장 가운데 어울리지 않는 꾸며 주는 말이 들어간 것은 어느 것인가요?',ARRAY['K2-1-u3-X19']::text[],false,'{"seq":19,"concept":"K2-1-u3-C4","difficulty":3,"kind":"mc","stem":"공원 모습을 쓴 문장 가운데 어울리지 않는 꾸며 주는 말이 들어간 것은 어느 것인가요?","options":[{"t":"「네모난 비둘기가 걸어간다.」","correct":true},{"t":"「푸른 나무가 우뚝 서 있다.」","mis":"K2-1-u3-X19"},{"t":"「알록달록한 꽃이 활짝 피었다.」","mis":"K2-1-u3-X19"}],"explanation":["비둘기는 네모나지 않아요.","다른 두 문장은 모습에 어울리는 말을 넣었어요.","「어울리지 않는」을 묻는 물음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#20','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C9',3,'error','auto','「동생과 함께 김밥 만들기」가 글감이에요. 제목을 알맞지 않게 지은 친구는 누구인가요?',ARRAY['K2-1-u3-X14','K2-1-u3-X19']::text[],false,'{"seq":20,"concept":"K2-1-u3-C9","difficulty":3,"kind":"error","stem":"「동생과 함께 김밥 만들기」가 글감이에요. 제목을 알맞지 않게 지은 친구는 누구인가요?","options":[{"t":"현우 — 「일요일」","correct":true,"mis_target":"K2-1-u3-X14"},{"t":"도담 — 「동생과 만든 김밥」","mis":"K2-1-u3-X19"},{"t":"하늘 — 「김밥 만들기 대작전」","mis":"K2-1-u3-X19"}],"explanation":["「일요일」만으로는 무슨 일인지 알 수 없어요.","제목에 겪은 일이 드러나야 내용을 알 수 있어요.","다른 두 친구는 내용이 드러나게 지었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#21','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C6',3,'mc','auto','글을 읽고 답해 보세요. 「조롱조롱」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X08']::text[],false,'{"seq":21,"concept":"K2-1-u3-C6","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 「조롱조롱」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"작은 열매가 많이 매달린 모양","correct":true},{"t":"겉면이 높고 낮은 모양","mis":"K2-1-u3-X08"},{"t":"꽃잎이 한껏 핀 모양","mis":"K2-1-u3-X08"}],"explanation":["초록 열매가 조롱조롱 매달렸다는 것은 작은 열매가 많이 달렸다는 뜻이에요.","다른 뜻은 다른 낱말의 뜻이에요.","낱말을 소리 내어 읽으며 모양을 떠올려요."],"asset":{"type":"passage","lines":["텃밭에 토마토 모종을 심었어요.","줄기가 쑥쑥 곧게 자라고 노란 꽃이 피었어요.","꽃이 진 자리에 초록 열매가 조롱조롱 매달렸어요.","햇볕을 듬뿍 받은 열매는 빨갛게 익어 갔어요."],"title":"조롱조롱 토마토"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#22','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C12',3,'mc','auto','흉내 내는 말 가운데 소리를 흉내 낸 말이 아닌 것은 어느 것인가요?',ARRAY['K2-1-u3-X19']::text[],false,'{"seq":22,"concept":"K2-1-u3-C12","difficulty":3,"kind":"mc","stem":"흉내 내는 말 가운데 소리를 흉내 낸 말이 아닌 것은 어느 것인가요?","options":[{"t":"반짝반짝","correct":true},{"t":"톡톡","mis":"K2-1-u3-X19"},{"t":"쨍그랑","mis":"K2-1-u3-X19"}],"explanation":["「반짝반짝」은 빛나는 모양을 흉내 낸 말이에요.","다른 두 말은 소리를 흉내 낸 말이에요.","「아닌 것」을 묻는 물음 — 따라 하며 무엇이 떠오르는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#23','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C10',4,'mc','auto','두 친구가 같은 날 「소풍」 일기를 썼어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#24','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C5',4,'essay','teacher','「바람이 분다.」에 꾸며 주는 말을 두 개 넣어 더 생생한 문장으로 고쳐 쓰고, 넣은 꾸며 주는 말을 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u3-C5","difficulty":4,"kind":"essay","stem":"「바람이 분다.」에 꾸며 주는 말을 두 개 넣어 더 생생한 문장으로 고쳐 쓰고, 넣은 꾸며 주는 말을 써 보세요.","answer_guide":{"answer":"예: 시원한 바람이 살랑살랑 분다. (시원한, 살랑살랑)","scoring_points":["꾸며 주는 말을 두 개 넣었는가","넣은 말이 대상과 모습에 어울리는가","문장을 끝까지 쓰고 마침표를 찍었는가"]},"explanation":["꾸며 주는 말 두 개.","어울림.","끝까지 쓴 문장."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_b#25','kor',2,1,'u3','','g2_1_kor_u3_review_b','unit_review','K2-1-u3-C10',4,'essay','teacher','다음 일기를 언제·어디서·누구와, 그리고 그때의 생각이나 느낌이 드러나게 꾸며 주는 말을 넣어 고쳐 써 보세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#1','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C1',1,'mc','auto','다음 문장에서 꾸며 주는 말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#2','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C2',1,'mc','auto','「예쁜 아기가 새근새근 잔다.」에서 「새근새근」이 꾸며 주는 말은 어느 것인가요?',ARRAY['K2-1-u3-X02']::text[],false,'{"seq":2,"concept":"K2-1-u3-C2","difficulty":1,"kind":"mc","stem":"「예쁜 아기가 새근새근 잔다.」에서 「새근새근」이 꾸며 주는 말은 어느 것인가요?","options":[{"t":"잔다","correct":true},{"t":"아기가","mis":"K2-1-u3-X02"},{"t":"예쁜","mis":"K2-1-u3-X02"}],"explanation":["「새근새근」은 어떻게 자는지 알려 줘요.","꾸며 주는 말을 뒤의 말에 붙여 읽어 보면 짝이 보여요.","「새근새근 잔다」처럼 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#3','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C4',1,'mc','auto','달팽이 그림을 보고 꾸며 주는 말을 넣으려고 해요. 가장 어울리는 말은 어느 것인가요?',ARRAY['K2-1-u3-X04']::text[],false,'{"seq":3,"concept":"K2-1-u3-C4","difficulty":1,"kind":"mc","stem":"달팽이 그림을 보고 꾸며 주는 말을 넣으려고 해요. 가장 어울리는 말은 어느 것인가요?","options":[{"t":"느릿느릿","correct":true},{"t":"쌩쌩","mis":"K2-1-u3-X04"},{"t":"깡충깡충","mis":"K2-1-u3-X04"}],"explanation":["달팽이가 기는 모습에는 「느릿느릿」이 어울려요.","다른 말은 달팽이의 모습과 어울리지 않아요.","대상을 잘 살펴 색·모양·움직임에 맞는 말을 골라요."],"asset":{"type":"scene","icon":"🐌"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#4','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C7',1,'mc','auto','일기에서 맨 처음에 쓰는 것은 어느 것인가요?',ARRAY['K2-1-u3-X10']::text[],false,'{"seq":4,"concept":"K2-1-u3-C7","difficulty":1,"kind":"mc","stem":"일기에서 맨 처음에 쓰는 것은 어느 것인가요?","options":[{"t":"날짜·요일·날씨","correct":true},{"t":"생각이나 느낌","mis":"K2-1-u3-X10"},{"t":"겪은 일","mis":"K2-1-u3-X10"}],"explanation":["일기는 날짜·요일·날씨부터 써요.","다른 것은 일기에 맞지 않아요.","일기는 겪은 일과 생각이나 느낌을 담는 글이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#5','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C8',1,'mc','auto','하루에 겪은 일로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X12']::text[],false,'{"seq":5,"concept":"K2-1-u3-C8","difficulty":1,"kind":"mc","stem":"하루에 겪은 일로 알맞은 것은 어느 것인가요?","options":[{"t":"선생님께 칭찬을 들었다","correct":true},{"t":"칠판","mis":"K2-1-u3-X12"},{"t":"뿌듯함","mis":"K2-1-u3-X12"}],"explanation":["「선생님께 칭찬을 들었다」는 내가 겪은 일이에요.","칠판은 물건, 뿌듯함은 느낌을 나타내는 낱말이에요.","「~했다·봤다·들었다」로 말이 되는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#6','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C9',1,'mc','auto','「할머니와 송편을 빚은」 일을 쓴 일기의 제목으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X14']::text[],false,'{"seq":6,"concept":"K2-1-u3-C9","difficulty":1,"kind":"mc","stem":"「할머니와 송편을 빚은」 일을 쓴 일기의 제목으로 알맞은 것은 어느 것인가요?","options":[{"t":"할머니와 빚은 송편","correct":true},{"t":"토요일","mis":"K2-1-u3-X14"},{"t":"재미","mis":"K2-1-u3-X14"}],"explanation":["「할머니와 빚은 송편」만 보아도 무슨 일인지 알 수 있어요.","「토요일」, 「재미」로는 내용을 알 수 없어요.","제목은 내용을 한눈에 보여 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#7','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C12',1,'mc','auto','별이 빛나는 모양을 흉내 낸 말은 어느 것인가요?',ARRAY['K2-1-u3-X18']::text[],false,'{"seq":7,"concept":"K2-1-u3-C12","difficulty":1,"kind":"mc","stem":"별이 빛나는 모양을 흉내 낸 말은 어느 것인가요?","options":[{"t":"반짝반짝","correct":true},{"t":"별","mis":"K2-1-u3-X18"},{"t":"밤하늘","mis":"K2-1-u3-X18"}],"explanation":["「반짝반짝」은 별이 빛나는 모양을 흉내 낸 말이에요.","별·밤하늘은 흉내 내는 말이 아니에요.","따라 했을 때 모습·소리·느낌이 떠오르면 흉내 내는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#8','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C11',1,'mc','auto','그림과 글로 함께 나타내는 일기는 어느 것인가요?',ARRAY['K2-1-u3-X17']::text[],false,'{"seq":8,"concept":"K2-1-u3-C11","difficulty":1,"kind":"mc","stem":"그림과 글로 함께 나타내는 일기는 어느 것인가요?","options":[{"t":"그림 일기","correct":true},{"t":"요리 일기","mis":"K2-1-u3-X17"},{"t":"관찰 일기","mis":"K2-1-u3-X17"}],"explanation":["그림과 글을 함께 쓰는 일기는 그림 일기예요.","다른 일기는 쓰는 내용이 달라요.","관찰 일기·요리 일기·그림 일기의 쓰는 내용을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#9','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C3',2,'ox','auto','「코끼리가 있다.」보다 「커다란 하얀 코끼리가 있다.」가 더 생생하게 느껴져요.',ARRAY['K2-1-u3-X03']::text[],false,'{"seq":9,"concept":"K2-1-u3-C3","difficulty":2,"kind":"ox","stem":"「코끼리가 있다.」보다 「커다란 하얀 코끼리가 있다.」가 더 생생하게 느껴져요.","answer":"O","reason_options":[{"t":"꾸며 주는 말이 모습을 그려 주니까","correct":true},{"t":"글자가 많을수록 좋은 문장이니까","mis":"K2-1-u3-X03"}],"mis":"K2-1-u3-X03","explanation":["「커다란」·「하얀」이 코끼리의 모습을 보여 줘요.","길어서가 아니라 모습이 떠올라서 생생한 거예요.","꾸며 주는 말은 문장을 자세하게 해 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#10','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C5',2,'mc','auto','꾸며 주는 말을 넣어 문장을 바르게 쓴 것은 어느 것인가요?',ARRAY['K2-1-u3-X06','K2-1-u3-X05']::text[],false,'{"seq":10,"concept":"K2-1-u3-C5","difficulty":2,"kind":"mc","stem":"꾸며 주는 말을 넣어 문장을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"커다란 배가 바다를 빠르게 나아간다.","correct":true},{"t":"커다란 배.","mis":"K2-1-u3-X06"},{"t":"커다란 배가 바다를 졸리게 달콤하게 나아간다.","mis":"K2-1-u3-X05"}],"explanation":["「커다란 배가 바다를 빠르게 나아간다.」는 어울리는 꾸며 주는 말을 넣어 끝까지 쓴 문장이에요.","「커다란 배.」는 끝맺지 않았어요.","「커다란 배가 바다를 졸리게 달콤하게 나아간다.」는 어울리지 않는 말이 들어갔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#11','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C6',2,'mc','auto','글을 읽고 답해 보세요. 덩굴손은 무엇을 감으며 뻗어 가나요?',ARRAY['K2-1-u3-X07']::text[],false,'{"seq":11,"concept":"K2-1-u3-C6","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 덩굴손은 무엇을 감으며 뻗어 가나요?","options":[{"t":"막대","correct":true},{"t":"땅콩","mis":"K2-1-u3-X07"},{"t":"꼬투리","mis":"K2-1-u3-X07"}],"explanation":["「덩굴손은 막대를 빙글빙글 감으며 쭉쭉 뻗어 가요.」라고 했어요.","다른 것은 글에 없거나 차례가 달라요.","글에서 찾아 손가락으로 짚어 봐요."],"asset":{"type":"passage","lines":["완두는 덩굴손이 있는 식물이에요.","덩굴손은 막대를 빙글빙글 감으며 쭉쭉 뻗어 가요.","꼬투리 속에는 동글동글한 완두콩이 나란히 들어 있어요.","땅콩 껍데기는 겉이 올록볼록해서 만지면 울퉁불퉁해요."],"title":"덩굴손과 꼬투리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#12','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C7',2,'mc','auto','일기를 쓰는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X10']::text[],false,'{"seq":12,"concept":"K2-1-u3-C7","difficulty":2,"kind":"mc","stem":"일기를 쓰는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"날짜·날씨 → 제목 → 겪은 일 → 생각이나 느낌","correct":true},{"t":"날짜·날씨 → 생각이나 느낌 → 제목 → 겪은 일","mis":"K2-1-u3-X10"},{"t":"겪은 일 → 생각이나 느낌 → 제목 → 날짜·날씨","mis":"K2-1-u3-X10"}],"explanation":["날짜·날씨가 맨 처음, 그다음 제목을 써요.","이어서 겪은 일, 마지막에 생각이나 느낌을 써요.","차례를 지키면 읽기 쉬워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#13','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C10',2,'mc','auto','「발표하기」를 겪은 뒤 쓴 문장 가운데 생각이나 느낌이 드러난 것은 어느 것인가요?',ARRAY['K2-1-u3-X15','K2-1-u3-X16']::text[],false,'{"seq":13,"concept":"K2-1-u3-C10","difficulty":2,"kind":"mc","stem":"「발표하기」를 겪은 뒤 쓴 문장 가운데 생각이나 느낌이 드러난 것은 어느 것인가요?","options":[{"t":"떨렸지만 끝까지 말해서 스스로가 대견했다.","correct":true},{"t":"발표를 했다.","mis":"K2-1-u3-X15"},{"t":"말했다.","mis":"K2-1-u3-X16"}],"explanation":["「떨렸지만 끝까지 말해서 스스로가 대견했다」에 그때의 마음이 담겨 있어요.","다른 문장은 한 일만 쓰거나 무슨 일인지 드러나지 않아요.","겪은 일에 솔직한 느낌을 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#14','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C12',2,'match','auto','흉내 내는 말과 어울리는 모습을 이어 보세요.','{}'::text[],false,'{"seq":14,"concept":"K2-1-u3-C12","difficulty":2,"kind":"match","stem":"흉내 내는 말과 어울리는 모습을 이어 보세요.","pairs":[{"l":"보들보들","r":"강아지 털을 만진다"},{"l":"쨍그랑","r":"유리컵이 깨진다"},{"l":"엉금엉금","r":"거북이가 긴다"}],"mis":"K2-1-u3-X18","explanation":["「보들보들」은 「강아지 털을 만진다」에 어울려요.","「쨍그랑」은 「유리컵이 깨진다」에 어울려요.","「엉금엉금」은 「거북이가 긴다」에 어울려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#15','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C11',2,'mc','auto','솔방울을 관찰할 때 살펴볼 점으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X17']::text[],false,'{"seq":15,"concept":"K2-1-u3-C11","difficulty":2,"kind":"mc","stem":"솔방울을 관찰할 때 살펴볼 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"겉면의 촉감","correct":true},{"t":"솔방울의 가격","mis":"K2-1-u3-X17"},{"t":"주운 사람 이름","mis":"K2-1-u3-X17"}],"explanation":["촉감은 손으로 만져 알 수 있어요.","솔방울의 가격·주운 사람 이름은 관찰해서 알 수 없어요.","눈·코·손으로 알 수 있는 것을 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#16','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C8',2,'mc','auto','도윤이의 하루예요. 일기 글감으로 가장 알맞은 일은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#17','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C2',3,'error','auto','「작은 다람쥐가 빨간 도토리를 냠냠 먹었다.」에서 꾸며 주는 말과 꾸밈을 받는 말을 이었어요. 잘못 이은 친구는 누구인가요?',ARRAY['K2-1-u3-X02','K2-1-u3-X19']::text[],false,'{"seq":17,"concept":"K2-1-u3-C2","difficulty":3,"kind":"error","stem":"「작은 다람쥐가 빨간 도토리를 냠냠 먹었다.」에서 꾸며 주는 말과 꾸밈을 받는 말을 이었어요. 잘못 이은 친구는 누구인가요?","options":[{"t":"민호 — 「빨간 → 다람쥐」","correct":true,"mis_target":"K2-1-u3-X02"},{"t":"서아 — 「작은 → 다람쥐」","mis":"K2-1-u3-X19"},{"t":"은솔 — 「냠냠 → 먹었다」","mis":"K2-1-u3-X19"}],"explanation":["「빨간」은 도토리를 꾸며요.","다른 두 친구는 바르게 이었어요.","꾸며 주는 말을 바로 뒤의 말에 붙여 읽어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#18','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C7',3,'mc','auto','글을 읽고 답해 보세요. 이 일기에서 빠진 것은 어느 것인가요?',ARRAY['K2-1-u3-X09']::text[],false,'{"seq":18,"concept":"K2-1-u3-C7","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 이 일기에서 빠진 것은 어느 것인가요?","options":[{"t":"제목","correct":true},{"t":"날짜·요일·날씨","mis":"K2-1-u3-X09"},{"t":"생각이나 느낌","mis":"K2-1-u3-X09"}],"explanation":["지후는 날짜 다음에 쓸 제목을 빠뜨렸어요.","다른 두 가지는 일기에 들어 있어요.","「빠진 것」을 묻는 물음 — 네 손가락을 접으며 확인해요."],"asset":{"type":"passage","lines":["7월 3일 수요일, 후덥지근하게 흐린 날","오후에 동생과 놀이터에서 물총놀이를 했다.","시원한 물줄기가 쏴 하고 뿜어져 나왔다.","옷이 흠뻑 젖었지만 깔깔 웃을 만큼 신났다."],"title":"지후의 일기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#19','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C4',3,'mc','auto','겨울 아침 모습을 쓴 문장 가운데 어울리지 않는 꾸며 주는 말이 들어간 것은 어느 것인가요?',ARRAY['K2-1-u3-X19']::text[],false,'{"seq":19,"concept":"K2-1-u3-C4","difficulty":3,"kind":"mc","stem":"겨울 아침 모습을 쓴 문장 가운데 어울리지 않는 꾸며 주는 말이 들어간 것은 어느 것인가요?","options":[{"t":"「뜨거운 눈이 펑펑 내린다.」","correct":true},{"t":"「하얀 눈이 소복소복 쌓였다.」","mis":"K2-1-u3-X19"},{"t":"「차가운 바람이 쌩쌩 분다.」","mis":"K2-1-u3-X19"}],"explanation":["눈은 뜨겁지 않아요.","다른 두 문장은 모습에 어울리는 말을 넣었어요.","「어울리지 않는」을 묻는 물음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#20','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C9',3,'error','auto','「운동회에서 이어달리기」가 글감이에요. 제목을 알맞지 않게 지은 친구는 누구인가요?',ARRAY['K2-1-u3-X14','K2-1-u3-X19']::text[],false,'{"seq":20,"concept":"K2-1-u3-C9","difficulty":3,"kind":"error","stem":"「운동회에서 이어달리기」가 글감이에요. 제목을 알맞지 않게 지은 친구는 누구인가요?","options":[{"t":"지우 — 「재미」","correct":true,"mis_target":"K2-1-u3-X14"},{"t":"하준 — 「운동회 이어달리기」","mis":"K2-1-u3-X19"},{"t":"다은 — 「바통을 넘겨라」","mis":"K2-1-u3-X19"}],"explanation":["「재미」만으로는 무슨 일인지 알 수 없어요.","제목에 겪은 일이 드러나야 내용을 알 수 있어요.","다른 두 친구는 내용이 드러나게 지었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#21','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C6',3,'mc','auto','글을 읽고 답해 보세요. 「올록볼록」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X08']::text[],false,'{"seq":21,"concept":"K2-1-u3-C6","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 「올록볼록」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"겉면이 고르지 않게 높고 낮은 모양","correct":true},{"t":"둥글게 감으며 도는 모양","mis":"K2-1-u3-X08"},{"t":"길게 곧게 뻗는 모양","mis":"K2-1-u3-X08"}],"explanation":["땅콩 껍데기가 올록볼록해서 만지면 울퉁불퉁하다고 했어요.","다른 뜻은 다른 낱말의 뜻이에요.","낱말을 소리 내어 읽으며 모양을 떠올려요."],"asset":{"type":"passage","lines":["완두는 덩굴손이 있는 식물이에요.","덩굴손은 막대를 빙글빙글 감으며 쭉쭉 뻗어 가요.","꼬투리 속에는 동글동글한 완두콩이 나란히 들어 있어요.","땅콩 껍데기는 겉이 올록볼록해서 만지면 울퉁불퉁해요."],"title":"덩굴손과 꼬투리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#22','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C12',3,'mc','auto','흉내 내는 말 가운데 느낌을 흉내 낸 말이 아닌 것은 어느 것인가요?',ARRAY['K2-1-u3-X19']::text[],false,'{"seq":22,"concept":"K2-1-u3-C12","difficulty":3,"kind":"mc","stem":"흉내 내는 말 가운데 느낌을 흉내 낸 말이 아닌 것은 어느 것인가요?","options":[{"t":"빙글빙글","correct":true},{"t":"보들보들","mis":"K2-1-u3-X19"},{"t":"찐득찐득","mis":"K2-1-u3-X19"}],"explanation":["「빙글빙글」은 도는 모양을 흉내 낸 말이에요.","다른 두 말은 느낌을 흉내 낸 말이에요.","「아닌 것」을 묻는 물음 — 따라 하며 무엇이 떠오르는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#23','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C10',4,'mc','auto','두 친구가 같은 날 「눈 오는 날」 일기를 썼어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#24','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C5',4,'essay','teacher','「아이가 웃는다.」에 꾸며 주는 말을 두 개 넣어 더 생생한 문장으로 고쳐 쓰고, 넣은 꾸며 주는 말을 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u3-C5","difficulty":4,"kind":"essay","stem":"「아이가 웃는다.」에 꾸며 주는 말을 두 개 넣어 더 생생한 문장으로 고쳐 쓰고, 넣은 꾸며 주는 말을 써 보세요.","answer_guide":{"answer":"예: 작은 아이가 방긋방긋 웃는다. (작은, 방긋방긋)","scoring_points":["꾸며 주는 말을 두 개 넣었는가","넣은 말이 대상과 모습에 어울리는가","문장을 끝까지 쓰고 마침표를 찍었는가"]},"explanation":["꾸며 주는 말 두 개.","어울림.","끝까지 쓴 문장."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_c#25','kor',2,1,'u3','','g2_1_kor_u3_review_c','unit_review','K2-1-u3-C10',4,'essay','teacher','다음 일기를 언제·어디서·누구와, 그리고 그때의 생각이나 느낌이 드러나게 꾸며 주는 말을 넣어 고쳐 써 보세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_d#1','kor',2,1,'u3','','g2_1_kor_u3_review_d','unit_review','K2-1-u3-C1',1,'mc','auto','다음 문장에서 꾸며 주는 말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_d#2','kor',2,1,'u3','','g2_1_kor_u3_review_d','unit_review','K2-1-u3-C2',1,'mc','auto','「커다란 배가 천천히 간다.」에서 「커다란」이 꾸며 주는 말은 어느 것인가요?',ARRAY['K2-1-u3-X02']::text[],false,'{"seq":2,"concept":"K2-1-u3-C2","difficulty":1,"kind":"mc","stem":"「커다란 배가 천천히 간다.」에서 「커다란」이 꾸며 주는 말은 어느 것인가요?","options":[{"t":"배가","correct":true},{"t":"천천히","mis":"K2-1-u3-X02"},{"t":"간다","mis":"K2-1-u3-X02"}],"explanation":["「커다란」은 배가 어떤지 알려 줘요.","꾸며 주는 말을 뒤의 말에 붙여 읽어 보면 짝이 보여요.","「커다란 배가」처럼 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_d#3','kor',2,1,'u3','','g2_1_kor_u3_review_d','unit_review','K2-1-u3-C4',1,'mc','auto','눈사람 그림을 보고 꾸며 주는 말을 넣으려고 해요. 가장 어울리는 말은 어느 것인가요?',ARRAY['K2-1-u3-X04']::text[],false,'{"seq":3,"concept":"K2-1-u3-C4","difficulty":1,"kind":"mc","stem":"눈사람 그림을 보고 꾸며 주는 말을 넣으려고 해요. 가장 어울리는 말은 어느 것인가요?","options":[{"t":"하얀","correct":true},{"t":"뜨거운","mis":"K2-1-u3-X04"},{"t":"빨간","mis":"K2-1-u3-X04"}],"explanation":["눈사람의 색에는 「하얀」이 어울려요.","다른 말은 눈사람의 모습과 어울리지 않아요.","대상을 잘 살펴 색·모양·움직임에 맞는 말을 골라요."],"asset":{"type":"scene","icon":"⛄"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_d#4','kor',2,1,'u3','','g2_1_kor_u3_review_d','unit_review','K2-1-u3-C7',1,'mc','auto','일기에 겪은 일을 쓴 다음에 쓰는 것은 어느 것인가요?',ARRAY['K2-1-u3-X10','K2-1-u3-X11']::text[],false,'{"seq":4,"concept":"K2-1-u3-C7","difficulty":1,"kind":"mc","stem":"일기에 겪은 일을 쓴 다음에 쓰는 것은 어느 것인가요?","options":[{"t":"그 일에 대한 생각이나 느낌","correct":true},{"t":"날짜와 날씨","mis":"K2-1-u3-X10"},{"t":"준비물 목록","mis":"K2-1-u3-X11"}],"explanation":["겪은 일 다음에 생각이나 느낌을 써요.","다른 것은 일기에 맞지 않아요.","일기는 겪은 일과 생각이나 느낌을 담는 글이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_d#5','kor',2,1,'u3','','g2_1_kor_u3_review_d','unit_review','K2-1-u3-C8',1,'mc','auto','하루에 겪은 일로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X12']::text[],false,'{"seq":5,"concept":"K2-1-u3-C8","difficulty":1,"kind":"mc","stem":"하루에 겪은 일로 알맞은 것은 어느 것인가요?","options":[{"t":"텃밭에서 상추를 땄다","correct":true},{"t":"바구니","mis":"K2-1-u3-X12"},{"t":"즐거움","mis":"K2-1-u3-X12"}],"explanation":["「텃밭에서 상추를 땄다」는 내가 겪은 일이에요.","바구니는 물건, 즐거움은 느낌을 나타내는 낱말이에요.","「~했다·봤다·들었다」로 말이 되는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_d#6','kor',2,1,'u3','','g2_1_kor_u3_review_d','unit_review','K2-1-u3-C9',1,'mc','auto','「처음 바다에서 수영한」 일을 쓴 일기의 제목으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X14']::text[],false,'{"seq":6,"concept":"K2-1-u3-C9","difficulty":1,"kind":"mc","stem":"「처음 바다에서 수영한」 일을 쓴 일기의 제목으로 알맞은 것은 어느 것인가요?","options":[{"t":"바다에서 처음 수영한 날","correct":true},{"t":"여름 방학","mis":"K2-1-u3-X14"},{"t":"물","mis":"K2-1-u3-X14"}],"explanation":["「바다에서 처음 수영한 날」만 보아도 무슨 일인지 알 수 있어요.","「여름 방학」, 「물」로는 내용을 알 수 없어요.","제목은 내용을 한눈에 보여 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_d#7','kor',2,1,'u3','','g2_1_kor_u3_review_d','unit_review','K2-1-u3-C12',1,'mc','auto','시냇물이 흐르는 소리를 흉내 낸 말은 어느 것인가요?',ARRAY['K2-1-u3-X18']::text[],false,'{"seq":7,"concept":"K2-1-u3-C12","difficulty":1,"kind":"mc","stem":"시냇물이 흐르는 소리를 흉내 낸 말은 어느 것인가요?","options":[{"t":"졸졸","correct":true},{"t":"시냇물","mis":"K2-1-u3-X18"},{"t":"흐른다","mis":"K2-1-u3-X18"}],"explanation":["「졸졸」은 물이 흐르는 소리를 흉내 낸 말이에요.","시냇물·흐른다는 흉내 내는 말이 아니에요.","따라 했을 때 모습·소리·느낌이 떠오르면 흉내 내는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_d#8','kor',2,1,'u3','','g2_1_kor_u3_review_d','unit_review','K2-1-u3-C11',1,'mc','auto','강낭콩이 자라는 모습을 날마다 살펴 쓰기에 알맞은 일기는 어느 것인가요?',ARRAY['K2-1-u3-X17']::text[],false,'{"seq":8,"concept":"K2-1-u3-C11","difficulty":1,"kind":"mc","stem":"강낭콩이 자라는 모습을 날마다 살펴 쓰기에 알맞은 일기는 어느 것인가요?","options":[{"t":"관찰 일기","correct":true},{"t":"요리 일기","mis":"K2-1-u3-X17"},{"t":"그림 없는 편지","mis":"K2-1-u3-X17"}],"explanation":["자라는 모습을 살펴 쓰는 일기는 관찰 일기예요.","다른 일기는 쓰는 내용이 달라요.","관찰 일기·요리 일기·그림 일기의 쓰는 내용을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_d#9','kor',2,1,'u3','','g2_1_kor_u3_review_d','unit_review','K2-1-u3-C3',2,'ox','auto','「꽃이 피었다.」보다 「예쁜 꽃이 활짝 피었다.」가 더 생생하게 느껴져요.',ARRAY['K2-1-u3-X03']::text[],false,'{"seq":9,"concept":"K2-1-u3-C3","difficulty":2,"kind":"ox","stem":"「꽃이 피었다.」보다 「예쁜 꽃이 활짝 피었다.」가 더 생생하게 느껴져요.","answer":"O","reason_options":[{"t":"꾸며 주는 말이 모습을 그려 주니까","correct":true},{"t":"글자가 많을수록 좋은 문장이니까","mis":"K2-1-u3-X03"}],"mis":"K2-1-u3-X03","explanation":["「예쁜」·「활짝」이 꽃의 모습을 보여 줘요.","길어서가 아니라 모습이 떠올라서 생생한 거예요.","꾸며 주는 말은 문장을 자세하게 해 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_d#10','kor',2,1,'u3','','g2_1_kor_u3_review_d','unit_review','K2-1-u3-C5',2,'mc','auto','꾸며 주는 말을 넣어 문장을 바르게 쓴 것은 어느 것인가요?',ARRAY['K2-1-u3-X06','K2-1-u3-X05']::text[],false,'{"seq":10,"concept":"K2-1-u3-C5","difficulty":2,"kind":"mc","stem":"꾸며 주는 말을 넣어 문장을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"귀여운 강아지가 신나게 달린다.","correct":true},{"t":"귀여운 강아지.","mis":"K2-1-u3-X06"},{"t":"귀여운 강아지가 딱딱하게 새콤하게 달린다.","mis":"K2-1-u3-X05"}],"explanation":["「귀여운 강아지가 신나게 달린다.」는 어울리는 꾸며 주는 말을 넣어 끝까지 쓴 문장이에요.","「귀여운 강아지.」는 끝맺지 않았어요.","「귀여운 강아지가 딱딱하게 새콤하게 달린다.」는 어울리지 않는 말이 들어갔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_d#11','kor',2,1,'u3','','g2_1_kor_u3_review_d','unit_review','K2-1-u3-C6',2,'mc','auto','글을 읽고 답해 보세요. 봄비가 내리자 일어난 일은 무엇인가요?',ARRAY['K2-1-u3-X07']::text[],false,'{"seq":11,"concept":"K2-1-u3-C6","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 봄비가 내리자 일어난 일은 무엇인가요?","options":[{"t":"조그만 새싹이 쏙 돋아났어요","correct":true},{"t":"까만 씨앗이 박혔어요","mis":"K2-1-u3-X07"},{"t":"꽃이 활짝 피었어요","mis":"K2-1-u3-X07"}],"explanation":["「봄비가 내리자 조그만 새싹이 쏙 돋아났어요.」라고 했어요.","다른 것은 글에 없거나 차례가 달라요.","글에서 찾아 손가락으로 짚어 봐요."],"asset":{"type":"passage","lines":["작은 씨앗이 흙 속에서 잠을 자요.","봄비가 내리자 조그만 새싹이 쏙 돋아났어요.","줄기는 하루하루 무럭무럭 자랐어요.","여름이 되자 커다란 해바라기가 활짝 피었어요.","가을에는 꽃 가운데에 까만 씨앗이 촘촘히 박혔어요."],"title":"해바라기가 자라요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_d#12','kor',2,1,'u3','','g2_1_kor_u3_review_d','unit_review','K2-1-u3-C7',2,'mc','auto','일기를 쓰는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X10']::text[],false,'{"seq":12,"concept":"K2-1-u3-C7","difficulty":2,"kind":"mc","stem":"일기를 쓰는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"날짜·날씨 → 제목 → 겪은 일 → 생각이나 느낌","correct":true},{"t":"제목 → 생각이나 느낌 → 날짜·날씨 → 겪은 일","mis":"K2-1-u3-X10"},{"t":"날짜·날씨 → 겪은 일 → 제목 → 생각이나 느낌","mis":"K2-1-u3-X10"}],"explanation":["날짜·날씨가 맨 처음, 그다음 제목을 써요.","이어서 겪은 일, 마지막에 생각이나 느낌을 써요.","차례를 지키면 읽기 쉬워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_d#13','kor',2,1,'u3','','g2_1_kor_u3_review_d','unit_review','K2-1-u3-C10',2,'mc','auto','「강아지 산책」을 겪은 뒤 쓴 문장 가운데 생각이나 느낌이 드러난 것은 어느 것인가요?',ARRAY['K2-1-u3-X15','K2-1-u3-X16']::text[],false,'{"seq":13,"concept":"K2-1-u3-C10","difficulty":2,"kind":"mc","stem":"「강아지 산책」을 겪은 뒤 쓴 문장 가운데 생각이나 느낌이 드러난 것은 어느 것인가요?","options":[{"t":"강아지가 꼬리를 흔들며 따라와서 무척 행복했다.","correct":true},{"t":"강아지와 산책했다.","mis":"K2-1-u3-X15"},{"t":"걸었다.","mis":"K2-1-u3-X16"}],"explanation":["「강아지가 꼬리를 흔들며 따라와서 무척 행복했다」에 그때의 마음이 담겨 있어요.","다른 문장은 한 일만 쓰거나 무슨 일인지 드러나지 않아요.","겪은 일에 솔직한 느낌을 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_d#14','kor',2,1,'u3','','g2_1_kor_u3_review_d','unit_review','K2-1-u3-C12',2,'match','auto','흉내 내는 말과 어울리는 모습을 이어 보세요.','{}'::text[],false,'{"seq":14,"concept":"K2-1-u3-C12","difficulty":2,"kind":"match","stem":"흉내 내는 말과 어울리는 모습을 이어 보세요.","pairs":[{"l":"펑펑","r":"함박눈이 내린다"},{"l":"살랑살랑","r":"잎이 흔들린다"},{"l":"보글보글","r":"찌개가 끓는다"}],"mis":"K2-1-u3-X18","explanation":["「펑펑」은 「함박눈이 내린다」에 어울려요.","「살랑살랑」은 「잎이 흔들린다」에 어울려요.","「보글보글」은 「찌개가 끓는다」에 어울려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_d#15','kor',2,1,'u3','','g2_1_kor_u3_review_d','unit_review','K2-1-u3-C11',2,'mc','auto','방울토마토를 관찰할 때 살펴볼 점으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X17']::text[],false,'{"seq":15,"concept":"K2-1-u3-C11","difficulty":2,"kind":"mc","stem":"방울토마토를 관찰할 때 살펴볼 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"열매의 색과 개수","correct":true},{"t":"토마토를 키운 회사","mis":"K2-1-u3-X17"},{"t":"화분의 값","mis":"K2-1-u3-X17"}],"explanation":["색과 개수는 눈으로 살펴 알 수 있어요.","토마토를 키운 회사·화분의 값은 관찰해서 알 수 없어요.","눈·코·손으로 알 수 있는 것을 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_d#16','kor',2,1,'u3','','g2_1_kor_u3_review_d','unit_review','K2-1-u3-C8',2,'mc','auto','예린이의 하루예요. 일기 글감으로 가장 알맞은 일은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_d#17','kor',2,1,'u3','','g2_1_kor_u3_review_d','unit_review','K2-1-u3-C2',3,'error','auto','「하얀 구름이 파란 하늘에 둥실둥실 떠간다.」에서 꾸며 주는 말과 꾸밈을 받는 말을 이었어요. 잘못 이은 친구는 누구인가요?',ARRAY['K2-1-u3-X02','K2-1-u3-X19']::text[],false,'{"seq":17,"concept":"K2-1-u3-C2","difficulty":3,"kind":"error","stem":"「하얀 구름이 파란 하늘에 둥실둥실 떠간다.」에서 꾸며 주는 말과 꾸밈을 받는 말을 이었어요. 잘못 이은 친구는 누구인가요?","options":[{"t":"태민 — 「둥실둥실 → 하늘」","correct":true,"mis_target":"K2-1-u3-X02"},{"t":"아린 — 「하얀 → 구름」","mis":"K2-1-u3-X19"},{"t":"소율 — 「파란 → 하늘」","mis":"K2-1-u3-X19"}],"explanation":["「둥실둥실」은 떠간다를 꾸며요.","다른 두 친구는 바르게 이었어요.","꾸며 주는 말을 바로 뒤의 말에 붙여 읽어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_d#18','kor',2,1,'u3','','g2_1_kor_u3_review_d','unit_review','K2-1-u3-C7',3,'mc','auto','글을 읽고 답해 보세요. 이 일기에서 빠진 것은 어느 것인가요?',ARRAY['K2-1-u3-X09']::text[],false,'{"seq":18,"concept":"K2-1-u3-C7","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 이 일기에서 빠진 것은 어느 것인가요?","options":[{"t":"생각이나 느낌","correct":true},{"t":"제목","mis":"K2-1-u3-X09"},{"t":"날짜·요일·날씨","mis":"K2-1-u3-X09"}],"explanation":["아린이는 공원의 모습은 생생하게 썼지만 그때의 마음을 쓰지 않았어요.","다른 두 가지는 일기에 들어 있어요.","「빠진 것」을 묻는 물음 — 네 손가락을 접으며 확인해요."],"asset":{"type":"passage","lines":["11월 2일 일요일, 하늘이 높고 파란 날","제목: 가을 소풍","아침에 가족과 공원에 갔다.","노랗게 물든 은행잎이 바람에 팔랑팔랑 떨어졌다."],"title":"아린이의 일기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_d#19','kor',2,1,'u3','','g2_1_kor_u3_review_d','unit_review','K2-1-u3-C4',3,'mc','auto','부엌 모습을 쓴 문장 가운데 어울리지 않는 꾸며 주는 말이 들어간 것은 어느 것인가요?',ARRAY['K2-1-u3-X19']::text[],false,'{"seq":19,"concept":"K2-1-u3-C4","difficulty":3,"kind":"mc","stem":"부엌 모습을 쓴 문장 가운데 어울리지 않는 꾸며 주는 말이 들어간 것은 어느 것인가요?","options":[{"t":"「시끄러운 사과가 놓여 있다.」","correct":true},{"t":"「보글보글 찌개가 끓는다.」","mis":"K2-1-u3-X19"},{"t":"「고소한 냄새가 솔솔 난다.」","mis":"K2-1-u3-X19"}],"explanation":["사과는 소리를 내지 않아요.","다른 두 문장은 모습에 어울리는 말을 넣었어요.","「어울리지 않는」을 묻는 물음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_d#20','kor',2,1,'u3','','g2_1_kor_u3_review_d','unit_review','K2-1-u3-C9',3,'error','auto','「할아버지와 밤 줍기」가 글감이에요. 제목을 알맞지 않게 지은 친구는 누구인가요?',ARRAY['K2-1-u3-X14','K2-1-u3-X19']::text[],false,'{"seq":20,"concept":"K2-1-u3-C9","difficulty":3,"kind":"error","stem":"「할아버지와 밤 줍기」가 글감이에요. 제목을 알맞지 않게 지은 친구는 누구인가요?","options":[{"t":"시우 — 「가을 일기」","correct":true,"mis_target":"K2-1-u3-X14"},{"t":"예린 — 「할아버지와 주운 밤」","mis":"K2-1-u3-X19"},{"t":"로아 — 「뾰족뾰족 밤송이」","mis":"K2-1-u3-X19"}],"explanation":["「가을 일기」만으로는 무슨 일인지 알 수 없어요.","제목에 겪은 일이 드러나야 내용을 알 수 있어요.","다른 두 친구는 내용이 드러나게 지었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_d#21','kor',2,1,'u3','','g2_1_kor_u3_review_d','unit_review','K2-1-u3-C6',3,'mc','auto','글을 읽고 답해 보세요. 「빙글빙글」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u3-X08']::text[],false,'{"seq":21,"concept":"K2-1-u3-C6","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 「빙글빙글」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"둥글게 감거나 도는 모양","correct":true},{"t":"겉면이 높고 낮은 모양","mis":"K2-1-u3-X08"},{"t":"힘차게 잘 자라는 모양","mis":"K2-1-u3-X08"}],"explanation":["덩굴손이 막대를 빙글빙글 감으며 뻗어 간다고 했어요.","다른 뜻은 다른 낱말의 뜻이에요.","낱말을 소리 내어 읽으며 모양을 떠올려요."],"asset":{"type":"passage","lines":["완두는 덩굴손이 있는 식물이에요.","덩굴손은 막대를 빙글빙글 감으며 쭉쭉 뻗어 가요.","꼬투리 속에는 동글동글한 완두콩이 나란히 들어 있어요.","땅콩 껍데기는 겉이 올록볼록해서 만지면 울퉁불퉁해요."],"title":"덩굴손과 꼬투리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_d#22','kor',2,1,'u3','','g2_1_kor_u3_review_d','unit_review','K2-1-u3-C12',3,'mc','auto','흉내 내는 말 가운데 소리를 흉내 낸 말이 아닌 것은 어느 것인가요?',ARRAY['K2-1-u3-X19']::text[],false,'{"seq":22,"concept":"K2-1-u3-C12","difficulty":3,"kind":"mc","stem":"흉내 내는 말 가운데 소리를 흉내 낸 말이 아닌 것은 어느 것인가요?","options":[{"t":"엉금엉금","correct":true},{"t":"멍멍","mis":"K2-1-u3-X19"},{"t":"보글보글","mis":"K2-1-u3-X19"}],"explanation":["「엉금엉금」은 기어가는 모양을 흉내 낸 말이에요.","다른 두 말은 소리를 흉내 낸 말이에요.","「아닌 것」을 묻는 물음 — 따라 하며 무엇이 떠오르는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_d#23','kor',2,1,'u3','','g2_1_kor_u3_review_d','unit_review','K2-1-u3-C10',4,'mc','auto','두 친구가 같은 날 「텃밭」 일기를 썼어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_d#24','kor',2,1,'u3','','g2_1_kor_u3_review_d','unit_review','K2-1-u3-C5',4,'essay','teacher','「배가 간다.」에 꾸며 주는 말을 두 개 넣어 더 생생한 문장으로 고쳐 쓰고, 넣은 꾸며 주는 말을 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u3-C5","difficulty":4,"kind":"essay","stem":"「배가 간다.」에 꾸며 주는 말을 두 개 넣어 더 생생한 문장으로 고쳐 쓰고, 넣은 꾸며 주는 말을 써 보세요.","answer_guide":{"answer":"예: 커다란 배가 바다 위를 천천히 간다. (커다란, 천천히)","scoring_points":["꾸며 주는 말을 두 개 넣었는가","넣은 말이 대상과 모습에 어울리는가","문장을 끝까지 쓰고 마침표를 찍었는가"]},"explanation":["꾸며 주는 말 두 개.","어울림.","끝까지 쓴 문장."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u3_review_d#25','kor',2,1,'u3','','g2_1_kor_u3_review_d','unit_review','K2-1-u3-C10',4,'essay','teacher','다음 일기를 언제·어디서·누구와, 그리고 그때의 생각이나 느낌이 드러나게 꾸며 주는 말을 넣어 고쳐 써 보세요.
